import spidev
import time
import signal
import sys

# SPI configuration
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 50000
SPI_MODE = 0b00
SPI_BITS_PER_WORD = 8

# Calibration factor: 5.0 V / 1023 counts for a 10-bit ADC
ADC_MAX_COUNTS = 1023
VOLTAGE_PER_COUNT = 5.0 / ADC_MAX_COUNTS


class LoadCellReader:
    """Reads analog weight data from an MCP3002 ADC over SPI on a Raspberry Pi."""

    def __init__(self, bus=SPI_BUS, device=SPI_DEVICE, max_speed_hz=SPI_MAX_SPEED_HZ):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(bus, device)
            self.spi.max_speed_hz = max_speed_hz
            self.spi.mode = SPI_MODE
            self.spi.bits_per_word = SPI_BITS_PER_WORD
        except OSError as e:
            raise RuntimeError(f"Failed to open SPI device /dev/spidev{bus}.{device}: {e}") from e

    def send_spi_command(self, data):
        """Send a 3-byte command to the MCP3002 and return the 3-byte response."""
        try:
            return self.spi.xfer2(data)
        except OSError as e:
            raise RuntimeError(f"SPI transfer failed: {e}") from e

    @staticmethod
    def extract_10bit(response):
        """Extract a 10-bit value from the 3-byte SPI response."""
        if not isinstance(response, (list, tuple)) or len(response) < 3:
            raise ValueError("SPI response must be a list/tuple of at least 3 bytes")
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        """Read raw 10-bit data from the MCP3002."""
        command = [0x01, 0x80, 0x00]
        response = self.send_spi_command(command)
        return self.extract_10bit(response)

    def convert_to_weight(self, raw_data):
        """Convert raw ADC counts to weight in kilograms."""
        return float(raw_data) * VOLTAGE_PER_COUNT

    def close(self):
        """Close the SPI connection."""
        try:
            self.spi.close()
        except Exception:
            pass


def main():
    reader = None
    try:
        reader = LoadCellReader()
        print("Load cell reader initialized. Press Ctrl+C to stop.")

        while True:
            try:
                raw_data = reader.read_raw_data()
                weight = reader.convert_to_weight(raw_data)
                print(f"Weight: {weight:.2f} kg")
            except (RuntimeError, ValueError) as e:
                print(f"Error reading weight: {e}", file=sys.stderr)
            time.sleep(0.5)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except RuntimeError as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        if reader is not None:
            reader.close()
        print("SPI connection closed.")


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, exiting.")
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGTERM, _signal_handler)
    main()

