import time
import datetime
import csv
import os
import signal
import sys
import spidev
import RPi.GPIO as GPIO
import adafruit_dht
import board

# Constants
DHT_PIN = 4
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
ADC_CHANNELS = [0, 1]
CALIBRATION_DURATION = 60
LOGGING_INTERVAL = 60
MOVING_AVERAGE_WINDOW = 5
TEMPERATURE_MIN = -20.0
TEMPERATURE_MAX = 50.0
HUMIDITY_MIN = 0.0
HUMIDITY_MAX = 100.0
CSV_FILE = "gas_data.csv"
ERROR_LOG = "error.log"

# Global state
running = True
spi = None
dht_device = None
sensor_data = {
    'temperature': {'readings': [], 'calibration_readings': []},
    'humidity': {'readings': [], 'calibration_readings': []},
    'gas_sensor_1': {'readings': [], 'calibration_readings': []},
    'gas_sensor_2': {'readings': [], 'calibration_readings': []},
}

def log_error(message):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ERROR_LOG, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}")

def read_mcp3008(channel):
    if not 0 <= channel <= 7:
        log_error(f"Invalid ADC channel: {channel}")
        return None
    try:
        # MCP3008 single-ended read: start bit, config byte, padding
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        log_error(f"SPI read error on channel {channel}: {e}")
        return None

def read_dht22():
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            log_error("DHT22 returned None values")
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        log_error(f"DHT22 read error (retry): {e}")
        return None, None
    except Exception as e:
        log_error(f"Unexpected DHT22 error: {e}")
        return None, None

def moving_average(data, window_size):
    if len(data) < window_size:
        return sum(data) / len(data) if data else 0.0
    return sum(data[-window_size:]) / window_size

def validate_temperature(temp):
    return TEMPERATURE_MIN <= temp <= TEMPERATURE_MAX

def validate_humidity(hum):
    return HUMIDITY_MIN <= hum <= HUMIDITY_MAX

def calibrate_sensors():
    print("Calibrating sensors for 60 seconds...")
    start_time = time.time()
    while time.time() - start_time < CALIBRATION_DURATION and running:
        temp, hum = read_dht22()
        if temp is not None and hum is not None:
            sensor_data['temperature']['calibration_readings'].append(temp)
            sensor_data['humidity']['calibration_readings'].append(hum)
        gas1 = read_mcp3008(ADC_CHANNELS[0])
        gas2 = read_mcp3008(ADC_CHANNELS[1])
        if gas1 is not None:
            sensor_data['gas_sensor_1']['calibration_readings'].append(gas1)
        if gas2 is not None:
            sensor_data['gas_sensor_2']['calibration_readings'].append(gas2)
        time.sleep(1)
    print("Calibration complete.")

def initialize_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        print("SPI initialized successfully.")
        return True
    except Exception as e:
        log_error(f"Failed to initialize SPI: {e}")
        return False

def initialize_dht22():
    global dht_device
    try:
        dht_device = adafruit_dht.DHT22(board.D4)
        print("DHT22 initialized successfully.")
        return True
    except Exception as e:
        log_error(f"Failed to initialize DHT22: {e}")
        return False

def cleanup():
    global spi, dht_device
    print("Cleaning up resources...")
    if spi:
        try:
            spi.close()
        except Exception:
            pass
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    print("Cleanup complete.")

def signal_handler(sig, frame):
    global running
    print(f"Signal {sig} received, shutting down...")
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.IN)
    except Exception as e:
        log_error(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    if not initialize_spi():
        sys.exit(1)

    if not initialize_dht22():
        cleanup()
        sys.exit(1)

    calibrate_sensors()

    if not os.path.exists(CSV_FILE):
        try:
            with open(CSV_FILE, 'w', newline='') as f:
                writer = csv.writer(f)
                writer.writerow(['Timestamp', 'Temperature_C', 'Humidity_%', 'Gas_Sensor_1', 'Gas_Sensor_2'])
        except Exception as e:
            log_error(f"Failed to create CSV file: {e}")
            cleanup()
            sys.exit(1)

    print("Starting data logging...")
    while running:
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        temp, hum = read_dht22()
        gas1 = read_mcp3008(ADC_CHANNELS[0])
        gas2 = read_mcp3008(ADC_CHANNELS[1])

        if temp is not None and hum is not None:
            sensor_data['temperature']['readings'].append(temp)
            sensor_data['humidity']['readings'].append(hum)
            temp_filtered = moving_average(sensor_data['temperature']['readings'], MOVING_AVERAGE_WINDOW)
            hum_filtered = moving_average(sensor_data['humidity']['readings'], MOVING_AVERAGE_WINDOW)
            if not validate_temperature(temp_filtered):
                log_error(f"Temperature out of range: {temp_filtered}")
                temp_filtered = None
            if not validate_humidity(hum_filtered):
                log_error(f"Humidity out of range: {hum_filtered}")
                hum_filtered = None
        else:
            temp_filtered = None
            hum_filtered = None

        if gas1 is not None:
            sensor_data['gas_sensor_1']['readings'].append(gas1)
            gas1_filtered = moving_average(sensor_data['gas_sensor_1']['readings'], MOVING_AVERAGE_WINDOW)
        else:
            gas1_filtered = None

        if gas2 is not None:
            sensor_data['gas_sensor_2']['readings'].append(gas2)
            gas2_filtered = moving_average(sensor_data['gas_sensor_2']['readings'], MOVING_AVERAGE_WINDOW)
        else:
            gas2_filtered = None

        if temp_filtered is not None and hum_filtered is not None and gas1_filtered is not None and gas2_filtered is not None:
            try:
                with open(CSV_FILE, 'a', newline='') as f:
                    writer = csv.writer(f)
                    writer.writerow([timestamp, f"{temp_filtered:.2f}", f"{hum_filtered:.2f}", f"{gas1_filtered}", f"{gas2_filtered}"])
            except Exception as e:
                log_error(f"Failed to write to CSV: {e}")
        else:
            log_error("Incomplete sensor data, skipping log entry.")

        for _ in range(LOGGING_INTERVAL):
            if not running:
                break
            time.sleep(1)

    cleanup()

if __name__ == "__main__":
    main()

