import time
import signal
import sys
import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import Adafruit_ADS1x15
import pigpio

# Constants
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_MS0_PIN = 14
MOTOR_MS1_PIN = 15
ADC_ADDRESS = 0x48
ADC_GAIN = 1
ADC_CHANNEL = 0
PWM_FREQUENCY = 500
ADC_MAX_VOLTAGE = 3.3
DUTY_CYCLE_MAX = 255
SLEEP_DURATION = 1

# Global resources for cleanup
pi = None
running = True


class MotorController:
    """Controls a stepper motor via pigpio for precise PWM control."""

    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise RuntimeError("pigpio daemon not running")
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self.microstep_resolution = "Full"
        self.direction = "CCW"
        self._set_pins()
        self._set_microstep_resolution(self.microstep_resolution)
        self._set_direction(self.direction)

    def _set_pins(self):
        for pin in (self.dir_pin, self.step_pin, self.ms0_pin, self.ms1_pin):
            self.pi.set_mode(pin, pigpio.OUTPUT)
            self.pi.write(pin, 0)

    def _set_microstep_resolution(self, resolution):
        mapping = {
            "Full": (0, 0),
            "Half": (1, 0),
            "1/4": (0, 1),
            "1/8": (1, 1),
        }
        if resolution not in mapping:
            raise ValueError(f"Invalid microstep resolution: {resolution}")
        self.pi.write(self.ms0_pin, mapping[resolution][0])
        self.pi.write(self.ms1_pin, mapping[resolution][1])

    def _set_direction(self, direction):
        if direction == "CW":
            self.pi.write(self.dir_pin, 1)
        elif direction == "CCW":
            self.pi.write(self.dir_pin, 0)
        else:
            raise ValueError(f"Invalid direction: {direction}")

    def set_pwm_duty_cycle(self, duty_cycle):
        if not 0 <= duty_cycle <= DUTY_CYCLE_MAX:
            raise ValueError(f"Duty cycle must be 0-{DUTY_CYCLE_MAX}")
        self.pi.set_PWM_frequency(self.step_pin, PWM_FREQUENCY)
        self.pi.set_PWM_dutycycle(self.step_pin, duty_cycle)

    def stop(self):
        self.pi.set_PWM_dutycycle(self.step_pin, 0)

    def close(self):
        self.stop()
        for pin in (self.dir_pin, self.step_pin, self.ms0_pin, self.ms1_pin):
            self.pi.set_mode(pin, pigpio.INPUT)
        self.pi.stop()


class SensorManager:
    """Manages LSM303 accelerometer and magnetometer readings."""

    def __init__(self, i2c_bus):
        self.i2c = i2c_bus
        self.accelerometer = None
        self.magnetometer = None
        self._initialize_sensors()

    def _initialize_sensors(self):
        try:
            self.accelerometer = adafruit_lsm303_accel.LSM303_Accel(self.i2c)
        except Exception as e:
            print(f"Error initializing accelerometer: {e}")
            self.accelerometer = None
        try:
            self.magnetometer = adafruit_lsm303dlh_mag.LSM303DLH_Mag(self.i2c)
        except Exception as e:
            print(f"Error initializing magnetometer: {e}")
            self.magnetometer = None

    def get_acceleration(self):
        if not self.accelerometer:
            return None
        try:
            return self.accelerometer.acceleration
        except Exception as e:
            print(f"Error reading acceleration: {e}")
            return None

    def get_magnetic_field(self):
        if not self.magnetometer:
            return None
