class MotorController:
    """Controls a stepper motor via pigpio for precise PWM control."""

    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise RuntimeError("pigpio daemon not running")
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self.microstep_resolution = "Full"
        self.direction = "CCW"
        self._set_pins()
        self._set_microstep_resolution(self.microstep_resolution)
        self._set_direction(self.direction)

    def _set_pins(self):
        for pin in (self.dir_pin, self.step_pin, self.ms0_pin, self.ms1_pin):
            self.pi.set_mode(pin, pigpio.OUTPUT)
            self.pi.write(pin, 0)

    def _set_microstep_resolution(self, resolution):
        mapping = {
            "Full": (0, 0),
            "Half": (1, 0),
            "1/4": (0, 1),
            "1/8": (1, 1),
        }
        if resolution not in mapping:
            raise ValueError(f"Invalid microstep resolution: {resolution}")
        self.pi.write(self.ms0_pin, mapping[resolution][0])
        self.pi.write(self.ms1_pin, mapping[resolution][1])

    def _set_direction(self, direction):
        if direction == "CW":
            self.pi.write(self.dir_pin, 1)
        elif direction == "CCW":
            self.pi.write(self.dir_pin, 0)
        else:
            raise ValueError(f"Invalid direction: {direction}")

