import time
import signal
import smbus2


class ADS1x15:
    """Minimal driver for the ADS1x15 (e.g. ADS1115) ADC over I2C using smbus2."""

    # Register addresses
    REG_CONVERSION = 0x00
    REG_CONFIG = 0x01

    # Config register bit fields
    CONFIG_OS_START = 0x8000
    CONFIG_MUX_OFFSET = 12
    CONFIG_PGA_OFFSET = 9
    CONFIG_MODE_SINGLE = 0x0100
    CONFIG_DR_128SPS = 0x0080
    CONFIG_CQUE_NONE = 0x0003

    # PGA values in mV
    PGA_VALUES = {
        6144, 4096, 2048, 1024, 512, 256,
    }

    def __init__(self, address=0x48, busnum=1):
        if address not in (0x48, 0x49, 0x4A, 0x4B):
            raise ValueError(f"Invalid ADS1x15 I2C address: 0x{address:02X}")
        if busnum < 0:
            raise ValueError("busnum must be a non-negative integer")

        self.address = address
        self._bus = None
        self._closed = False

        try:
            self._bus = smbus2.SMBus(busnum)
        except FileNotFoundError:
            raise RuntimeError(
                f"I2C bus {busnum} not found. Enable I2C with 'sudo raspi-config'."
            )
        except PermissionError:
            raise RuntimeError(
                f"Permission denied on I2C bus {busnum}. Run as root or add user to 'i2c' group."
            )
        except OSError as exc:
            raise RuntimeError(f"Failed to open I2C bus {busnum}: {exc}") from exc

    # ------------------------------------------------------------------
    # Resource management
    # ------------------------------------------------------------------
    def close(self):
        if self._closed:
            return
        self._closed = True
        if self._bus is not None:
            try:
                self._bus.close()
            except Exception:
                pass
            self._bus = None

    def __del__(self):
        self.close()

    # ------------------------------------------------------------------
    # Low-level I2C helpers
    # ------------------------------------------------------------------
    def _write_config(self, config_word):
        """Write a 16-bit config word to the ADS1x15 config register."""
