import time
import json
import signal
import logging
import threading
import queue
import datetime
import argparse
import threading
import signal
import sys
import RPi.GPIO as GPIO
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput
from gpiozero import LED
from PIL import Image, ImageChops, ImageStat

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotionDetector:
    def __init__(self, config):
        self.config = config
        self.motion_threshold = config.get('motion_threshold', 10)
        self.last_frame = None
        self.motion_detected = False
        self.motion_start_time = None
        self.motion_end_time = None
        self.motion_duration = 0
        self.motion_count = 0
        self.motion_log = []
        self.motion_lock = threading.Lock()

    def detect_motion(self, current_frame):
        if current_frame is None:
            return False
        try:
            current_gray = current_frame.convert('L')
            if self.last_frame is None:
                self.last_frame = current_gray
                return False
            diff = ImageChops.difference(current_gray, self.last_frame)
            stat = ImageStat.Stat(diff)
            mean_diff = sum(stat.mean) / len(stat.mean)
            self.last_frame = current_gray
            return mean_diff > self.motion_threshold
        except Exception as e:
            logging.error(f"Error in motion detection: {e}")
            return False

    def update_motion(self, motion_detected):
        with self.motion_lock:
            if motion_detected and not self.motion_detected:
                self.motion_detected = True
                self.motion_start_time = time.time()
                self.motion_count += 1
                self.motion_log.append({
                    'timestamp': datetime.datetime.now().isoformat(),
                    'duration': 0,
                    'count': self.motion_count
                })
            elif not motion_detected and self.motion_detected:
                self.motion_end_time = time.time()
                self.motion_duration = self.motion_end_time - self.motion_start_time
                self.motion_detected = False
                self.motion_log[-1]['duration'] = self.motion_duration

    def get_motion_data(self):
        with self.motion_lock:
            return {
                'motion_detected': self.motion_detected,
                'motion_log': self.motion_log,
                'motion_count': self.motion_count,
                'motion_duration': self.motion_duration
            }

class CameraHandler:
    def __init__(self, config):
        self.config = config
        self.camera = None
        self.encoder = None
        self.output = None
        self.frame_queue = queue.Queue(maxsize=self.config['frame_queue_size'])
        self.running = True
        self.camera_lock = threading.Lock()
        self.motion_detector = MotionDetector(config)
        self.mqtt_client = None
        self.led = None
        self.led_pin = config.get('gpio_pin')
        self.led_duration = config.get('led_duration', 1)
        self._init_gpio()
        self._init_camera()

    def _init_gpio(self):
        if self.led_pin is not None:
            try:
                self.led = LED(self.led_pin)
                logging.info(f"GPIO pin {self.led_pin} initialized for LED.")
            except Exception as e:
                logging.error(f"Failed to initialize GPIO pin {self.led_pin}: {e}")
                self.led = None

    def _init_camera(self):
        try:
            self.camera = Picamera2()
            camera_config = self.camera.create_video_configuration(
                main={"size": tuple(self.config['resolution'])},
                controls={"FrameRate": self.config['framerate']}
            )
            self.camera.configure(camera_config)
            self.encoder = MJPEGEncoder()
            self.output = FileOutput()
            self.camera.start()
            time.sleep(2)
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize camera: {e}")
            self.camera = None

    def capture_loop(self):
        while self.running:
            try:
                frame = self.camera.capture_array()
                if frame is None:
                    logging.warning("Captured frame is None.")
                    continue
                image = Image.fromarray(frame)
                if self.frame_queue.full():
                    try:
                        self.frame_queue.get_nowait()
                    except queue.Empty:
                        pass
                self.frame_queue.put(image)
                motion_detected = self.motion_detector.detect_motion(image)
                self.motion_detector.update_motion(motion_detected)
                if motion_detected:
                    logging.info("Motion detected!")
                    self.trigger_alert()
            except Exception as e:
                logging.error(f"Error in capture loop: {e}")
            time.sleep(0.1)

    def trigger_alert(self):
        if self.led:
            try:
                self.led.on()
                logging.info("LED activated.")
                timer = threading.Timer(self.led_duration, self._led_off)
                timer.start()
            except Exception as e:
                logging.error(f"Failed to trigger LED: {e}")
        else:
            logging.info("No LED configured. Alert triggered via console.")

    def _led_off(self):
        if self.led:
            try:
                self.led.off()
                logging.info("LED deactivated.")
            except Exception as e:
                logging.error(f"Failed to deactivate LED: {e}")

    def get_frame(self):
        try:
            return self.frame_queue.get(timeout=1)
        except queue.Empty:
            return None

    def get_motion_data(self):
        return self.motion_detector.get_motion_data()

    def cleanup(self):
        self.running = False
        if self.camera:
            try:
                self.camera.stop()
                logging.info("Camera stopped.")
            except Exception as e:
                logging.error(f"Error stopping camera: {e}")
        if self.led:
            try:
                self.led.close()
                logging.info("GPIO pin cleaned up.")
            except Exception as e:
                logging.error(f"Error cleaning up GPIO: {e}")
        GPIO.cleanup()
        logging.info("GPIO cleanup complete.")

def main():
    parser = argparse.ArgumentParser(description="Raspberry Pi Camera Security System")
    parser.add_argument("--config", default="config.json", help="Path to the configuration file")
    args = parser.parse_args()

    config = {}
    try:
        with open(args.config, 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {args.config}")
        sys.exit(1)
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}")
        sys.exit(1)

    camera_handler = None
    def signal_handler(sig, frame):
        logging.info("Received SIGINT. Shutting down...")
        if camera_handler:
            camera_handler.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)

    try:
        camera_handler = CameraHandler(config)
        capture_thread = threading.Thread(target=camera_handler.capture_loop, daemon=True)
        capture_thread.start()
        while True:
            frame = camera_handler.get_frame()
            if frame:
                logging.info("Frame captured successfully.")
            motion_data = camera_handler.get_motion_data()
            if motion_data['motion_detected']:
                logging.info(f"Motion detected! Count: {motion_data['motion_count']}, Duration: {motion_data['motion_duration']:.2f}s")
            time.sleep(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if camera_handler:
            camera_handler.cleanup()

if __name__ == "__main__":
    main()

