            i2c.deinit()
        except Exception:
            pass
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
    else:
        print("\nExiting cleanly.")


def init_sensor():
    """Initialize I2C and AMG8833. Returns sensor object or None on failure."""
    global i2c, amg
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        amg = adafruit_amg88xx.AMG88XX(i2c, addr=I2C_ADDRESS)
        # Allow sensor to stabilize after power-up
        time.sleep(0.5)
        return amg
    except Exception as e:
        print(f"AMG8833 not detected at 0x{I2C_ADDRESS:02X} ({e}). "
              f"Using simulated thermal data.")
        return None


def get_thermal_data(amg):
    """Read 8x8 thermal array from AMG8833 or simulate if sensor unavailable."""
    if amg is not None:
        try:
            pixels = amg.pixels
            if len(pixels) != 64:
                raise RuntimeError(f"Unexpected pixel count: {len(pixels)}")
            return pixels
        except Exception as e:
            print(f"Sensor read error: {e}. Using simulated data.")
            return [random.uniform(20.0, 45.0) for _ in range(64)]
    else:
        return [random.uniform(20.0, 45.0) for _ in range(64)]


def detect_human(thermal_data):
    """Return True if any pixel exceeds the human-heat threshold."""
    return any(temp > HUMAN_THRESHOLD for temp in thermal_data)


def trigger_alert(buzzer):
    """Sound the buzzer for ALERT_DURATION seconds."""
    if buzzer is None:
        return
    try:
        buzzer.on()
        time.sleep(ALERT_DURATION)
        buzzer.off()
    except Exception as e:
        print(f"Buzzer error: {e}")


def main():
    global buzzer

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        print(f"Failed to initialize buzzer on GPIO{BUZZER_PIN}: {e}")
        cleanup()
        return

    # Initialize sensor
    amg = init_sensor()

    print("Thermal security system started. Press Ctrl+C to exit.")

    while running:
        thermal_data = get_thermal_data(amg)
        if detect_human(thermal_data):
            print("Human detected! Triggering alert.")
            trigger_alert(buzzer)
        else:
            print("No human detected.")
        time.sleep(POLL_INTERVAL)

    cleanup()


if __name__ == "__main__":
    main()

