import spidev
import time
import datetime
import logging
import signal
import sys
import RPi.GPIO as GPIO
from picamera2 import Picamera2
import requests

# Configuration
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
MOISTURE_CHANNELS = [0, 1, 2, 3]
VALVE_PINS = [17, 27, 22, 23]
MOISTURE_THRESHOLDS = [30, 40, 35, 45]
IRRIGATION_DURATION = 600
CHECK_INTERVAL = 300
CAMERA_INTERVAL = 600
OPENWEATHERMAP_API_KEY = "YOUR_API_KEY"
RAIN_THRESHOLD_MM = 2.0
CAMERA_RESOLUTION = (640, 480)
CAMERA_ANALYSIS_FACTOR = {"healthy": 0.8, "stressed": 1.1}

# Logging setup
logging.basicConfig(
    filename="irrigation.log",
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# Global state
spi = None
camera = None
running = True


def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False


def init_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        logging.info("SPI initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize SPI: {e}")
        raise


def init_camera():
    global camera
    try:
        camera = Picamera2()
        config = camera.create_still_configuration(
            main={"size": CAMERA_RESOLUTION, "format": "RGB888"}
        )
        camera.configure(config)
        camera.start()
        logging.info("Camera initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        camera = None


def read_moisture(channel):
    if spi is None:
        logging.error("SPI not initialized.")
        return None
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        logging.error(f"Error reading moisture from channel {channel}: {e}")
        return None


def control_valve(pin, state):
    try:
        GPIO.output(pin, GPIO.HIGH if state else GPIO.LOW)
        logging.info(f"Valve on pin {pin} set to {'ON' if state else 'OFF'}.")
    except Exception as e:
        logging.error(f"Error controlling valve on pin {pin}: {e}")


def irrigate_zone(zone, duration):
    logging.info(f"Starting irrigation for zone {zone} for {duration} seconds.")
    control_valve(VALVE_PINS[zone], True)
    start_time = time.time()
    while running and (time.time() - start_time) < duration:
        time.sleep(10)
    control_valve(VALVE_PINS[zone], False)
    logging.info(f"Irrigation for zone {zone} completed.")


def capture_image():
    if camera is None:
        logging.warning("Camera not available, skipping image capture.")
        return None
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"image_{timestamp}.jpg"
        camera.capture_file(filename)
        logging.info(f"Image captured: {filename}")
        return filename
    except Exception as e:
        logging.error(f"Error capturing image: {e}")
        return None


def assess_plant_health():
    current_second = datetime.datetime.now().second
    if current_second % 2 == 0:
        return "healthy"
    else:
        return "stressed"


def get_weather_data():
    try:
        response = requests.get(
            f"http://api.openweathermap.org/data/2.5/weather",
            params={"appid": OPENWEATHERMAP_API_KEY, "q": "London"},
            timeout=10
        )
        response.raise_for_status()
        data = response.json()
        rain = data.get("rain", {}).get("1h", 0)
        return rain
    except Exception as e:
        logging.error(f"Error getting weather data: {e}")
        return None


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        for pin in VALVE_PINS:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        init_spi()
        init_camera()
        logging.info("Irrigation system started.")

        while running:
            for i, channel in enumerate(MOISTURE_CHANNELS):
                moisture = read_moisture(channel)
                if moisture is not None:
                    logging.info(f"Zone {i+1}: Moisture = {moisture}")
                    if moisture < MOISTURE_THRESHOLDS[i]:
                        duration = IRRIGATION_DURATION
                        health = assess_plant_health()
                        if health in CAMERA_ANALYSIS_FACTOR:
                            duration *= CAMERA_ANALYSIS_FACTOR[health]
                        logging.info(f"Zone {i+1}: Plant health = {health}, adjusted duration = {duration:.1f}s")
                        irrigate_zone(i, duration)
                else:
                    logging.warning(f"Zone {i+1}: Failed to read moisture, skipping irrigation.")

            if time.time() % CAMERA_INTERVAL == 0:
                capture_image()

            if get_weather_data() is not None:
                logging.info("Weather data retrieved successfully.")
            else:
                logging.warning("Failed to retrieve weather data.")

            for _ in range(CHECK_INTERVAL):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        logging.info("Shutting down...")
        for pin in VALVE_PINS:
            try:
                GPIO.output(pin, GPIO.LOW)
            except:
                pass
        if spi is not None:
            try:
                spi.close()
            except:
                pass
        if camera is not None:
            try:
                camera.stop()
                camera.close()
            except:
                pass
        GPIO.cleanup()
        logging.info("Irrigation system stopped.")


if __name__ == "__main__":
    main()

