import cv2
import numpy as np
import signal
import sys
from picamera2 import Picamera2

running = True

def signal_handler(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    picam0 = None
    picam1 = None
    try:
        picam0 = Picamera2(0)
        picam1 = Picamera2(1)
        config = picam0.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            controls={"FrameDurationLimits": (33333, 33333)}
        )
        picam0.configure(config)
        picam1.configure(config)
        picam0.start()
        picam1.start()
    except Exception as e:
        print(f"Error initializing cameras: {e}", file=sys.stderr)
        if picam0 is not None:
            try:
                picam0.close()
            except Exception:
                pass
        if picam1 is not None:
            try:
                picam1.close()
            except Exception:
                pass
        cv2.destroyAllWindows()
        sys.exit(1)

    cv2.namedWindow("Dual CSI Cameras", cv2.WINDOW_AUTOSIZE)

    try:
        while running:
            img0 = picam0.capture_array()
            img1 = picam1.capture_array()
            if img0 is None or img1 is None:
                print("Warning: captured empty frame, skipping", file=sys.stderr)
                continue
            img = np.hstack((img0, img1))
            cv2.imshow("Dual CSI Cameras", img)
            key = cv2.waitKey(30) & 0xFF
            if key == 27 or cv2.getWindowProperty("Dual CSI Cameras", cv2.WND_PROP_AUTOSIZE) < 0:
                break
    except KeyboardInterrupt:
        pass
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        if picam0 is not None:
            try:
                picam0.stop()
            except Exception:
                pass
        if picam1 is not None:
            try:
                picam1.stop()
            except Exception:
                pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

