import multiprocessing
import os
import signal
import time
import atexit
import threading
import traceback
from typing import List, Callable, Any, Optional

import config
import logsupport as L
from controlevents import CEvent, PostEvent, ConsoleEvent
from setproctitle import setproctitle

# Type aliases for clarity
ProcessID = int
KeepAliveEvent = multiprocessing.Event
DebugList = List[str]

# Constants
FAILSAFE_INTERVAL_SECONDS = 30
FAILSAFE_TIMEOUT_SECONDS = 60
POST_MASTHER_SHUTDOWN_DELAY_SECONDS = 3
FAILSAFE_EXIT_CODE = 94
TOMBSTONE_FILE = '/home/pi/.tombstoneW'
HISTORY_FILE = '/home/pi/Console/.HistoryBuffer/hlogW'

# Global state
keep_alive_event: KeepAliveEvent = multiprocessing.Event()
debug_output: DebugList = []
console_pid: ProcessID = config.sysStore.Console_pid
_master_shutdown_event: Optional[multiprocessing.Event] = None
_master_shutdown_delay_event: Optional[multiprocessing.Event] = None
_master_shutdown_delay_timer: Optional[threading.Timer] = None
_master_shutdown_timer: Optional[threading.Timer] = None
_master_shutdown_delay_seconds: int = POST_MASTHER_SHUTDOWN_DELAY_SECONDS
_master_shutdown_timer_seconds: int = 30
_interrupted: bool = False


def log_debug(message: str) -> None:
    """Append a timestamped debug message to the history file and in-memory list."""
    timestamp = time.strftime('%H:%M:%S %d-%b-%y', time.localtime(time.time()))
    debug_message = f'{timestamp} {message}'
    debug_output.append(debug_message)
    try:
        with open(HISTORY_FILE, 'a') as f:
            f.write(debug_message + '\n')
            f.flush()
    except OSError as e:
        L.Log(f'Watchdog: failed to write to history file: {e}')


def master_dying() -> None:
    """Signal that the master process is dying."""
    global _interrupted
    _interrupted = True
    log_debug('Watchdog: master dying')


def master_alive() -> None:
    """Signal that the master process is alive."""
    global _interrupted
    _interrupted = False
    log_debug('Watchdog: master alive')


def _check_process_exists(pid: ProcessID) -> bool:
    """Return True if *pid* is currently running."""
    try:
        os.kill(pid, 0)
        return True
    except OSError:
        return False


def _failsafe_exit(code: int) -> None:
    """Send SIGUSR1 then SIGKILL to the console process and exit."""
    log_debug(f'Watchdog exiting with code {code}')
    if console_pid > 0 and _check_process_exists(console_pid):
        try:
            os.kill(console_pid, signal.SIGUSR1)
            log_debug('Watchdog: sent SIGUSR1 to console')
        except OSError:
            pass
        time.sleep(1)
        try:
            os.kill(console_pid, signal.SIGKILL)
            log_debug('Watchdog: sent SIGKILL to console')
        except OSError:
            pass
    os._exit(code)


def _signal_handler_sigterm(signum: int, frame: Any) -> None:
    """Handle SIGTERM (expected from systemd)."""
    log_debug('Watchdog: received SIGTERM (systemd)')
    time.sleep(_master_shutdown_timer_seconds)
    _failsafe_exit(0)


def _signal_handler_sigint(signum: int, frame: Any) -> None:
    """Handle SIGINT (Ctrl-C)."""
    log_debug('Watchdog: received SIGINT')
    _failsafe_exit(FAILSAFE_EXIT_CODE)


def _signal_handler_sighup(signum: int, frame: Any) -> None:
    """Handle SIGHUP (ignored)."""
    log_debug('Watchdog: received SIGHUP (ignored)')


def _signal_handler_sigabrt(signum: int, frame: Any) -> None:
    """Handle SIGABRT by writing a tombstone and exiting."""
    log_debug('Watchdog: received SIGABRT')
    try:
        with open(TOMBSTONE_FILE, 'a') as f:
            f.write(f'{time.strftime("%Y-%m-%d %H:%M:%S")} Watchdog abort\n')
            f.flush()
            traceback.print_stack(file=f)
            f.flush()
    except OSError as e:
        L.Log(f'Watchdog: failed to write tombstone: {e}')
    _failsafe_exit(93)


def _install_signal_handlers() -> None:
    """Install all signal handlers."""
    signal.signal(signal.SIGTERM, _signal_handler_sigterm)
    signal.signal(signal.SIGINT, _signal_handler_sigint)
    signal.signal(signal.SIGHUP, _signal_handler_sighup)
    signal.signal(signal.SIGABRT, _signal_handler_sigabrt)


def _failsafe_termination() -> None:
    """Attempt graceful shutdown of the console process on watchdog exit."""
    log_debug('Watchdog: atexit - attempting failsafe termination')
    if console_pid > 0 and _check_process_exists(console_pid):
        try:
            os.kill(console_pid, signal.SIGUSR1)
            log_debug('Watchdog: sent SIGUSR1 to console')
        except OSError:
            pass
        time.sleep(1)
        try:
            os.kill(console_pid, signal.SIGKILL)
            log_debug('Watchdog: sent SIGKILL to console')
        except OSError:
            pass


def _interrupt_master() -> None:
    """Send SIGINT to the master process if it has died."""
    global _interrupted
    if _interrupted and console_pid > 0 and _check_process_exists(console_pid):
        try:
            os.kill(console_pid, signal.SIGINT)
            log_debug('Watchdog: sent SIGINT to master')
        except OSError:
            pass


def _injector() -> None:
    """Periodically inject a FailSafePing event into the console."""
    while True:
        try:
            now = time.time()
            L.Log(f'Inject: {disptime(now)}')
            PostEvent(ConsoleEvent(CEvent.FailSafePing, inject=now))
            time.sleep(FAILSAFE_INTERVAL_SECONDS)
        except Exception as e:
            log_debug(f'Inject: exception: {e}')
            time.sleep(FAILSAFE_INTERVAL_SECONDS)


def _watchdog() -> None:
    """Main watchdog loop: wait for keep-alive or timeout."""
    global keep_alive_event, debug_output, _interrupted, _master_shutdown_delay_timer, _master_shutdown_timer

    _install_signal_handlers()
    setproctitle('Console Watchdog')

    log_debug('Watchdog started')

    while True:
        try:
            if keep_alive_event.wait(FAILSAFE_TIMEOUT_SECONDS):
                keep_alive_event.clear()
                log_debug('Watchdog: keep-alive received')
            else:
                log_debug('Watchdog: keep-alive timeout - attempting failsafe termination')
                _failsafe_termination()
                break
        except Exception as e:
            log_debug(f'Watchdog: exception: {e}')
            break

    log_debug('Watchdog: exiting')


def _check_master_thread() -> None:
    """Background thread: verify MainThread is alive every 30 seconds."""
    global _interrupted, _master_shutdown_delay_timer, _master_shutdown_timer

    while True:
        time.sleep(30)
        if _interrupted:
            continue
        if not threading.currentThread() is threading._main_thread:
            log_debug('Watchdog: Main Thread died - interrupting master')
            _interrupt_master()
            break


def _failsafe_master_shutdown() -> None:
    """Handle master shutdown: delay then kill the console."""
    global _master_shutdown_delay_timer, _master_shutdown_timer

    if _master_shutdown_delay_timer:
        _master_shutdown_delay_timer.cancel()
        _master_shutdown_delay_timer = None

    if _master_shutdown_timer:
        _master_shutdown_timer.cancel()
        _master_shutdown_timer = None

    log_debug('Watchdog: master shutdown')
    time.sleep(_master_shutdown_delay_seconds)

    if console_pid > 0 and _check_process_exists(console_pid):
        try:
            os.kill(console_pid, signal.SIGUSR1)
            log_debug('Watchdog: sent SIGUSR1 to console')
        except OSError:
            pass
        time.sleep(1)
        try:
            os.kill(console_pid, signal.SIGKILL)
            log_debug('Watchdog: sent SIGKILL to console')
        except OSError:
            pass


def _failsafe_master_shutdown_delay() -> None:
    """Schedule the actual master shutdown after a delay."""
    global _master_shutdown_delay_timer, _master_shutdown_timer

    if _master_shutdown_delay_timer:
