from fractions import Fraction
from math import floor, fabs
from typing import Tuple, Union, Any


def degrees_decimal_to_dms(degrees_decimal: float) -> Tuple[int, int, float]:
    """Converts decimal degrees to (degrees, minutes, seconds) tuple.

    Args:
        degrees_decimal: The latitude or longitude in decimal degrees.

    Returns:
        A tuple containing (degrees, minutes, seconds) as integers or float.

    Raises:
        ValueError: If the input is not a real number.
    """
    if not isinstance(degrees_decimal, (int, float)):
        raise ValueError(f"Input must be a real number, got {type(degrees_decimal).__name__}")

    try:
        abs_degrees = abs(float(degrees_decimal))
    except (ValueError, TypeError):
        raise ValueError(f"Could not convert input to float: {degrees_decimal}")

    degrees = int(abs_degrees)
    decimal_minutes = (abs_degrees - degrees) * 60
    minutes = int(decimal_minutes)
    seconds = (decimal_minutes - minutes) * 60

    # Preserve the sign of the original input
    if degrees_decimal < 0:
        degrees = -degrees
        minutes = -minutes
        seconds = -seconds

    return degrees, minutes, seconds


def number_to_exif_rational(number: Union[int, float, Fraction]) -> Tuple[int, int]:
    """Converts a number to a rational representation suitable for EXIF metadata.

    Args:
        number: The number to convert.

    Returns:
        A tuple containing (numerator, denominator) as integers.

    Raises:
        ValueError: If the input is not a real number or cannot be converted to a fraction.
        TypeError: If the resulting numerator or denominator are not integers.
    """
    if not isinstance(number, (int, float, Fraction)):
        raise ValueError(f"Input must be a real number or Fraction, got {type(number).__name__}")

    try:
        fraction = Fraction(number).limit_denominator(1000)
    except (ValueError, TypeError):
        raise ValueError(f"Could not convert input to a fraction: {number}")

    numerator = fraction.numerator
    denominator = fraction.denominator

    if not isinstance(numerator, int) or not isinstance(denominator, int):
        raise TypeError("Numerator and denominator must be integers.")

    return numerator, denominator


def _check_exif_value(value: Any) -> None:
    """Internal helper to validate EXIF value types."""
    if not isinstance(value, (int, float, Fraction)):
        raise ValueError(f"EXIF value must be int, float, or Fraction, got {type(value).__name__}")
    if isinstance(value, (int, float)):
        if not isinstance(value, (int, float)):
            raise TypeError(f"Value must be int or float, got {type(value).__name__}")
    elif isinstance(value, Fraction):
        if not isinstance(value.numerator, int) or not isinstance(value.denominator, int):
            raise TypeError("Fraction must have integer numerator and denominator.")


def _convert_to_rational(value: Any) -> Tuple[int, int]:
    """Internal helper to convert a value to a rational tuple."""
    _check_exif_value(value)
    return number_to_exif_rational(value)


def _convert_to_exif_value(value: Any) -> Tuple[int, int]:
    """Internal helper to convert a value to an EXIF rational tuple."""
    return _convert_to_rational(value)


def _convert_exif_value(value: Any) -> Tuple[int, int]:
    """Internal helper to convert a value to an EXIF rational tuple."""
    return _convert_to_rational(value)


def _convert_exif_value_list(value: Any) -> Tuple[Tuple[int, int], ...]:
    """Internal helper to convert a list of values to a tuple of EXIF rational tuples."""
    if not isinstance(value, (list, tuple)):
        raise ValueError(f"Input must be a list or tuple, got {type(value).__name__}")
    return tuple(_convert_to_rational(v) for v in value)


def _convert_exif_value_dict(value: Any) -> Tuple[Tuple[int, int], ...]:
    """Internal helper to convert a dict of values to a tuple of EXIF rational tuples."""
    if not isinstance(value, dict):
        raise ValueError(f"Input must be a dict, got {type(value).__name__}")
    return tuple(_convert_to_rational(v) for v in value.values())

