import atexit
import signal
import sys
import threading
import time
import logging
from typing import Optional, Tuple

from flask import Flask, render_template, Response, request, redirect, url_for

from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput

from config import Config
from mail_config import send_email

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

app = Flask(__name__)
config = Config()
mail_config = None

shutdown_event = threading.Event()
picam2: Optional[Picamera2] = None


def initialize_camera() -> Picamera2:
    """Initialize picamera2 with a video configuration suitable for streaming."""
    cam = Picamera2()
    video_config = cam.create_video_configuration(
        main={"size": (640, 480), "format": "RGB888"},
        lores={"size": (320, 240), "format": "YUV420"},
    )
    cam.configure(video_config)
    cam.start()
    return cam


def capture_frame(cam: Picamera2) -> bytes:
    """Capture a single JPEG frame from the camera."""
    # Capture to a file-like buffer so we can read JPEG bytes directly
    buffer = io.BytesIO()
    cam.capture_file(buffer, format="jpeg")
    buffer.seek(0)
    return buffer.read()


def detect_object(frame: bytes, classifier) -> bool:
    """Run object detection on the JPEG frame using the provided classifier."""
    # classifier is expected to be a callable that accepts bytes and returns a bool
    return classifier(frame)


def send_notification(frame: bytes, config: Config) -> None:
    """Send an email notification with the detected frame."""
    try:
        send_email(frame, config)
        logger.info("Email notification sent successfully.")
    except Exception as e:
        logger.error(f"Failed to send email notification: {e}")


def check_for_objects() -> None:
    """Continuously check for objects and send notifications if configured."""
    last_email_time = 0.0
    while not shutdown_event.is_set():
        try:
            if config.classifier_name == "motion_detector":
                frame, object_detected = get_object_with_basic_motion_detection()
            else:
                frame, object_detected = get_object(config.classifier)

            if object_detected:
                if config.send_email_notifications and (time.time() - last_email_time) >= config.email_send_interval:
                    send_notification(frame, config)
                    last_email_time = time.time()
        except Exception as e:
            logger.error(f"Error in object detection loop: {e}")
        shutdown_event.wait(1.0)


def get_object(classifier) -> Tuple[bytes, bool]:
    """Get a frame and run object detection."""
    frame = capture_frame(picam2)
    object_detected = detect_object(frame, classifier)
    return frame, object_detected


def get_object_with_basic_motion_detection() -> Tuple[bytes, bool]:
    """Get a frame and run motion detection."""
    frame = capture_frame(picam2)
    object_detected = detect_object(frame, config.motion_detector)
    return frame, object_detected


@app.route('/', methods=['GET', 'POST'])
def index() -> str:
    """Render the configuration form."""
    if request.method == 'POST':
        config.classifier_name = request.form.get('classifier_name')
        config.classifier = request.form.get('classifier')
        config.use_grayscale = request.form.get('use_grayscale') == 'on'
        config.live_preview = request.form.get('live_preview') == 'on'
        config.send_email_notifications = request.form.get('send_email_notifications') == 'on'
        config.email_recipient = request.form.get('email_recipient')
        config.email_send_interval = float(request.form.get('email_send_interval', 60))

        if config.send_email_notifications and not config.email_recipient:
            config.send_email_notifications = False
            logger.warning("Email notifications disabled due to missing recipient.")

        logger.info(f"Configuration updated: {config}")

    return render_template('index.html', config=config)


def gen(camera):
    """Generate JPEG frames for the MJPEG video feed."""
    while not shutdown_event.is_set():
        try:
            if config.classifier_name == "motion_detector":
                frame, _ = get_object_with_basic_motion_detection()
            else:
                frame, _ = get_object(config.classifier)

            yield (b'--frame\r\n'
                   b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n\r\n')
        except Exception as e:
            logger.error(f"Error generating frame: {e}")
            shutdown_event.wait(1.0)


@app.route('/video_feed')
def video_feed() -> Response:
    """Return the MJPEG video feed response."""
    return Response(gen(picam2),
                    mimetype='multipart/x-mixed-replace; boundary=frame')


def cleanup() -> None:
    """Clean up camera resources on exit."""
    global picam2
    if picam2 is not None:
        try:
            picam2.stop()
            logger.info("Camera stopped.")
        except Exception as e:
            logger.error(f"Error stopping camera: {e}")
        picam2 = None


def signal_handler(signum, frame) -> None:
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    logger.info(f"Signal {signum} received, shutting down...")
    shutdown_event.set()


if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        picam2 = initialize_camera()
        logger.info("Camera initialized successfully.")
    except Exception as e:
        logger.error(f"Failed to initialize camera: {e}")
        sys.exit(1)

    atexit.register(cleanup)

    try:
        object_detection_thread = threading.Thread(target=check_for_objects, daemon=True)
        object_detection_thread.start()
        logger.info("Object detection thread started.")

        app.run(host='0.0.0.0', port=5000, debug=False, use_reloader=False)
    except Exception as e:
        logger.error(f"Application error: {e}")
    finally:
        shutdown_event.set()
        cleanup()

