import json
import logging
import signal
import sys
import time
from collections import deque
from datetime import datetime

try:
    from gpiozero import OutputDevice, InputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(0)

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning(f"Config file '{config_file}' not found. Creating default config.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in config file: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()


def save_config(config, config_file):
    try:
        with open(config_file, "w") as f:
            json.dump(config, f, indent=4)
    except OSError as e:
        logging.error(f"Error saving config: {e}")


def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    try:
        trigger = OutputDevice(trigger_pin)
        echo = InputDevice(echo_pin)
    except GPIOZeroError as e:
        logging.error(f"GPIO init error on trigger={trigger_pin}, echo={echo_pin}: {e}")
        return None

    try:
        trigger.on()
        time.sleep(0.00001)
        trigger.off()

        timeout = time.time() + 0.05
        while echo.is_active:
            if time.time() > timeout:
                logging.warning(f"Echo rising edge timeout on trigger={trigger_pin}, echo={echo_pin}")
                return None

        pulse_start = time.time()
        timeout = time.time() + 0.05
        while not echo.is_active:
            if time.time() > timeout:
                logging.warning(f"Echo falling edge timeout on trigger={trigger_pin}, echo={echo_pin}")
                return None

        pulse_end = time.time()
        pulse_duration = pulse_end - pulse_start

        distance = (pulse_duration * 34300) / 2
        distance += offset
        water_level = max_distance - distance

        if water_level < 0:
            logging.warning(f"Negative water level: {water_level:.2f} on trigger={trigger_pin}, echo={echo_pin}")
            return None

        return water_level
    except DeviceClosed:
        logging.error(f"Device closed during measurement on trigger={trigger_pin}, echo={echo_pin}")
        return None
    except Exception as e:
        logging.error(f"Error measuring distance on trigger={trigger_pin}, echo={echo_pin}: {e}")
        return None
    finally:
        try:
            trigger.close()
            echo.close()
        except Exception:
            pass


def get_average_water_level(sensors, config):
    valid_readings = []
    consecutive_errors = [0] * len(sensors)

    for i, sensor in enumerate(sensors):
        readings = []
        for _ in range(3):
            water_level = measure_distance(
                sensor["trigger_pin"], sensor["echo_pin"], sensor["offset"], sensor["max_distance"]
            )
            if water_level is not None:
                readings.append(water_level)
            else:
                consecutive_errors[i] += 1
                if consecutive_errors[i] >= 5:
                    logging.error(
                        f"Sensor {i} (trigger={sensor['trigger_pin']}, echo={sensor['echo_pin']}) "
                        f"excluded after 5 consecutive errors."
                    )
                    return None

        if readings:
            readings.sort()
            median = (readings[1] + readings[2]) / 2
            valid_readings.append(median)

    if not valid_readings:
        logging.error("No valid readings from any sensor.")
        return None

    return sum(valid_readings) / len(valid_readings)


def check_alerts(average_water_level, config, last_alert_times):
    alert_threshold_low = config["alert_threshold_low"]
    alert_threshold_high = config["alert_threshold_high"]
    alert_repeat_delay = config["alert_repeat_delay"]

    now = time.time()
    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    if average_water_level is None:
        return last_alert_times

    if average_water_level < alert_threshold_low:
        if (current_time not in last_alert_times
                or (now - last_alert_times[current_time]) > alert_repeat_delay):
            logging.warning(
                f"Low water level alert! Average: {average_water_level:.2f}, "
                f"Threshold: {alert_threshold_low}"
            )
            last_alert_times[current_time] = now
    elif average_water_level > alert_threshold_high:
        if (current_time not in last_alert_times
                or (now - last_alert_times[current_time]) > alert_repeat_delay):
            logging.warning(
                f"High water level alert! Average: {average_water_level:.2f}, "
                f"Threshold: {alert_threshold_high}"
            )
            last_alert_times[current_time] = now

    return last_alert_times


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config(CONFIG_FILE)
    setup_logging(config["log_file"])

    sensors = config["sensors"]
    alert_threshold_low = config["alert_threshold_low"]
    alert_threshold_high = config["alert_threshold_high"]
    alert_repeat_delay = config["alert_repeat_delay"]
    log_file = config["log_file"]

    last_alert_times = {}

    try:
        while _running:
            average_water_level = get_average_water_level(sensors, config)

            if average_water_level is not None:
                logging.info(f"Average Water Level: {average_water_level:.2f}")
                check_alerts(average_water_level, config, last_alert_times)
            else:
                logging.warning("No valid water level readings.")

            time.sleep(5)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Program shutting down.")


if __name__ == "__main__":
    main()

