            return filename
        except Exception as e:
            print(f"Error capturing image: {e}")
            return None
    else:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        print(f"Simulated image captured: {filename}")
        return filename

def listen_for_commands():
    recognizer = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            print("Listening for commands...")
            recognizer.adjust_for_ambient_noise(source, duration=0.5)
            audio = recognizer.listen(source, timeout=5)
    except sr.WaitTimeoutError:
        print("No speech detected within timeout.")
        return None
    except Exception as e:
        print(f"Error listening for commands: {e}")
        return None

    try:
        command = recognizer.recognize_google(audio).lower()
        print(f"Recognized command: {command}")
        return command
    except sr.UnknownValueError:
        print("Could not understand audio.")
        return None
    except sr.RequestError as e:
        print(f"Could not request results from Google Web Speech API: {e}")
        return None

def process_command(command):
    global lights_on
    if "turn on the lights" in command:
        turn_lights_on()
        lights_on = True
    elif "turn off the lights" in command:
        turn_lights_off()
        lights_on = False
    elif "what is the temperature" in command:
        read_temperature()
    elif "take a picture" in command:
        capture_image()
    else:
        print("Unknown command.")

def main():
    global lights_on
    init_gpio()
    init_camera()
    init_dht_sensor()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Greenhouse control system started. Say 'Greenhouse' followed by a command.")
    try:
        while True:
            command = listen_for_commands()
            if command and WAKE_WORD in command:
                process_command(command)
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

