import cv2
import time
import signal
import sys
import config
import face

try:
    from picamera2 import Picamera2
except ImportError:
    print("picamera2 is not installed. Install with: pip install picamera2")
    sys.exit(1)

try:
    from hardware import Box
except ImportError:
    print("hardware.Box is not available. Ensure the hardware module is installed.")
    sys.exit(1)

# Global resources for cleanup
box = None
picam2 = None
running = True


def signal_handler(sig, frame):
    global running
    running = False


def cleanup():
    global box, picam2
    if box is not None:
        try:
            if not box.is_locked:
                box.lock()
        except Exception:
            pass
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception:
            pass


def main():
    global box, picam2, running

    signal.signal(signal.SIGINT, signal_handler)

    # Initialize the hardware box
    try:
        box = Box()
        box.lock()
    except Exception as e:
        print(f"Failed to initialize box: {e}")
        sys.exit(1)

    # Initialize the face recognition model
    try:
        face_model = cv2.face.EigenFaceRecognizer_create()
        face_model.read(config.TRAINING_FILE)
    except Exception as e:
        print(f"Failed to load face model: {e}")
        sys.exit(1)

    # Initialize the Haar cascade for face detection
    cascade_path = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
    face_cascade = cv2.CascadeClassifier(cascade_path)
    if face_cascade.empty():
        print(f"Failed to load Haar cascade from {cascade_path}")
        sys.exit(1)

    # Initialize the camera
    try:
        picam2 = Picamera2()
        picam2.configure(
            picam2.create_preview_configuration(
                main={"format": 'XRGB8888', "size": (640, 480)}
            )
        )
        picam2.start()
    except Exception as e:
        print(f"Failed to initialize camera: {e}")
        sys.exit(1)

    print("System ready. Press Ctrl+C to exit.")

    while running:
        try:
            # Capture a frame as a BGR array
            frame = picam2.capture_array()
            if frame is None or frame.size == 0:
                print("Warning: empty frame captured")
                time.sleep(0.1)
                continue

            # Convert to grayscale for detection
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)

            # Detect faces
            faces = face_cascade.detectMultiScale(
                gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30)
            )

            if len(faces) > 0:
                # Take the first detected face
                x, y, w, h = faces[0]
                cropped_face = gray[y:y + h, x:x + w]

                # Resize to model's expected size
                resized_face = cv2.resize(
                    cropped_face, (100, 100), interpolation=cv2.INTER_AREA
                )

                # Predict identity
                label, confidence = face_model.predict(resized_face)

                print(
                    f"Predicted label: {label}, Confidence: {confidence}"
                )

                # Unlock if the correct person is recognized
                if label == config.POSITIVE_LABEL and \
                        config.POSITIVE_THRESHOLD > confidence > 1500:
                    if box.is_locked:
                        box.unlock()
                        print("Box unlocked.")
                    else:
                        print("Box already unlocked.")
                else:
                    print("Face not recognized.")

            # Check if the box is unlocked and the button is up to re-lock
            if not box.is_locked and box.is_button_up():
                box.lock()
                print("Box re-locked.")

            time.sleep(0.1)

        except Exception as e:
            print(f"Error during capture/processing: {e}")
            time.sleep(0.1)

    cleanup()
    print("Exiting.")


if __name__ == "__main__":
    main()

