try:
    from gpiozero import Button, OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    inputs = []
    outputs = []
    try:
        for pin in INPUT_PINS:
            btn = Button(pin, pull_up=True, bounce_time=None)
            inputs.append(btn)
        for pin in OUTPUT_PINS:
            out = OutputDevice(pin, active_high=True, initial_value=False)
            outputs.append(out)

        out24_state = False

        while _running:
            if inputs[0].is_active:
                outputs[0].on()
            else:
                outputs[0].off()

            if inputs[1].is_active:
                outputs[0].off()

            if inputs[2].is_active:
                out24_state = not out24_state
                outputs[1].value = out24_state

            time.sleep(POLL_INTERVAL)

    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"GPIO initialization or runtime error: {e}", file=sys.stderr)
        sys.exit(1)
    except PermissionError as e:
        print(f"Permission denied accessing GPIO: {e}", file=sys.stderr)
        print("Ensure the script is run with sufficient privileges (e.g., sudo).", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in outputs:
            try:
                dev.close()
            except Exception:
                pass
        for dev in inputs:
            try:
                dev.close()
            except Exception:
                pass


if __name__ == "__main__":
