from picamera2.outputs import FileOutput
from http.server import HTTPServer, BaseHTTPRequestHandler
from typing import Optional, Tuple, List

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotionDetector:
    def __init__(self, threshold: int = 20, min_motion_vectors: int = 10):
        self.threshold = threshold
        self.min_motion_vectors = min_motion_vectors
        self.previous_frame: Optional[np.ndarray] = None
        self.motion_vectors: List[Tuple[int, int]] = []

    def detect_motion(self, current_frame: np.ndarray) -> bool:
        if self.previous_frame is None:
            self.previous_frame = current_frame
            return False

        diff = np.abs(current_frame.astype(np.int16) - self.previous_frame.astype(np.int16))
        motion_pixels = np.sum(diff > self.threshold)
