import sys
import select
import os
import signal
import time
import cv2
import pygame.mixer
from gpiozero import Button, OutputDevice
from config import *
from face import detect_single, crop, resize

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
camera = None
door = None
button = None
mixer_initialized = False
running = True


def cleanup():
    """Release all hardware and audio resources."""
    global camera, door, button, mixer_initialized
    if camera is not None:
        try:
            camera.release()
        except Exception:
            pass
        camera = None
    if door is not None:
        try:
            door.close()
        except Exception:
            pass
        door = None
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
        button = None
    if mixer_initialized:
        try:
            pygame.mixer.quit()
        except Exception:
            pass
        mixer_initialized = False


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global running
    running = False


def init_mixer():
    """Initialize pygame.mixer with the configured parameters."""
    global mixer_initialized
    try:
        pygame.mixer.init(frequency=48000, size=-16, channels=1, buffer=1024)
        mixer_initialized = True
    except pygame.error as e:
        print(f"Error initializing pygame.mixer: {e}", file=sys.stderr)
        sys.exit(1)


def load_sounds():
    """Load welcome, wait, and later sounds into separate channels."""
    try:
        sounds = {
            "welcome": pygame.mixer.Sound(config.WELCOME_SOUND),
            "wait": pygame.mixer.Sound(config.WAIT_SOUND),
            "later": pygame.mixer.Sound(config.LATER_SOUND),
        }
        channels = {
            "welcome": pygame.mixer.Channel(0),
            "wait": pygame.mixer.Channel(1),
            "later": pygame.mixer.Channel(2),
        }
        for name, sound in sounds.items():
            channels[name].set_volume(0.5)
            channels[name].play(sound)
        return channels
    except (pygame.error, FileNotFoundError) as e:
        print(f"Error loading sounds: {e}", file=sys.stderr)
        sys.exit(1)


def load_model():
    """Load the pre-trained EigenFaceRecognizer model, verifying the file exists."""
    if not os.path.isfile(config.TRAINING_FILE):
        print(f"Error: Training file not found: {config.TRAINING_FILE}", file=sys.stderr)
        sys.exit(1)
    try:
        print("Loading training data...")
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
        print("Training data loaded!")
        return model
    except cv2.error as e:
        print(f"Error loading training data: {e}", file=sys.stderr)
        sys.exit(1)


def is_letter_input(letter):
    """Check stdin for a specific character without blocking."""
    try:
        if select.select([sys.stdin], [], [], 0.0)[0]:
            input_char = sys.stdin.read(1)
            return input_char.lower() == letter.lower()
    except Exception:
        pass
    return False


def main():
    global camera, door, button, running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize mixer and load sounds
    init_mixer()
    channels = load_sounds()

    # Load the face recognition model
    model = load_model()

    # Initialize camera
    camera = cv2.VideoCapture(config.get_camera())
    if not camera.isOpened():
        print("Error: Could not open camera.", file=sys.stderr)
        cleanup()
        sys.exit(1)

    # Initialize GPIO devices
    try:
        door = hardware.Door()
        button = Button(5, pull_up=True)  # BCM 5, internal pull-up
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print("Running Door Controller...")
    print("Press the button to trigger face recognition.")
    print("Press 'l' followed by Enter to lock the door manually.")
    print("Press Ctrl-C to quit.")

    try:
        while running:
            # Check for button press (active-low with pull-up)
            if button.is_pressed:
                try:
                    ret, image = camera.read()
                    if not ret or image is None:
                        print("Error: Could not read image from camera.", file=sys.stderr)
                        continue

                    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
                    face = detect_single(gray)

                    if face is None:
                        print("No face detected.")
                        channels["later"].play()
                        channels["wait"].play()
                        time.sleep(1)
                        continue

                    cropped = crop(face)
                    resized = resize(cropped)

                    label, confidence = model.predict(resized)

                    print(
                        f"Predicted label: {label}, Confidence: {confidence}"
                    )

                    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                        print("Recognized face! Unlocking door...")
                        channels["welcome"].play()
                        door.unlock()
                    else:
                        print("Face not recognized.")
                        channels["later"].play()
                        channels["wait"].play()

                except cv2.error as e:
                    print(f"OpenCV error during recognition: {e}", file=sys.stderr)
                except Exception as e:
                    print(f"Error during recognition: {e}", file=sys.stderr)

            # Check for manual lock command
            if is_letter_input("l"):
                try:
                    door.lock()
                    print("Door locked manually.")
                except Exception as e:
                    print(f"Error locking door: {e}", file=sys.stderr)

            time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("Exiting...")


if __name__ == "__main__":
    main()

