import argparse
import datetime
import json
import logging
import os
import signal
import sys
import threading
import time

import cv2
import face_recognition
from gpiozero import OutputDevice
from picamera2 import Picamera2

DOOR_RELAY_PIN = 17
ENCODINGS_FILE = "encodings.json"
DEFAULT_CONFIDENCE_THRESHOLD = 0.6
DEFAULT_MOTION_THRESHOLD = 500
DEFAULT_DOOR_OPEN_DURATION = 5
DEFAULT_DEBOUNCE_TIME = 2
DEFAULT_LOG_LEVEL = "INFO"

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class DoorAccessSystem:
    def __init__(self, args):
        self.args = args
        self.running = True
        self.last_access_time = 0.0
        self.debounce_lock = threading.Lock()
        self.relay = None
        self.picam2 = None
        self.encodings = self._load_encodings()
        self._install_signal_handlers()

    def _install_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._signal_handler)

    def _signal_handler(self, signum, frame):
        logging.info(f"Received signal {signum}; shutting down.")
        self.running = False

    def _load_encodings(self):
        encodings = {}
        if os.path.exists(ENCODINGS_FILE):
            try:
                with open(ENCODINGS_FILE, "r") as f:
                    encodings = json.load(f)
                logging.info(f"Loaded {len(encodings)} known encodings.")
            except (json.JSONDecodeError, OSError) as e:
                logging.error(f"Failed to load encodings: {e}; starting empty.")
                encodings = {}
        else:
            logging.info("Encodings file not found; starting with empty set.")
        return encodings

    def _save_encodings(self):
        try:
            with open(ENCODINGS_FILE, "w") as f:
                json.dump(self.encodings, f, indent=4)
            logging.info("Encodings saved.")
        except OSError as e:
            logging.error(f"Failed to save encodings: {e}")

    def _init_camera(self):
        try:
            self.picam2 = Picamera2()
            config = self.picam2.create_preview_configuration(
                main={"format": "XRGB8888", "size": (640, 480)}
            )
            self.picam2.configure(config)
            self.picam2.start()
            logging.info("Camera initialized at 640x480.")
        except Exception as e:
            logging.error(f"Camera init failed: {e}")
            raise

    def _init_relay(self):
        try:
            self.relay = OutputDevice(DOOR_RELAY_PIN, active_high=True, initial_value=False)
            logging.info(f"Relay initialized on GPIO {DOOR_RELAY_PIN}.")
        except Exception as e:
            logging.error(f"Relay init failed: {e}")
            raise

    def _capture_frame(self):
        if self.picam2 is None:
            return None
        try:
            return self.picam2.capture_array()
        except Exception as e:
            logging.error(f"Frame capture error: {e}")
            return None

    def _detect_motion(self, frame1, frame2):
        if frame1 is None or frame2 is None:
            return False
        try:
            diff = cv2.absdiff(frame1, frame2)
            gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
            _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
            thresh = cv2.GaussianBlur(thresh, (5, 5), 0)
            motion_pixels = cv2.countNonZero(thresh)
            return motion_pixels > self.args.motion_threshold
        except Exception as e:
            logging.error(f"Motion detection error: {e}")
            return False

    def _recognize_face(self, face_locations, frame):
        if not face_locations:
            return None, None
        try:
            face_encodings = face_recognition.face_encodings(frame, face_locations)
            if not face_encodings:
                return None, None
            face_encoding = face_encodings[0]
            distances = face_recognition.face_distance(
                list(self.encodings.values()), face_encoding
            )
            best_idx = int(distances.argmin())
            confidence = 1.0 - distances[best_idx]
            if confidence > self.args.confidence_threshold:
                return list(self.encodings.keys())[best_idx], confidence
            return None, None
        except Exception as e:
            logging.error(f"Recognition error: {e}")
            return None, None

    def _activate_relay(self, duration):
        if self.relay is None:
            logging.warning("Relay not initialized; skipping activation.")
            return
        try:
            with self.debounce_lock:
                now = time.time()
                if now - self.last_access_time < self.args.debounce_time:
                    logging.info("Debounce active; skipping relay activation.")
                    return
                self.relay.on()
                logging.info("Relay ON.")
                time.sleep(duration)
                self.relay.off()
                logging.info("Relay OFF.")
                self.last_access_time = time.time()
        except Exception as e:
            logging.error(f"Relay control error: {e}")

    def run(self):
        try:
            self._init_camera()
            self._init_relay()
            prev_frame = self._capture_frame()
            if prev_frame is None:
                logging.error("Initial frame capture failed; aborting.")
                return
            logging.info("System running. Press Ctrl+C to exit.")
            while self.running:
                curr_frame = self._capture_frame()
                if curr_frame is None:
                    time.sleep(0.1)
                    continue
                if self._detect_motion(prev_frame, curr_frame):
                    name, confidence = self._recognize_face(
                        face_recognition.face_locations(curr_frame), curr_frame
                    )
                    ts = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    if name:
                        logging.info(
                            f"Access granted to {name} "
                            f"(confidence: {confidence:.2f}) at {ts}"
                        )
                        self._activate_relay(self.args.door_open_duration)
                    else:
                        logging.warning(
                            f"Unknown face detected (confidence: {confidence:.2f}) at {ts}"
                        )
                prev_frame = curr_frame
                time.sleep(0.1)
        except Exception as e:
            logging.error(f"Fatal error: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        logging.info("Cleaning up resources.")
        if self.relay is not None:
            try:
                self.relay.off()
                self.relay.close()
            except Exception:
                pass
        if self.picam2 is not None:
            try:
                self.picam2.stop()
            except Exception:
                pass
        self._save_encodings()
        logging.info("Cleanup complete.")


def main():
    parser = argparse.ArgumentParser(
        description="Raspberry Pi facial-recognition door-access system."
    )
    parser.add_argument(
        "--confidence_threshold", type=float, default=DEFAULT_CONFIDENCE_THRESHOLD,
        help="Confidence threshold (0.0-1.0)."
    )
    parser.add_argument(
        "--motion_threshold", type=int, default=DEFAULT_MOTION_THRESHOLD,
        help="Motion-pixel threshold (default 500)."
    )
    parser.add_argument(
        "--door_open_duration", type=int, default=DEFAULT_DOOR_OPEN_DURATION,
        help="Door-open seconds (default 5)."
    )
    parser.add_argument(
        "--debounce_time", type=int, default=DEFAULT_DEBOUNCE_TIME,
        help="Debounce seconds (default 2)."
    )
    parser.add_argument(
        "--log_level", type=str, default=DEFAULT_LOG_LEVEL,
        choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"],
        help="Logging level."
    )
    args = parser.parse_args()

    logging.getLogger().setLevel(args.log_level)

    system = DoorAccessSystem(args)
    system.run()


if __name__ == "__main__":
    main()

