import io
import logging
import signal
import threading
from typing import Callable, Optional

import numpy as np
import cv2

logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffers JPEG frames from picamera2, broadcasts complete frames over WebSocket."""

    def __init__(
        self,
        websocket_handler: object,
        detect_motion_function: Optional[Callable] = None,
    ):
        if websocket_handler is None:
            raise TypeError("websocket_handler must not be None")
        if detect_motion_function is not None and not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable or None")
        self.websocket_handler = websocket_handler
        self.detect_motion_function = detect_motion_function
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self._shutdown = False

    def write(self, data: bytes) -> int:
        """Process incoming JPEG bytes; broadcast complete frames."""
        if self._shutdown:
            return len(data)
        try:
            with self.lock:
                self.buffer.write(data)
                self._process_buffer()
            return len(data)
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer.write: {e}")
            return len(data)

    def _process_buffer(self) -> None:
        """Detect JPEG frame boundaries and broadcast complete frames."""
        try:
            buffered_data = self.buffer.getvalue()
            if not buffered_data:
                return
            frame_start = buffered_data.find(b"\xff\xd8")
            if frame_start == -1:
                return
            frame_data = buffered_data[frame_start:]
            self.buffer.seek(frame_start)
            self.buffer.truncate()
            self.buffer.write(frame_data)
            self.buffer.seek(0)
            self._broadcast_frame(frame_data)
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer._process_buffer: {e}")

    def _broadcast_frame(self, frame_data: bytes) -> None:
        """Broadcast a complete JPEG frame over WebSocket."""
        try:
            if self.websocket_handler.has_connections():
                self.websocket_handler.broadcast(frame_data)
        except Exception as e:
            logger.error(f"Error broadcasting frame: {e}")
        if self.detect_motion_function:
            try:
                self.detect_motion_function(frame_data)
            except Exception as e:
                logger.error(f"Error in detect_motion_function: {e}")

    def flush(self) -> None:
        """Emit any remaining buffered frame on shutdown."""
        if self._shutdown:
            return
        self._shutdown = True
        try:
            with self.lock:
                remaining = self.buffer.getvalue()
                if remaining:
                    self._broadcast_frame(remaining)
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer.flush: {e}")

    def close(self) -> None:
        """Public close hook for clean resource release."""
        self.flush()


class MotionDetectionBuffer:
    """Buffers JPEG frames for motion detection using OpenCV."""

    def __init__(
        self,
        detect_motion_function: Callable,
        previous_frame: Optional[np.ndarray] = None,
        current_frame: Optional[np.ndarray] = None,
    ):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        if previous_frame is not None and not isinstance(previous_frame, np.ndarray):
            raise TypeError("previous_frame must be a numpy ndarray or None")
        if current_frame is not None and not isinstance(current_frame, np.ndarray):
            raise TypeError("current_frame must be a numpy ndarray or None")
        self.detect_motion_function = detect_motion_function
        self.previous_frame = previous_frame
        self.current_frame = current_frame
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()

    def write(self, data: bytes) -> int:
        """Process incoming JPEG bytes; assemble frames for motion detection."""
        try:
            with self.lock:
                self.buffer.write(data)
                self._process_buffer()
            return len(data)
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer.write: {e}")
            return len(data)

    def _process_buffer(self) -> None:
        """Detect JPEG frame boundaries and run motion detection on complete frames."""
        try:
            buffered_data = self.buffer.getvalue()
            if not buffered_data:
                return
            frame_start = buffered_data.find(b"\xff\xd8")
            if frame_start == -1:
                return
            frame_data = buffered_data[frame_start:]
            self.buffer.seek(frame_start)
            self.buffer.truncate()
            self.buffer.write(frame_data)
            self.buffer.seek(0)
            self._detect_motion(frame_data)
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer._process_buffer: {e}")

    def _detect_motion(self, frame_data: bytes) -> None:
        """Decode a complete JPEG and invoke the motion detection callback."""
        try:
            frame_np = _convert_to_opencv_frame(frame_data)
            if frame_np is None:
                return
            self.previous_frame = self.current_frame
            self.current_frame = frame_np
            if self.previous_frame is not None and self.current_frame is not None:
                self.detect_motion_function(self.previous_frame, self.current_frame)
        except Exception as e:
            logger.error(f"Error in _detect_motion: {e}")

    def flush(self) -> None:
        """Emit any remaining buffered frame on shutdown."""
        try:
            with self.lock:
                remaining = self.buffer.getvalue()
                if remaining:
                    self._detect_motion(remaining)
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer.flush: {e}")

    def close(self) -> None:
        """Public close hook for clean resource release."""
        self.flush()


def _convert_to_opencv_frame(frame_data: bytes) -> Optional[np.ndarray]:
    """Decode a complete JPEG buffer into an OpenCV BGR image."""
    try:
        data = np.frombuffer(frame_data, dtype=np.uint8)
        frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
        if frame is None:
            logger.error("cv2.imdecode returned None")
            return None
        return frame
    except Exception as e:
        logger.error(f"Error converting frame: {e}")
        return None


