    def _shutdown(self, signum, frame):
        """Placeholder for application-specific shutdown logic."""
        pass


def _get_signal_handler():
    if _SignalHandler._instance is None:
        _SignalHandler()
    return _SignalHandler._instance


def _install_signal_handler():
    """Install the singleton signal handler."""
    _SignalHandler()


def _uninstall_signal_handler():
    """Remove the singleton signal handler."""
    global _SignalHandler
    _SignalHandler._instance = None


def _create_camera_stream_buffer(websocket_handler, detect_motion_function=None):
    return CameraStreamBuffer(websocket_handler, detect_motion_function)


def _create_motion_detection_buffer(
    detect_motion_function, previous_frame=None, current_frame=None
):
    return MotionDetectionBuffer(
        detect_motion_function, previous_frame, current_frame
    )


def _convert_frame_data_to_opencv_frame(frame_data):
    return _convert_to_opencv_frame(frame_data)


def _install_signal_handlers():
    _install_signal_handler()


def _uninstall_signal_handlers():
    _uninstall_signal_handler()

