logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffer for accumulating and flushing MJPEG frames from picamera2."""

    def __init__(self, c):
        if not isinstance(c, Picamera2):
            raise TypeError("c must be a Picamera2 instance")
        self.c = c
        self.b = io.BytesIO()
        self._closed = False

    def write(self, d):
        if self._closed:
            return
        try:
            self.b.write(d)
        except (IOError, OSError) as exc:
            logger.error("I/O error while writing to CameraStreamBuffer: %s", exc)
            return
        try:
