import os
import sys
import time
import signal
import logging
import threading
import speech_recognition as sr
from picamera2 import Picamera2
from libcamera import Transform
import serial
import sx126x

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

SERIAL_PORT = "/dev/ttyS0"
LORA_FREQUENCY = 868
LORA_ADDRESS = 0
LORA_POWER = 22
LORA_AIR_SPEED = 2400
DESKTOP_PATH = "/home/raspberry/Desktop/IoT Project"
IMAGE_FILENAME = "captured_image.jpg"
IMAGE_PATH = os.path.join(DESKTOP_PATH, IMAGE_FILENAME)
SAMPLE_RATE = 44100
CHUNK_SIZE = 1024

running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_lora_node(serial_port, frequency, address, power, air_speed):
    try:
        lora_node = sx126x.sx126x(serial_num=serial_port, freq=frequency, addr=address, power=power, rssi=True, air_speed=air_speed, relay=False)
        logging.info("LoRa node initialized successfully.")
        return lora_node
    except Exception as e:
        logging.error(f"Failed to initialize LoRa node: {e}")
        return None

def send_lora_message(lora_node, message):
    if lora_node is None:
        logging.error("LoRa node not initialized. Cannot send message.")
        return False
    try:
        data = message.encode('utf-8')
        lora_node.send(data)
        logging.info(f"Sent LoRa message: {message}")
        return True
    except Exception as e:
        logging.error(f"Failed to send LoRa message: {e}")
        return False

def capture_image(image_path):
    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_still_configuration(main={"size": (640, 480), "format": "RGB888"}))
        picam2.start()
        time.sleep(2)
        picam2.capture_file(image_path)
        picam2.stop()
        picam2.close()
        logging.info(f"Image captured and saved to: {image_path}")
        return True
    except Exception as e:
        logging.error(f"Failed to capture image: {e}")
        return False

def listen_for_voice_command(sample_rate, chunk_size):
    recognizer = sr.Recognizer()
    try:
        microphone = sr.Microphone(sample_rate=sample_rate, chunk_size=chunk_size)
    except Exception as e:
        logging.error(f"Failed to initialize microphone: {e}")
        return None

    try:
        with microphone as source:
            recognizer.adjust_for_ambient_noise(source)
            logging.info("Listening for voice command...")
            audio = recognizer.listen(source, timeout=5, phrase_time_limit=5)
    except sr.WaitTimeoutError:
        logging.warning("No speech detected within timeout.")
        return None
    except Exception as e:
        logging.error(f"Error listening for voice command: {e}")
        return None

    try:
        command = recognizer.recognize_google(audio)
        logging.info(f"Recognized voice command: {command}")
        return command.lower()
    except sr.UnknownValueError:
        logging.warning("Could not understand audio.")
        return None
    except sr.RequestError as e:
        logging.error(f"Could not request results from Google Web Speech API: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)

    os.makedirs(DESKTOP_PATH, exist_ok=True)

    lora_node = initialize_lora_node(SERIAL_PORT, LORA_FREQUENCY, LORA_ADDRESS, LORA_POWER, LORA_AIR_SPEED)
    if lora_node is None:
        logging.error("Exiting due to LoRa initialization failure.")
        sys.exit(1)

    try:
        while running:
            voice_command = listen_for_voice_command(SAMPLE_RATE, CHUNK_SIZE)
            if voice_command and "capture" in voice_command:
                if capture_image(IMAGE_PATH):
                    send_lora_message(lora_node, "Image captured")
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Exiting program.")
        if 'lora_node' in locals():
            try:
                lora_node.close()
            except Exception:
                pass
        if 'picam2' in locals():
            try:
                picam2.close()
            except Exception:
                pass
        if 'microphone' in locals():
            try:
                microphone.close()
            except Exception:
                pass

if __name__ == "__main__":
    main()

