import time
import signal
import sys
import smbus2

# OLED I2C address (SSD1306 common address on bus 1)
OLED_ADDRESS = 0x3C

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c_bus(bus_number=1):
    """Initializes the I2C bus using smbus2."""
    try:
        return smbus2.SMBus(bus_number)
    except FileNotFoundError:
        print(f"Error: I2C bus {bus_number} not found. Enable I2C with 'sudo raspi-config'.")
        return None
    except PermissionError:
        print("Error: Permission denied accessing I2C bus. Run as root or add user to 'i2c' group.")
        return None
    except Exception as e:
        print(f"Error initializing I2C bus {bus_number}: {e}")
        return None

def read_cpu_temperature():
    """Reads the CPU temperature from the system file."""
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except FileNotFoundError:
        print("Error: Thermal zone file not found. Is this running on a Raspberry Pi?")
        return None
    except PermissionError:
        print("Error: Permission denied reading thermal zone file.")
        return None
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None

def main():
    """Main function to read and display CPU temperature."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c_bus(1)
    if i2c_bus is None:
        sys.exit(1)

    try:
        while _running:
            temperature = read_cpu_temperature()
            if temperature is not None:
                print(f"CPU Temperature: {temperature:.2f} °C")
            time.sleep(2)
    finally:
        if i2c_bus is not None:
            try:
                i2c_bus.close()
                print("I2C bus closed.")
            except Exception as e:
                print(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

