import time
import signal
import sys
import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht

# --- Configuration -----------------------------------------------------------
LCD_COLUMNS = 16
LCD_ROWS = 2
LCD_I2C_ADDRESS = 0x27
DHT_PIN = board.D4
READ_INTERVAL_SECONDS = 2.0

# --- Globals for cleanup -----------------------------------------------------
lcd = None
dht_device = None
running = True


def cleanup():
    """Clear the LCD and release sensor resources on exit."""
    global lcd, dht_device
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global running
    running = False


def init_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None


def init_lcd(i2c_bus):
    """Initialize the 16x2 I2C LCD; return the lcd object or None on failure."""
    try:
        lcd = character_lcd.Character_LCD_I2C(
            i2c_bus, LCD_COLUMNS, LCD_ROWS, address=LCD_I2C_ADDRESS
        )
        lcd.clear()
        return lcd
    except Exception as e:
        print(f"Error initializing LCD at 0x{LCD_I2C_ADDRESS:02X}: {e}", file=sys.stderr)
        return None


def init_dht22():
    """Initialize the DHT22 sensor; return the device object or None on failure."""
    try:
        return adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Error initializing DHT22 on GPIO4: {e}", file=sys.stderr)
        return None


def read_dht22(dht_device):
    """Read temperature and humidity from the DHT22.

    Returns (temperature, humidity) or (None, None) on any error.
    """
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            print("Warning: DHT22 returned None for temperature or humidity.", file=sys.stderr)
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 checksum / timing errors are common; log and continue.
        print(f"DHT22 read error (checksum or timing): {e}", file=sys.stderr)
        return None, None
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}", file=sys.stderr)
        return None, None


def update_lcd(lcd, temperature, humidity):
    """Write temperature and humidity to the LCD."""
    try:
        line1 = f"Temp: {temperature:.1f} C" if temperature is not None else "Temp: N/A"
        line2 = f"Humidity: {humidity:.1f}%" if humidity is not None else "Humidity: N/A"
        lcd.message = f"{line1}\n{line2}"
    except Exception as e:
        print(f"Error updating LCD: {e}", file=sys.stderr)


def main():
    global lcd, dht_device

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = init_i2c()
    if i2c_bus is None:
        sys.exit(1)

    lcd = init_lcd(i2c_bus)
    if lcd is None:
        sys.exit(1)

    dht_device = init_dht22()
    if dht_device is None:
        sys.exit(1)

    print("Starting DHT22 + LCD display. Press Ctrl+C to exit.")

    try:
        while running:
            temperature, humidity = read_dht22(dht_device)
            update_lcd(lcd, temperature, humidity)
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as e:
        print(f"Unexpected runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

