logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class GifPlayer:
    """
    Plays GIF animations on an SPI-connected ST7789 display on a Raspberry Pi.
    """

    def __init__(self, display_width: int = 240, display_height: int = 240, folder: str = "gifs"):
        self.display_width = display_width
        self.display_height = display_height
        self.folder = folder
        self.gif_files: List[str] = []
        self.device: Optional[st7789] = None
        self._running = True

        self._setup_signal_handlers()

    def _setup_signal_handlers(self) -> None:
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._signal_handler)

    def _signal_handler(self, signum, frame) -> None:
        logger.info(f"Received signal {signum}, shutting down...")
        self._running = False

    def initialize(self) -> None:
        """Initializes the SPI interface and ST7789 display."""
        try:
            serial = spi(port=0, device=0, bus_speed_hz=40000000)
            self.device = st7789(serial, width=self.display_width, height=self.display_height)
            logger.info("Display initialized successfully.")
        except Exception as e:
            logger.error(f"Failed to initialize display: {e}")
            raise

    def load_gif_files(self) -> None:
        """Loads GIF file paths from the specified folder."""
        try:
            self.gif_files = sorted(
                f for f in os.listdir(self.folder) if f.lower().endswith(".gif")
            )
            if not self.gif_files:
                raise FileNotFoundError(f"No GIF files found in folder: {self.folder}")
            logger.info(f"Loaded {len(self.gif_files)} GIF files.")
        except FileNotFoundError as e:
            logger.error(str(e))
            raise
        except Exception as e:
            logger.error(f"Error loading GIF files: {e}")
            raise

    def play(self, gif_path: str) -> None:
        """Plays a single GIF file."""
        try:
            with Image.open(gif_path) as image:
                logger.info(f"Playing GIF: {gif_path}")
                while self._running:
                    for frame in range(image.n_frames):
                        if not self._running:
                            break
                        image.seek(frame)
                        duration = image.info.get("duration", 100)
                        frame_image = image.convert("RGB")
                        padded_image = ImageOps.pad(
                            frame_image,
                            (self.display_width, self.display_height),
                            method=Image.NEAREST,
                            color=(0, 0, 0),
                            centering=(0.5, 0.5),
                        )
                        self._update_display(padded_image)
                        time.sleep(duration / 1000.0)
        except FileNotFoundError as e:
            logger.error(f"GIF file not found: {e}")
        except Exception as e:
            logger.error(f"Error playing GIF: {e}")

    def _update_display(self, image: Image.Image) -> None:
        """Updates the display with the given image."""
        if self.device is None:
            logger.warning("Display not initialized, skipping update.")
            return
        try:
            self.device.display(image)
        except Exception as e:
            logger.error(f"Error updating display: {e}")

    def run(self) -> None:
        """Runs the GIF player indefinitely."""
        try:
