import time
import logging
from PIL import Image, ImageOps
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class GIFPlayer:
    def __init__(self, i2c_port=1, i2c_address=0x3C, gif_folder=""):
        self.i2c_port = i2c_port
        self.i2c_address = i2c_address
        self.gif_folder = gif_folder
        self.gif_files = []
        self.device = None
        self.running = True
        self.load_gif_files()

    def load_gif_files(self):
        if not os.path.isdir(self.gif_folder):
            logging.error(f"Folder not found: {self.gif_folder}")
            return
        try:
            self.gif_files = sorted([f for f in os.listdir(self.gif_folder) if f.lower().endswith(".gif")])
            if not self.gif_files:
                logging.warning(f"No GIF files found in {self.gif_folder}")
        except OSError as e:
            logging.error(f"Error accessing folder {self.gif_folder}: {e}")

    def initialize_display(self):
        try:
            serial = i2c(port=self.i2c_port, address=self.i2c_address)
            self.device = ssd1306(serial, width=128, height=64)
            logging.info(f"SSD1306 display initialized at I2C address 0x{self.i2c_address:02X}")
        except Exception as e:
            logging.error(f"Failed to initialize display: {e}")
            self.device = None

    def play_gif(self, gif_path, loop_count=0):
        if not self.device:
            logging.error("Display not initialized. Cannot play GIF.")
            return
        try:
            with Image.open(gif_path) as image:
                if getattr(image, 'is_animated', False):
                    frames = []
                    for frame_index in range(image.n_frames):
                        image.seek(frame_index)
                        frame = ImageOps.pad(image.convert('RGB'), (128, 64), method=Image.NEAREST, color=(0, 0, 0))
                        frames.append(frame)
                    durations = [image.info.get('duration', 100)] * len(frames)
                    loop = image.info.get('loop', 0)
                    if loop_count == 0:
                        loop_count = float('inf')
                    else:
                        loop_count = int(loop_count)
                    current_frame = 0
                    while self.running and current_frame < loop_count:
                        for frame in frames:
                            if not self.running:
                                break
                            self.display_frame(frame)
                            time.sleep(durations[current_frame] / 1000.0)
                        current_frame += 1
                else:
                    logging.warning(f"File {gif_path} is not an animated GIF.")
        except FileNotFoundError:
            logging.error(f"GIF file not found: {gif_path}")
        except Exception as e:
            logging.error(f"Error playing GIF {gif_path}: {e}")

    def display_frame(self, image):
        try:
            with canvas(self.device) as draw:
                draw.bitmap((0, 0), image.convert('1'))
        except Exception as e:
            logging.error(f"Error displaying frame: {e}")

    def signal_handler(self, signum, frame):
        logging.info("SIGINT received. Exiting gracefully...")
        self.running = False

    def run(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        if not self.gif_files:
            logging.info("No GIF files to play. Exiting.")
            return
        self.initialize_display()
        if self.device:
            for gif_file in self.gif_files:
                if not self.running:
                    break
                gif_path = os.path.join(self.gif_folder, gif_file)
                logging.info(f"Playing GIF: {gif_path}")
                self.play_gif(gif_path, loop_count=0)
            self.cleanup()
        else:
            logging.error("Display initialization failed. Exiting.")

    def cleanup(self):
        if self.device:
            try:
                self.device.cleanup()
                logging.info("Display resources released.")
            except Exception as e:
                logging.error(f"Error during cleanup: {e}")

if __name__ == "__main__":
    player = GIFPlayer(gif_folder="path/to/your/gif/folder")
    player.run()

