import RPi.GPIO as GPIO
import time
import signal
import sys

TRIG = 17
ECHO = 18
SPEED_OF_SOUND = 34300.0
TANK_HEIGHT = 50.0
MAX_DISTANCE_CM = 400.0
MIN_DISTANCE_CM = 2.0
ECHO_TIMEOUT_S = 0.03
LOOP_INTERVAL_S = 2.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(TRIG, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(ECHO, GPIO.IN)
    time.sleep(0.2)

def measure_distance():
    GPIO.output(TRIG, GPIO.LOW)
    time.sleep(0.00001)
    GPIO.output(TRIG, GPIO.HIGH)
    time.sleep(0.00001)
    GPIO.output(TRIG, GPIO.LOW)

    deadline = time.time() + ECHO_TIMEOUT_S
    while GPIO.input(ECHO) == 0:
        if time.time() > deadline:
            return None
    pulse_start = time.time()

    deadline = time.time() + ECHO_TIMEOUT_S
    while GPIO.input(ECHO) == 1:
        if time.time() > deadline:
            return None
    pulse_end = time.time()

    duration = pulse_end - pulse_start
    distance = duration * SPEED_OF_SOUND / 2.0
    return distance

def compute_water_level(distance):
    if distance is None or distance < MIN_DISTANCE_CM or distance > MAX_DISTANCE_CM:
        return None
    water_level = TANK_HEIGHT - distance
    return max(0.0, min(water_level, TANK_HEIGHT))

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        setup_gpio()
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)
    try:
        while _running:
            try:
                distance = measure_distance()
                water_level = compute_water_level(distance)
                if distance is not None:
                    print(f"Distance: {distance:.2f} cm")
                if water_level is not None:
                    print(f"Water Level: {water_level:.2f} cm")
                else:
                    print("Invalid measurement, skipping.")
            except Exception as e:
                print(f"Measurement error: {e}", file=sys.stderr)
            for _ in range(int(LOOP_INTERVAL_S * 10)):
                if not _running:
                    break
                time.sleep(0.1)
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

