import math
import signal
import sys
import time

from gpiozero import PWMOutputDevice

# Motor control pins (left motor: GPIO12/13, right motor: GPIO18/19)
LEFT_MOTOR_FORWARD_PIN = 12
LEFT_MOTOR_BACKWARD_PIN = 13
RIGHT_MOTOR_FORWARD_PIN = 18
RIGHT_MOTOR_BACKWARD_PIN = 19

# Constants
MAX_ITERATIONS = 1000
SLEEP_TIME = 0.1
TURN_THRESHOLD = 175.0
GOAL_DISTANCE_THRESHOLD = 10.0
IMAGE_POINT_EXTENSION = 50
CAR_FRONT = (180, -15)
CAR_BACK = (200, -15)
BALL = (180, -200)
GOAL = (0, 200)

# Global motor objects for cleanup
motors = []


def angle(a1, a2):
    """Return the signed angle in degrees between two points from the origin."""
    return math.degrees(math.atan2(a2[1], a2[0]) - math.atan2(a1[1], a1[0]))


def distance(p1, p2):
    """Return the Euclidean distance between two points."""
    return math.hypot(p1[0] - p2[0], p1[1] - p2[1])


def compute_image_point(ball, goal, extension):
    """Compute the image point beyond the ball on the line to the goal."""
    d = distance(ball, goal)
    if d == 0:
        raise ValueError("Goal and ball are at the same point; cannot compute line.")
    scale = d / distance(ball, goal) + extension / d
    return (int(ball[0] + (goal[0] - ball[0]) * scale),
            int(ball[1] + (goal[1] - ball[1]) * scale))


def control_loop(ball, car_front, car_back, goal, extension):
    """Main control loop for intercepting the ball and reaching the goal."""
    image_point = compute_image_point(ball, goal, extension)

    # Initialize motor PWM devices
    try:
        left_fwd = PWMOutputDevice(LEFT_MOTOR_FORWARD_PIN, initial_value=0)
        left_bwd = PWMOutputDevice(LEFT_MOTOR_BACKWARD_PIN, initial_value=0)
        right_fwd = PWMOutputDevice(RIGHT_MOTOR_FORWARD_PIN, initial_value=0)
        right_bwd = PWMOutputDevice(RIGHT_MOTOR_BACKWARD_PIN, initial_value=0)
        motors.extend([left_fwd, left_bwd, right_fwd, right_bwd])
    except Exception as e:
        print(f"Error initializing motors: {e}")
        return

    def stop_motors():
        for m in motors:
            try:
                m.value = 0
            except Exception:
                pass

    def cleanup(signum=None, frame=None):
        stop_motors()
        for m in motors:
            try:
                m.close()
            except Exception:
                pass
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        while True:
            # Calculate angles
            angle_to_image = angle(car_back, image_point)
            angle_to_goal = angle(car_back, goal)

            # Calculate distances
            dist_to_image = distance(car_front, image_point)
            dist_to_goal = distance(car_front, goal)

            print(f"Ball: {ball}, Image Point: {image_point}, Goal: {goal}")
            print(f"Angle to Image: {angle_to_image:.2f}, Angle to Goal: {angle_to_goal:.2f}")
            print(f"Distance to Image: {dist_to_image:.2f}, Distance to Goal: {dist_to_goal:.2f}")

            if abs(angle_to_goal) < TURN_THRESHOLD:
                if angle_to_goal < 0:
                    print("Turning Right")
                    left_fwd.value = 0.2
                    right_bwd.value = 0.2
                else:
                    print("Turning Left")
                    right_fwd.value = 0.2
                    left_bwd.value = 0.2
            elif dist_to_goal > GOAL_DISTANCE_THRESHOLD:
                print("Moving Forward")
                left_fwd.value = 0.5
                right_fwd.value = 0.5
            elif abs(angle_to_image) < TURN_THRESHOLD:
                if angle_to_image < 0:
                    print("Turning Right")
                    left_fwd.value = 0.2
                    right_bwd.value = 0.2
                else:
                    print("Turning Left")
                    right_fwd.value = 0.2
                    left_bwd.value = 0.2
            elif dist_to_image > GOAL_DISTANCE_THRESHOLD:
