import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
PCF8574_ADDR = 0x20
POLL_INTERVAL_S = 0.1
RETRY_DELAY_S = 1.0

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    msg = i2c_msg.write(PCF8574_ADDR, [reg, value & 0xFF])
    bus.i2c_rdwr(msg)


def _read_reg(bus, reg):
    write_msg = i2c_msg.write(PCF8574_ADDR, [reg])
    read_msg = i2c_msg.read(PCF8574_ADDR, 1)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)[0]


def main():
    global running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            _write_reg(bus, 0x00, 0xFF)
        except OSError as exc:
            print(f"Error: cannot configure PCF8574 at 0x{PCF8574_ADDR:02X}: {exc}", file=sys.stderr)
            print("Check wiring (SDA=GPIO3, SCL=GPIO5) and that the expander is powered.", file=sys.stderr)
            return

        while running:
            try:
                port = _read_reg(bus, 0x00)
            except OSError as exc:
                print(f"I2C read error: {exc}", file=sys.stderr)
                time.sleep(RETRY_DELAY_S)
                continue

            for sensor_num in range(8):
                if not (port & (1 << sensor_num)):
                    print(f"Obstacle detected by sensor {sensor_num}")

            time.sleep(POLL_INTERVAL_S)
    finally:
        try:
            bus.close()
        except OSError:
            pass


if __name__ == "__main__":
    main()

