#!/usr/bin/env python3
"""
Clean Energy Monitoring System (Simulated)

Simulates sensor readings on GPIO17 (light) and GPIO4 (temperature)
using gpiozero.InputDevice. Reads the Raspberry Pi's internal
temperature via vcgencmd. Logs every 5 seconds with timestamps.
"""

import time
import datetime
import random
import subprocess
import sys
import signal

try:
    from gpiozero import InputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LIGHT_PIN = 17
TEMP_PIN = 4
LIGHT_THRESHOLD = 300          # lux
TEMP_THRESHOLD = 35            # °C
PI_TEMP_THRESHOLD = 75         # °C
SAMPLE_INTERVAL = 5            # seconds

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_devices = []
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def setup_gpio():
    """Initialize GPIO17 and GPIO4 as simulated input pins."""
    global _devices
    try:
        light_sensor = InputDevice(LIGHT_PIN, pull_up=False)
        temp_sensor = InputDevice(TEMP_PIN, pull_up=False)
        _devices = [light_sensor, temp_sensor]
        print(f"GPIO setup complete: light=GPIO{LIGHT_PIN}, temp=GPIO{TEMP_PIN}")
    except Exception as e:
        print(f"Error during GPIO setup: {e}")
        raise


def simulate_light_level():
    """Simulate light level (lux) based on time of day."""
    now = datetime.datetime.now()
    hour = now.hour
    if 6 <= hour < 18:
        return random.randint(600, 1000)
    else:
        return random.randint(100, 300)


def simulate_temperature():
    """Simulate temperature (°C)."""
    return random.uniform(20, 30)


def simulate_voltage_and_current(light_level):
    """Simulate voltage (V) and current (A) based on light level."""
    if light_level > LIGHT_THRESHOLD:
        return random.uniform(11.5, 12.5), random.uniform(1.5, 2.5)
    else:
        return random.uniform(10.0, 11.0), random.uniform(0.5, 1.0)


def get_pi_temperature():
    """
    Read Raspberry Pi internal temperature via vcgencmd.
    Returns float °C or None on failure.
    """
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        # Expected output: temp=42.8'C
        temp_str = result.stdout.strip()
        if not temp_str.startswith("temp="):
            print(f"Warning: unexpected vcgencmd output: {temp_str!r}")
            return None
        temp_c = float(temp_str.split("=")[1].split("'")[0])
        return temp_c
    except FileNotFoundError:
        print("Warning: vcgencmd not found. Install with: sudo apt install libraspberrypi-bin")
        return None
    except subprocess.TimeoutExpired:
        print("Warning: vcgencmd timed out.")
        return None
    except subprocess.CalledProcessError as e:
        print(f"Warning: vcgencmd failed (rc={e.returncode}): {e.stderr.strip()}")
        return None
    except (IndexError, ValueError) as e:
        print(f"Warning: could not parse vcgencmd output: {e}")
        return None
    except Exception as e:
        print(f"Warning: unexpected error reading Pi temperature: {e}")
        return None


def log_data(light_level, temperature, voltage, current, pi_temperature):
    """Print a timestamped log line."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(
        f"{timestamp} - Light: {light_level} lux, "
        f"Temp: {temperature:.2f}°C, "
        f"Voltage: {voltage:.2f}V, "
        f"Current: {current:.2f}A, "
        f"Pi Temp: {pi_temperature if pi_temperature is not None else 'N/A'}°C"
    )


def check_thresholds(light_level, temperature, pi_temperature):
    """Check thresholds and print warnings/critical messages."""
    if light_level < LIGHT_THRESHOLD:
        print("WARNING: Light level below threshold. Possible solar panel performance issues.")
    if temperature > TEMP_THRESHOLD:
        print("WARNING: Temperature above threshold. Simulating cooling system activation.")
    if pi_temperature is not None and pi_temperature > PI_TEMP_THRESHOLD:
        print("CRITICAL: Pi temperature above threshold. Simulating system shutdown.")


def cleanup():
    """Close all gpiozero device objects."""
    global _devices
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass
    _devices.clear()
    print("GPIO cleanup complete.")


def main():
    """Main loop: simulate sensors, log data, check thresholds."""
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception:
        print("Fatal: GPIO setup failed. Exiting.")
        cleanup()
        sys.exit(1)

    try:
        while _running:
            try:
                light_level = simulate_light_level()
                temperature = simulate_temperature()
                voltage, current = simulate_voltage_and_current(light_level)
                pi_temperature = get_pi_temperature()

                log_data(light_level, temperature, voltage, current, pi_temperature)
                check_thresholds(light_level, temperature, pi_temperature)

            except Exception as e:
                print(f"Error during sensor simulation: {e}")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < SAMPLE_INTERVAL:
                time.sleep(0.5)
                slept += 0.5

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

