import csv
import os
import signal
import sys
import time
from datetime import datetime

import adafruit_dht
from board import D4

DATA_DIR = '/home/pi/data'
CSV_FILE = os.path.join(DATA_DIR, 'sensor_data.csv')
ERROR_LOG = os.path.join(DATA_DIR, 'error.log')
DHT_PIN = D4

running = True


def log_error(message: str) -> None:
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        with open(ERROR_LOG, 'a') as f:
            f.write(f'{timestamp} - {message}\n')
    except OSError as e:
        print(f'Failed to write to error log: {e}', file=sys.stderr)


def signal_handler(signum, frame):
    global running
    running = False


def main() -> int:
    global running

    os.makedirs(DATA_DIR, exist_ok=True)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    dht_device = None
    csv_file = None
    writer = None

    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        log_error(f'Failed to initialize DHT22 on GPIO4: {e}')
        return 1

    try:
        csv_file = open(CSV_FILE, 'w', newline='')
        writer = csv.writer(csv_file)
        writer.writerow(['Timestamp', 'Temperature_C'])
        csv_file.flush()
    except OSError as e:
        log_error(f'Failed to open CSV file {CSV_FILE}: {e}')
        return 1

    try:
        while running:
            try:
                temperature_c = dht_device.temperature
                if temperature_c is None:
                    raise RuntimeError('Sensor returned None for temperature')

                timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                writer.writerow([timestamp, f'{temperature_c:.2f}'])
                csv_file.flush()
                print(f'{timestamp} - Temperature: {temperature_c:.2f} C')

            except RuntimeError as e:
                log_error(f'Sensor read failed: {e}')
            except Exception as e:
                log_error(f'Unexpected error reading sensor: {e}')

            time.sleep(2)

    finally:
        if csv_file is not None:
            try:
                csv_file.close()
            except OSError:
                pass
        if dht_device is not None:
            try:
                dht_device.exit()
            except Exception:
                pass

    return 0


if __name__ == '__main__':
    sys.exit(main())

