import time
import logging
import signal
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    I2C_BUS = 1
    I2C_ADDRESS = 0x38
    MEASUREMENT_DELAY = 0.5
    MEASUREMENT_TIMEOUT = 0.1
    RETRY_DELAY = 2
    MAX_RETRIES = 5
    STATUS_REG = 0x71
    MEASURE_REG = 0xAC

    def __init__(self, bus_number=I2C_BUS, address=I2C_ADDRESS):
        self.address = address
        self.bus = None
        try:
            self.bus = smbus2.SMBus(bus_number)
            time.sleep(self.MEASUREMENT_DELAY)
            status = self.bus.read_byte_data(self.address, self.STATUS_REG)
            if (status & 0x18) != 0x18:
                logger.error(f"DHT20 not ready at address 0x{address:02X}, status=0x{status:02X}")
                self.close()
                raise RuntimeError("DHT20 not ready")
            logger.info(f"DHT20 initialized on bus {bus_number} at address 0x{address:02X}")
        except Exception as e:
            logger.error(f"Failed to initialize DHT20: {e}")
            self.close()
            raise

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None

    def _read_raw(self):
        data = self.bus.read_i2c_block_data(self.address, self.STATUS_REG, 7)
        raw_h = (data[1] << 12) | (data[2] << 4) | (data[3] >> 4)
        raw_t = ((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]
        return raw_t, raw_h

    @staticmethod
    def _crc8(data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def get_temperature_and_humidity(self):
        for attempt in range(1, self.MAX_RETRIES + 1):
            try:
                self.bus.write_i2c_block_data(self.address, self.MEASURE_REG, [0x33, 0x00])
                start = time.time()
                while True:
                    status = self.bus.read_byte_data(self.address, self.STATUS_REG)
                    if (status & 0x80) == 0:
                        break
                    if time.time() - start > self.MEASUREMENT_TIMEOUT:
                        logger.warning("Measurement timeout, retrying...")
                        break
                    time.sleep(0.01)
                raw_t, raw_h = self._read_raw()
                crc = self._crc8([0x33, 0x00, raw_t >> 16, raw_t >> 8, raw_t & 0xFF, raw_h >> 8])
                if crc != (raw_h & 0xFF):
                    logger.warning(f"CRC mismatch, retrying (attempt {attempt}/{self.MAX_RETRIES})")
                    time.sleep(self.RETRY_DELAY)
                    continue
                temperature = raw_t / 5242.88 - 50
                humidity = raw_h / 1048576.0 * 100.0
                return temperature, humidity, False
            except Exception as e:
                logger.error(f"Error during measurement (attempt {attempt}/{self.MAX_RETRIES}): {e}")
                if attempt < self.MAX_RETRIES:
                    time.sleep(self.RETRY_DELAY)
        logger.error("Failed to get temperature and humidity after multiple retries.")
        return None, None, True

    def __del__(self):
        self.close()


def main():
    sensor = None
    def signal_handler(sig, frame):
        logger.info("Interrupt received, shutting down.")
        if sensor is not None:
            sensor.close()
        exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        sensor = DHT20()
        temp, hum, crc_err = sensor.get_temperature_and_humidity()
        if temp is not None and hum is not None:
            logger.info(f"Temperature: {temp:.2f} C, Humidity: {hum:.2f} %, CRC: {'OK' if not crc_err else 'ERROR'}")
        else:
            logger.error("Failed to retrieve data.")
    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        if sensor is not None:
            sensor.close()


if __name__ == "__main__":
    main()

