import time
import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT20_I2C_ADDRESS = 0x38
DHT20_STATUS_REG = 0x71
DHT20_MEASURE_REG = 0xAC
DHT20_MEASURE_CMD = [0x33, 0x00]
MEASURE_TIMEOUT = 0.1
POLL_INTERVAL = 0.01


class DHT20:
    def __init__(self, i2c_bus_number=1):
        self.bus = None
        self._running = True
        try:
            self.bus = SMBus(i2c_bus_number)
            logging.info(f"Opened I2C bus {i2c_bus_number}")
        except Exception as e:
            logging.error(f"Failed to open I2C bus {i2c_bus_number}: {e}")
            self.bus = None
            return

        if not self._check_sensor():
            logging.error("DHT20 sensor not detected at address 0x38")
            self.close()
            self.bus = None
            return

    def _check_sensor(self):
        if self.bus is None:
            return False
        try:
            data = self.bus.read_i2c_block_data(DHT20_I2C_ADDRESS, DHT20_STATUS_REG, 1)
            if data[0] != 0x71:
                logging.warning(f"Unexpected status byte 0x{data[0]:02X}, expected 0x71")
                return False
            return True
        except Exception as e:
            logging.error(f"Error checking sensor: {e}")
            return False

    def measure(self):
        if self.bus is None:
            logging.error("I2C bus not initialized")
            return None, None, True

        try:
            self.bus.write_i2c_block_data(DHT20_I2C_ADDRESS, DHT20_MEASURE_REG, DHT20_MEASURE_CMD)
        except Exception as e:
            logging.error(f"Failed to send measurement command: {e}")
            return None, None, True

        start_time = time.time()
        while time.time() - start_time < MEASURE_TIMEOUT:
            try:
                status = self.bus.read_i2c_block_data(DHT20_I2C_ADDRESS, DHT20_STATUS_REG, 1)[0]
            except Exception as e:
                logging.error(f"Error reading status: {e}")
                return None, None, True
            if not (status & 0x80):
                break
            time.sleep(POLL_INTERVAL)
        else:
            logging.error("Measurement timeout")
            return None, None, True

        try:
            data = self.bus.read_i2c_block_data(DHT20_I2C_ADDRESS, DHT20_STATUS_REG, 7)
        except Exception as e:
            logging.error(f"Failed to read measurement data: {e}")
            return None, None, True

        if len(data) < 7:
            logging.error(f"Incomplete data read: got {len(data)} bytes, expected 7")
            return None, None, True

        crc_error = self._calculate_crc(data) != data[6]
        if crc_error:
            logging.warning("CRC error detected")

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        temperature = float(temperature_raw) / 5242.88 - 50.0
        humidity = float(humidity_raw) / 0x100000 * 100.0

        return temperature, humidity, crc_error

    def _calculate_crc(self, data):
        crc = 0xFF
        for byte in data[:6]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
                logging.info("I2C bus closed")
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None

    def stop(self):
        self._running = False


def main():
    sensor = DHT20(i2c_bus_number=1)
    if sensor.bus is None:
        logging.error("Failed to initialize DHT20 sensor. Exiting.")
        sys.exit(1)

    def signal_handler(signum, frame):
        logging.info(f"Signal {signum} received, shutting down...")
        sensor.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        temperature, humidity, crc_error = sensor.measure()
        if temperature is not None and humidity is not None:
            logging.info(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, CRC Error: {crc_error}")
        else:
            logging.error("Failed to read sensor data.")
    finally:
        sensor.close()


if __name__ == "__main__":
    main()

