import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Initialize I2C bus on GPIO3 (SCL) and GPIO2 (SDA)
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Fatal: Failed to initialize I2C bus: {e}")
    raise SystemExit(1)

# Initialize TCA9548A I2C multiplexer at address 0x70
try:
    i2c_multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
except Exception as e:
    print(f"Fatal: Failed to initialize TCA9548A multiplexer at 0x70: {e}")
    raise SystemExit(1)

# Initialize BME280 sensor on multiplexer channel 0 (default I2C address 0x76)
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_multiplexer, address=0x76)
except Exception as e:
    print(f"Fatal: Failed to initialize BME280 on channel 0: {e}")
    raise SystemExit(1)

# Initialize TSL2591 sensor on multiplexer channel 1 (default I2C address 0x29)
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_multiplexer, address=0x29)
except Exception as e:
    print(f"Fatal: Failed to initialize TSL2591 on channel 1: {e}")
    raise SystemExit(1)

# Main loop to read and print sensor data every 2 seconds
try:
    while True:
        # Read BME280 data
        try:
            temperature = bme280_sensor.temperature
            humidity = bme280_sensor.humidity
        except Exception as e:
            print(f"Warning: Failed to read BME280: {e}")
            temperature = None
            humidity = None

        # Read TSL2591 data
        try:
            light_intensity = tsl2591_sensor.lux
        except Exception as e:
