            print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light: {light_intensity:.2f} lux")
        else:
            print("Sensor data unavailable.")

        time.sleep(2)

except KeyboardInterrupt:
    print("\nExiting program.")
finally:
    # Clean up resources on all exit paths
    try:
        i2c_bus.deinit()
    except Exception:
        pass

