import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Initialize I2C bus on GPIO3 (SCL) and GPIO2 (SDA)
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    raise SystemExit(1)

# Initialize TCA9548A I2C multiplexer at default address 0x70
try:
    i2c_multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
except Exception as e:
    print(f"Error initializing TCA9548A multiplexer: {e}")
    raise SystemExit(1)

# Initialize BME280 sensor on multiplexer channel 0 (default 0x76 or 0x77)
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_multiplexer, address=0x76)
except Exception as e:
    print(f"Error initializing BME280 sensor: {e}")
    raise SystemExit(1)

# Initialize TSL2591 sensor on multiplexer channel 1 (default 0x29)
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_multiplexer, address=0x29)
except Exception as e:
    print(f"Error initializing TSL2591 sensor: {e}")
    raise SystemExit(1)

# Main loop for continuous sensor readings
try:
    while True:
        # Read temperature and humidity from BME280
        try:
            temperature_value = bme280_sensor.temperature
            humidity_value = bme280_sensor.humidity
        except Exception as e:
            print(f"Error reading BME280 sensor: {e}")
            temperature_value = None
            humidity_value = None

        # Read light intensity (lux) from TSL2591
        try:
            light_intensity_value = tsl2591_sensor.lux
        except Exception as e:
            print(f"Error reading TSL2591 sensor: {e}")
            light_intensity_value = None

        # Print sensor readings with two decimal places
        if temperature_value is not None and humidity_value is not None:
            print(f"Temperature: {temperature_value:.2f} C")
            print(f"Humidity: {humidity_value:.2f} %")
        else:
            print("Temperature and/or Humidity reading failed.")

        if light_intensity_value is not None:
            print(f"Light Intensity: {light_intensity_value:.2f} lux")
        else:
            print("Light Intensity reading failed.")

        print()  # Add a newline for better readability
        time.sleep(2)  # Wait for 2 seconds before the next reading

except KeyboardInterrupt:
    print("Program terminated by user.")

