import serial
import serial.tools.list_ports
import csv
import time
import sys
import signal

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
READ_TIMEOUT = 1.0
LOG_FILE = 'temperature_log.csv'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def open_serial_port():
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"Error: serial port {SERIAL_PORT} unavailable: {exc}", file=sys.stderr)
        return None

def write_csv_header(path):
    try:
        with open(path, 'x', newline='') as fh:
            csv.writer(fh).writerow(['timestamp', 'celsius', 'fahrenheit'])
    except FileExistsError:
        pass
    except OSError as exc:
        print(f"Error: cannot create log file {path}: {exc}", file=sys.stderr)
        raise

def append_reading(path, celsius, fahrenheit):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    try:
        with open(path, 'a', newline='') as fh:
            csv.writer(fh).writerow([timestamp, f'{celsius:.2f}', f'{fahrenheit:.2f}'])
    except OSError as exc:
        print(f"Warning: failed to write log entry: {exc}", file=sys.stderr)

def process_line(line):
    line = line.decode('ascii', errors='replace').strip()
    if not line:
        return
    try:
        celsius = float(line)
    except ValueError:
        print(f"Warning: non-numeric data received: {line!r}", file=sys.stderr)
        return
    fahrenheit = celsius * 9.0 / 5.0 + 32.0
    print(f"Temperature: {celsius:.2f}°C / {fahrenheit:.2f}°F")
    append_reading(LOG_FILE, celsius, fahrenheit)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    try:
        write_csv_header(LOG_FILE)
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                break
            if not raw:
                continue
            process_line(raw)
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

