import RPi.GPIO as GPIO
import time
import sys

DHT_PIN = 4
RETRY_DELAY = 2
MAX_RETRIES = 3
RETRY_BACKOFF = 5
READ_INTERVAL = 5

def read_dht22(pin):
    """Read temperature and humidity from a DHT22 sensor using the full one-wire protocol."""
    # Send start signal: pull low for >= 18 ms, then release
    GPIO.setup(pin, GPIO.OUT)
    GPIO.output(pin, GPIO.LOW)
    time.sleep(0.02)  # 20 ms well above 18 ms
    GPIO.output(pin, GPIO.HIGH)
    time.sleep(0.000040)  # 40 µs settle

    # Switch to input and wait for response: 80 µs low, 80 µs high
    GPIO.setup(pin, GPIO.IN)
    timeout = time.time() + 0.0001  # 100 µs timeout
    while GPIO.input(pin) == GPIO.HIGH:
        if time.time() > timeout:
            return None, None
    timeout = time.time() + 0.0001
    while GPIO.input(pin) == GPIO.LOW:
        if time.time() > timeout:
            return None, None
    timeout = time.time() + 0.0001
    while GPIO.input(pin) == GPIO.HIGH:
        if time.time() > timeout:
            return None, None

    # Read 40 bits (5 bytes) as 0/1
    data = []
    for _ in range(40):
        timeout = time.time() + 0.0001
        while GPIO.input(pin) == GPIO.LOW:
            if time.time() > timeout:
                return None, None
        start = time.time()
        timeout = time.time() + 0.0001
        while GPIO.input(pin) == GPIO.HIGH:
            if time.time() > timeout:
                return None, None
        duration = time.time() - start
        data.append(1 if duration > 0.000050 else 0)  # 50 µs threshold

    if len(data) != 40:
        return None, None

    # Combine bits into bytes
    bytes_data = []
    for i in range(5):
        byte = 0
        for j in range(8):
            byte = (byte << 1) | (1 if data[i * 8 + j] else 0)
        bytes_data.append(byte)

    humidity_int, humidity_dec, temp_int, temp_dec, checksum = bytes_data

    # Validate checksum: sum of first 4 bytes mod 256 == 5th byte
    if (humidity_int + humidity_dec + temp_int + temp_dec) % 256 != checksum:
        return None, None

    # Convert to decimal
    humidity = humidity_int + humidity_dec / 10.0
    temperature = temp_int + temp_dec / 10.0

    return temperature, humidity

def main():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    try:
        while True:
            temperature, humidity = None, None
            for attempt in range(1, MAX_RETRIES + 1):
                try:
                    temperature, humidity = read_dht22(DHT_PIN)
                    if temperature is not None and humidity is not None:
                        print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                        time.sleep(READ_INTERVAL)
                        break
                    else:
                        print(f"Attempt {attempt}/{MAX_RETRIES}: sensor returned invalid data")
                except Exception as e:
                    print(f"Attempt {attempt}/{MAX_RETRIES}: read error: {e}")
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY)
            else:
                print(f"Error: Failed to read DHT22 after {MAX_RETRIES} attempts. Retrying in {RETRY_BACKOFF} seconds.")
                time.sleep(RETRY_BACKOFF)
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

