            byte = (byte << 1) | (1 if data[i * 8 + j] else 0)
        bytes_data.append(byte)

    humidity_int, humidity_dec, temp_int, temp_dec, checksum = bytes_data

    # Validate checksum: sum of first 4 bytes mod 256 == 5th byte
    if (humidity_int + humidity_dec + temp_int + temp_dec) % 256 != checksum:
        return None, None

    # Convert to decimal
    humidity = humidity_int + humidity_dec / 10.0
    temperature = temp_int + temp_dec / 10.0

    return temperature, humidity

def main():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    try:
        while True:
            temperature, humidity = None, None
            for attempt in range(1, MAX_RETRIES + 1):
                try:
                    temperature, humidity = read_dht22(DHT_PIN)
                    if temperature is not None and humidity is not None:
