        return temperature, humidity
    except RuntimeError as e:
        logging.error(f"DHT22 read error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected DHT22 error: {e}")
        return None, None

def validate_data(temperature, humidity):
    if temperature is None or humidity is None:
        return False, "Invalid data (None)"
    if not -40 <= temperature <= 80:
        return False, f"Temperature out of range: {temperature}"
    if not 0 <= humidity <= 100:
        return False, f"Humidity out of range: {humidity}"
    return True, ""

def calculate_moving_average(data, window_size):
    if not data:
        return None
    if len(data) < window_size:
        return sum(data) / len(data)
    return sum(data[-window_size:]) / window_size

def send_webhook(url, data):
    try:
        json_data = json.dumps(data).encode('utf-8')
        req = urllib.request.Request(url, data=json_data, headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=10) as response:
