            validation_result, validation_message = validate_data(temperature, humidity)
            if not validation_result:
                logging.warning(f"Data validation failed: {validation_message}")
                sensor_failure_count += 1
                if sensor_failure_count >= config["max_sensor_read_failures"]:
                    logging.warning(f"Pausing data acquisition for {config['sensor_read_failure_pause']} seconds.")
                    time.sleep(config["sensor_read_failure_pause"])
