                for attempt in range(config["retry_attempts"]):
                    if send_webhook(config["webhook_url"], webhook_data):
                        break
                    else:
                        delay = config["retry_backoff"][attempt] if attempt < len(config["retry_backoff"]) else 1
                        logging.warning(f"Webhook failed. Retrying in {delay}s...")
                        time.sleep(delay)
            else:
                webhook_data["actuators"]["vent_fan"] = False

            if average_humidity is not None and average_humidity > config["humidity_threshold"]:
                logging.warning("Humidity threshold exceeded!")
                webhook_data["actuators"]["water_pump"] = True
                for attempt in range(config["retry_attempts"]):
                    if send_webhook(config["webhook_url"], webhook_data):
