            else:
                webhook_data["actuators"]["water_pump"] = False

            if average_temperature is not None and average_temperature < config["heater_threshold"]:
                logging.warning("Heater threshold exceeded!")
                webhook_data["actuators"]["heater"] = True
                for attempt in range(config["retry_attempts"]):
                    if send_webhook(config["webhook_url"], webhook_data):
