            else:
                webhook_data["actuators"]["heater"] = False

            control_actuators(average_temperature, average_humidity)

            time.sleep(config["sensor_read_interval"])

    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if dht_device:
            try:
                dht_device.exit()
            except Exception:
                pass
        logging.info("Greenhouse monitoring system stopped.")

if __name__ == "__main__":
    main()

