#!/usr/bin/env python3
"""
Home automation controller for Raspberry Pi.
Reads temperature/humidity from a DHT22 on GPIO4, simulates a light sensor,
controls a fan on GPIO17 and a light on GPIO27, and logs to SQLite.
"""

import argparse
import logging
import random
import signal
import sqlite3
import sys
import time
from datetime import datetime, timezone

import board
import adafruit_dht

try:
    from gpiozero import LED
    from gpiozero import Device
    from gpiozero.pins.mock import MockFactory
except Exception:  # pragma: no cover - hardware-specific
    LED = None
    Device = None
    MockFactory = None

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
DHT_PIN = board.D4
FAN_PIN = 17
LIGHT_PIN = 27
DATABASE = "home_automation.db"
TABLE = "sensor_data"
RETRY_COUNT = 3
RETRY_DELAY = 1.0
DEFAULT_INTERVAL = 60
DEFAULT_TEMP_OFFSET = 0.0
DEFAULT_HUMIDITY_OFFSET = 0.0
DEFAULT_LOG_LEVEL = "INFO"

fan = None
light = None
dht_device = None
running = True


def parse_args():
    p = argparse.ArgumentParser(description="Raspberry Pi Home Automation Controller")
    p.add_argument("--interval", type=int, default=DEFAULT_INTERVAL,
                   help="Sampling interval in seconds (default: 60)")
    p.add_argument("--temp-offset", type=float, default=DEFAULT_TEMP_OFFSET,
                   help="Temperature offset in Celsius (default: 0.0)")
    p.add_argument("--humidity-offset", type=float, default=DEFAULT_HUMIDITY_OFFSET,
                   help="Humidity offset in percent (default: 0.0)")
    p.add_argument("--log-level", type=str, default=DEFAULT_LOG_LEVEL,
                   choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"],
                   help="Logging level (default: INFO)")
    return p.parse_args()


def setup_logging(level):
    logging.basicConfig(
        level=getattr(logging, level.upper(), logging.INFO),
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def init_database():
    try:
        conn = sqlite3.connect(DATABASE, timeout=5)
        conn.execute(
            f"CREATE TABLE IF NOT EXISTS {TABLE} "
            "(timestamp TEXT PRIMARY KEY, temperature REAL, humidity REAL, "
            "light_level INTEGER, fan_state INTEGER, light_state INTEGER, "
            "synced INTEGER DEFAULT 0)"
        )
        conn.commit()
        conn.close()
        logging.info("Database initialized.")
    except sqlite3.Error as e:
        logging.error(f"Database initialization failed: {e}")
        sys.exit(1)


def init_hardware():
    global fan, light, dht_device
    if LED is None:
        logging.warning("gpiozero not available; running in mock mode.")
        if MockFactory is not None:
            try:
                Device.pin_factory = MockFactory()
            except Exception as e:
                logging.warning(f"Could not set mock pin factory: {e}")
    else:
        try:
            fan = LED(FAN_PIN)
            light = LED(LIGHT_PIN)
            fan.off()
            light.off()
            logging.info("GPIO outputs initialized (fan=GPIO17, light=GPIO27).")
        except Exception as e:
            logging.warning(f"GPIO output init failed (mock mode): {e}")
            fan = None
            light = None

    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        logging.info("DHT22 initialized on GPIO4.")
    except Exception as e:
        logging.warning(f"DHT22 init failed (mock mode): {e}")
        dht_device = None


def read_dht22():
    if dht_device is None:
        return None, None
    for attempt in range(1, RETRY_COUNT + 1):
        try:
            temp = dht_device.temperature
            hum = dht_device.humidity
            if temp is not None and hum is not None:
                return temp, hum
        except RuntimeError as e:
            logging.warning(f"DHT22 read attempt {attempt}/{RETRY_COUNT} failed: {e}")
        except Exception as e:
            logging.error(f"DHT22 unexpected error on attempt {attempt}: {e}")
        if attempt < RETRY_COUNT:
            time.sleep(RETRY_DELAY)
    logging.error("DHT22 read failed after all retries.")
    return None, None


def read_light_sensor():
    return random.randint(0, 1000)


def control_fan(temp):
    if temp is None:
        return
    if temp > 28.0:
        if fan is not None:
            fan.on()
        logging.info("Fan ON (temp > 28C).")
    elif temp < 25.0:
        if fan is not None:
            fan.off()
        logging.info("Fan OFF (temp < 25C).")


def control_light(light_level):
    if light_level is None:
        return
    if light_level < 200:
        if light is not None:
            light.on()
        logging.info("Light ON (light < 200).")
    elif light_level > 800:
        if light is not None:
            light.off()
        logging.info("Light OFF (light > 800).")


def log_data(timestamp, temp, hum, light_level, fan_state, light_state):
    try:
        conn = sqlite3.connect(DATABASE, timeout=5)
        conn.execute(
            f"INSERT OR REPLACE INTO {TABLE} "
            "(timestamp, temperature, humidity, light_level, fan_state, light_state) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (timestamp, temp, hum, light_level, fan_state, light_state),
        )
        conn.commit()
        conn.close()
        logging.debug("Data logged to database.")
    except sqlite3.Error as e:
        logging.error(f"Database insert failed: {e}")


def cleanup(signum=None, frame=None):
    global running
    running = False
    logging.info("Shutting down...")
    if fan is not None:
        try:
            fan.off()
            fan.close()
        except Exception:
            pass
    if light is not None:
        try:
            light.off()
            light.close()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global running
    args = parse_args()
    setup_logging(args.log_level)
    init_database()
    init_hardware()

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    logging.info("Home automation controller started.")

    while running:
        timestamp = datetime.now(timezone.utc).isoformat()
        temp, hum = read_dht22()
        if temp is not None:
            temp += args.temp_offset
        if hum is not None:
            hum += args.humidity_offset

        light_level = read_light_sensor()

        control_fan(temp)
        control_light(light_level)

        fan_state = 1 if (fan is not None and fan.is_active) else 0
        light_state = 1 if (light is not None and light.is_active) else 0

        log_data(timestamp, temp, hum, light_level, fan_state, light_state)

        for _ in range(args.interval):
            if not running:
                break
            time.sleep(1)

    cleanup()


if __name__ == "__main__":
    main()

