import time
import signal
import sys
import logging
import os
import paho.mqtt.client as mqtt
import adafruit_dht
import board

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT22Sensor:
    def __init__(self, pin):
        self.pin = pin
        self.sensor = None
        try:
            self.sensor = adafruit_dht.DHT22(self.pin, use_pulseio=False)
            time.sleep(2)
        except Exception as e:
            logging.error(f"Failed to initialize DHT22 on pin {self.pin}: {e}")

    def read(self):
        if not self.sensor:
            return None, None
        for attempt in range(3):
            try:
                temp = self.sensor.temperature
                hum = self.sensor.humidity
                if temp is not None and hum is not None:
                    return temp, hum
            except RuntimeError as e:
                logging.warning(f"DHT22 read attempt {attempt+1} failed: {e}")
            except Exception as e:
                logging.error(f"Unexpected DHT22 error: {e}")
            time.sleep(2)
        return None, None

    def cleanup(self):
        if self.sensor:
            try:
                self.sensor.exit()
            except Exception:
                pass

class MQTTClient:
    def __init__(self, config):
        self.config = config
        self.client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
        self.client.username_pw_set(config.mqttusername, config.mqttpassword)
        self.client.on_connect = self._on_connect
        self.client.on_disconnect = self._on_disconnect
        self.connected = False

    def _on_connect(self, client, userdata, flags, reason_code, properties):
        if reason_code == 0:
            self.connected = True
            self._publish_homie_discovery()
        else:
            logging.error(f"MQTT connection failed with reason code {reason_code}")

    def _on_disconnect(self, client, userdata, flags, reason_code, properties):
        self.connected = False
        logging.warning(f"MQTT disconnected (reason code {reason_code})")

    def connect(self):
        try:
            self.client.connect(self.config.mqttbroker, self.config.mqttport, keepalive=60)
            self.client.loop_start()
        except Exception as e:
            logging.error(f"MQTT connection error: {e}")

    def _publish_homie_discovery(self):
        base = f"homie/{self.config.homieclientid}"
        self.client.publish(f"{base}/$name", self.config.homieclientname, retain=True, qos=1)
        self.client.publish(f"{base}/$nodes", self.config.homienodes, retain=True, qos=1)
        node = self.config.homienodes
        self.client.publish(f"{base}/{node}/$name", "DHT22 Sensor", retain=True, qos=1)
        self.client.publish(f"{base}/{node}/$properties", "temperature,humidity", retain=True, qos=1)
        self.client.publish(f"{base}/{node}/temperature/$name", "Temperature", retain=True, qos=1)
        self.client.publish(f"{base}/{node}/temperature/$unit", "°C", retain=True, qos=1)
        self.client.publish(f"{base}/{node}/temperature/$datatype", "float", retain=True, qos=1)
        self.client.publish(f"{base}/{node}/humidity/$name", "Humidity", retain=True, qos=1)
        self.client.publish(f"{base}/{node}/humidity/$unit", "%", retain=True, qos=1)
        self.client.publish(f"{base}/{node}/humidity/$datatype", "float", retain=True, qos=1)

    def publish(self, topic, payload):
        if self.connected:
            try:
                self.client.publish(topic, payload, retain=True, qos=1)
            except Exception as e:
                logging.error(f"MQTT publish error: {e}")
        else:
            logging.warning("MQTT not connected, cannot publish")

    def disconnect(self):
        self.client.loop_stop()
        self.client.disconnect()

class HomieMQTT:
    def __init__(self, config, mqtt_client):
        self.config = config
        self.mqtt_client = mqtt_client
        self.base_topic = f"homie/{config.homieclientid}"
        self.node = config.homienodes
        self.temp_topic = f"{self.base_topic}/{self.node}/temperature"
        self.hum_topic = f"{self.base_topic}/{self.node}/humidity"

    def publish_reading(self, temperature, humidity):
        if temperature is not None and humidity is not None:
            self.mqtt_client.publish(self.temp_topic, f"{temperature:.1f}")
            self.mqtt_client.publish(self.hum_topic, f"{humidity:.1f}")

def main():
    class Config:
        dhtgpiopin = 4
        mqttbroker = "localhost"
        mqttport = 1883
        mqttusername = ""
        mqttpassword = ""
        mqttclientid = "rpi-dht22"
        homieclientid = "rpi-dht22"
        homieclientname = "Raspberry Pi DHT22"
        homienodes = "dht22"
        publishtime = 10

    config = Config()
    sensor = DHT22Sensor(config.dhtgpiopin)
    mqtt_client = MQTTClient(config)
    mqtt_client.connect()
    homie = HomieMQTT(config, mqtt_client)

    running = True
    def signal_handler(signum, frame):
        nonlocal running
        running = False
        logging.info(f"Signal {signum} received, shutting down...")
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while running:
            temperature, humidity = sensor.read()
            if temperature is not None and humidity is not None:
                homie.publish_reading(temperature, humidity)
            else:
                logging.warning("Failed to read DHT22 sensor after retries")
            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        sensor.cleanup()
        mqtt_client.disconnect()
        logging.info("Cleanup complete.")

if __name__ == "__main__":
    main()

