import random
import time
import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

HEATER_PIN = 17
READ_INTERVAL = 2.0
ITERATIONS = 5
TEMP_MIN = 10.0
TEMP_MAX = 30.0
HEATER_THRESHOLD = 20.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_temperature():
    return random.uniform(TEMP_MIN, TEMP_MAX)

def control_heater(heater, temperature):
    if temperature < HEATER_THRESHOLD:
        print("Heater ON")
        heater.on()
    else:
        print("Heater OFF")
        heater.off()

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        heater = OutputDevice(HEATER_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO{HEATER_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(ITERATIONS):
            if not _running:
                break
            temperature = read_temperature()
            print(f"Iteration {i + 1}/{ITERATIONS}: Temperature = {temperature:.2f}°C")
            control_heater(heater, temperature)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        try:
            heater.off()
            heater.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

