import time
import signal
import sys
import board
import busio
import adafruit_bme680

LOG_FILE = 'air_quality_log.txt'
READ_INTERVAL = 10

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def log_reading(temperature, humidity, pressure, gas):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp},{temperature:.2f},{humidity:.2f},{pressure:.2f},{gas:.2f}\n"
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c = None
    bme = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        bme = adafruit_bme680.Adafruit_BME680_I2C(i2c, address=0x77)
        print("BME680 initialized at I2C address 0x77. Logging air quality data...")

        while _running:
            try:
                temperature = bme.temperature
                humidity = bme.humidity
                pressure = bme.pressure
                gas = bme.gas

                print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, "
                      f"Pressure: {pressure:.2f} hPa, Gas: {gas:.2f} ohms")

                log_reading(temperature, humidity, pressure, gas)

            except (OSError, ValueError) as e:
                print(f"Sensor read error: {e}", file=sys.stderr)

            for _ in range(READ_INTERVAL):
                if not _running:
                    break
                time.sleep(1)

    except Exception as e:
        print(f"Initialization error: {e}", file=sys.stderr)
    finally:
        if bme is not None:
            try:
                bme.deinit()
            except Exception:
                pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        print("Resources released. Exiting.")

if __name__ == '__main__':
    main()

