import time
import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    I2C_BUS = 1
    I2C_ADDR = 0x38
    MEAS_DELAY = 0.08
    MAX_MEAS_ATTEMPTS = 10
    MEAS_RETRIES = 5
    MIN_INTERVAL = 2.0
    STATUS_REG = 0x71
    MEASURE_REG = 0xAC
    MEASURE_CMD = [0x33, 0x00]
    CRC_POLY = 0x31

    def __init__(self, bus_num=I2C_BUS, addr=I2C_ADDR):
        self.addr = addr
        self.bus_num = bus_num
        self.bus = None
        self.last_temp = None
        self.last_hum = None
        self.last_time = 0.0
        self._running = True

    def __enter__(self):
        if not self.begin():
            raise RuntimeError('DHT20 init failed')
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None

    def _signal_handler(self, signum, frame):
        logger.info('Signal %s received, shutting down', signum)
        self._running = False

    def begin(self):
        try:
            self.bus = SMBus(self.bus_num)
        except OSError as e:
            logger.error('Cannot open I2C bus %d: %s', self.bus_num, e)
            self.bus = None
            return False
        time.sleep(0.5)
        if not self._check_status():
            logger.error('DHT20 not responding at 0x%02X', self.addr)
            self.close()
            return False
        return True

    def _check_status(self):
        try:
            status = self.bus.read_byte_data(self.addr, self.STATUS_REG)
        except OSError as e:
            logger.error('I2C read status failed: %s', e)
            return False
        return (status & 0x18) == 0x18

    def _read_raw(self):
        try:
            data = self.bus.read_i2c_block_data(self.addr, self.STATUS_REG, 7)
        except OSError as e:
            logger.error('I2C read block failed: %s', e)
            return None
        if len(data) != 7:
            logger.error('Unexpected block length: %d', len(data))
            return None
        if self._crc8(data[:6]) != data[6]:
            logger.warning('CRC mismatch (got 0x%02X, expected 0x%02X)', data[6], self._crc8(data[:6]))
            return None
        return data

    def _crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.CRC_POLY) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _wait_idle(self):
        for _ in range(self.MAX_MEAS_ATTEMPTS):
            try:
                status = self.bus.read_byte_data(self.addr, self.STATUS_REG)
            except OSError as e:
                logger.error('I2C read status failed: %s', e)
                return False
            if (status & 0x18) == 0x18:
                return True
            time.sleep(self.MEAS_DELAY)
        logger.warning('DHT20 measurement timeout')
        return False

    def get_temperature_and_humidity(self):
        now = time.time()
        if now - self.last_time < self.MIN_INTERVAL:
            logger.debug('Measurement within interval, returning cached values')
            return self.last_temp, self.last_hum
        for attempt in range(self.MEAS_RETRIES):
            if not self._running:
                return None, None, True
            try:
                self.bus.write_i2c_block_data(self.addr, self.MEASURE_REG, self.MEASURE_CMD)
            except OSError as e:
                logger.error('I2C write measurement command failed: %s', e)
                time.sleep(0.01)
                continue
            if not self._wait_idle():
                logger.warning('Measurement idle check failed on attempt %d', attempt + 1)
                time.sleep(0.01)
                continue
            data = self._read_raw()
            if data is None:
                logger.warning('Raw data read failed on attempt %d', attempt + 1)
                time.sleep(0.01)
                continue
            hum_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
            temp_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
            humidity = hum_raw / (1 << 20) * 100.0
            temperature = temp_raw / (1 << 19) * 200.0 - 50.0
            self.last_temp = temperature
            self.last_hum = humidity
            self.last_time = now
            return temperature, humidity, False
        logger.error('All measurement attempts failed')
        return None, None, True


def main():
    signal.signal(signal.SIGINT, lambda s, f: None)
    signal.signal(signal.SIGTERM, lambda s, f: None)
    sensor = DHT20()
    try:
        if not sensor.begin():
            print('DHT20 initialization failed. Check wiring and I2C address.', file=sys.stderr)
            sys.exit(0)
        while sensor._running:
            temp, hum, err = sensor.get_temperature_and_humidity()
            if err:
                print('Error reading DHT20 sensor data.')
            else:
                print(f'Temperature: {temp:.2f} C, Humidity: {hum:.2f} %')
            time.sleep(1)
    except KeyboardInterrupt:
        print('\nExiting program.')
    finally:
        sensor.close()


if __name__ == '__main__':
    main()

