import time
import logging
import signal
import sys
import board
import adafruit_dht

# Configure logging to file and console
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler("wildlife_monitoring.log"),
        logging.StreamHandler(sys.stdout)
    ]
)

# Constants
DHT22_PINS = [board.D4, board.D17]  # GPIO4 and GPIO17
TEMPERATURE_THRESHOLD_HIGH = 35.0
TEMPERATURE_THRESHOLD_LOW = 5.0
HUMIDITY_THRESHOLD_HIGH = 90.0
READ_INTERVAL_SECONDS = 60
MAX_RETRIES = 3
RETRY_DELAY_SECONDS = 2

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False
    logging.info("Shutdown signal received. Exiting gracefully...")

def read_dht22(dht_device, pin_number):
    """
    Reads temperature and humidity from a DHT22 sensor with retry logic.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                logging.warning(f"Attempt {attempt}/{MAX_RETRIES}: Incomplete data from DHT22 on pin {pin_number}")
        except RuntimeError as e:
            logging.warning(f"Attempt {attempt}/{MAX_RETRIES}: DHT22 read error on pin {pin_number}: {e}")
        except Exception as e:
            logging.error(f"Attempt {attempt}/{MAX_RETRIES}: Unexpected error reading DHT22 on pin {pin_number}: {e}")

        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY_SECONDS)

    logging.error(f"Failed to read DHT22 on pin {pin_number} after {MAX_RETRIES} attempts.")
    return None, None

def check_anomalies(temperature, humidity, pin_number):
    """
    Checks for temperature and humidity anomalies and logs them.
    """
    if temperature is not None:
        if temperature > TEMPERATURE_THRESHOLD_HIGH:
            logging.error(f"Temperature anomaly: {temperature:.1f}°C (High) on pin {pin_number}")
        elif temperature < TEMPERATURE_THRESHOLD_LOW:
            logging.error(f"Temperature anomaly: {temperature:.1f}°C (Low) on pin {pin_number}")
    if humidity is not None:
        if humidity > HUMIDITY_THRESHOLD_HIGH:
            logging.error(f"Humidity anomaly: {humidity:.1f}% (High) on pin {pin_number}")

def main():
    """Main function to initialize sensors and run the monitoring loop."""
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    dht_devices = []
    try:
        for pin in DHT22_PINS:
            try:
                dht = adafruit_dht.DHT22(pin, use_pulseio=False)
                dht_devices.append(dht)
                logging.info(f"Initialized DHT22 on pin {pin}")
            except Exception as e:
                logging.error(f"Failed to initialize DHT22 on pin {pin}: {e}")
                dht_devices.append(None)
    except Exception as e:
        logging.error(f"Error initializing DHT22 sensors: {e}")
        return

    try:
        while running:
            for i, dht in enumerate(dht_devices):
                if dht is None:
                    logging.warning(f"Skipping pin {DHT22_PINS[i]} due to initialization failure.")
                    continue

                temperature, humidity = read_dht22(dht, DHT22_PINS[i])

                if temperature is not None and humidity is not None:
                    logging.info(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}% on pin {DHT22_PINS[i]}")
                else:
                    logging.warning(f"Failed to read data from DHT22 on pin {DHT22_PINS[i]}")

                check_anomalies(temperature, humidity, DHT22_PINS[i])

            # Wait for the next reading interval, checking for shutdown
            for _ in range(READ_INTERVAL_SECONDS):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Clean up resources
        for dht in dht_devices:
            if dht is not None:
                try:
                    dht.exit()
                except Exception:
                    pass
        logging.info("GPIO cleanup complete. Exiting.")

if __name__ == "__main__":
    main()

