DHT_PIN = board.D4
LED1_RED = 17
LED1_GREEN = 22
LED1_BLUE = 27
LED2_RED = 5
LED2_GREEN = 6
LED2_BLUE = 13
LED3_RED = 19
LED3_GREEN = 26
LED3_BLUE = 16
CLOUD_URL = "http://example.com/api/data"
PWM_FREQUENCY = 1000
SAFE_TEMP_MIN = 18
SAFE_TEMP_MAX = 28
SAFE_HUMIDITY_MIN = 30
SAFE_HUMIDITY_MAX = 80
DHT_RETRIES = 3
DHT_RETRY_DELAY = 2
READ_INTERVAL = 5
CLOUD_INTERVAL = 60

# Logging setup
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
    handlers=[
        logging.FileHandler("greenhouse.log"),
        logging.StreamHandler()
    ]
)

# Global state
last_temperature = None
last_humidity = None
last_alert = None
dht_device = None
pwm_channels = []

def setup_gpio():
    """Initialize GPIO pins and PWM channels."""
    global pwm_channels
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for led in [(LED1_RED, LED1_GREEN, LED1_BLUE),
                (LED2_RED, LED2_GREEN, LED2_BLUE),
                (LED3_RED, LED3_GREEN, LED3_BLUE)]:
        for pin in led:
            GPIO.setup(pin, GPIO.OUT)
            GPIO.output(pin, GPIO.LOW)
    pwm_channels = [
        [GPIO.PWM(LED1_RED, PWM_FREQUENCY), GPIO.PWM(LED1_GREEN, PWM_FREQUENCY), GPIO.PWM(LED1_BLUE, PWM_FREQUENCY)],
        [GPIO.PWM(LED2_RED, PWM_FREQUENCY), GPIO.PWM(LED2_GREEN, PWM_FREQUENCY), GPIO.PWM(LED2_BLUE, PWM_FREQUENCY)],
        [GPIO.PWM(LED3_RED, PWM_FREQUENCY), GPIO.PWM(LED3_GREEN, PWM_FREQUENCY), GPIO.PWM(LED3_BLUE, PWM_FREQUENCY)]
    ]
    for led in pwm_channels:
        for pwm in led:
            pwm.start(0)

def set_led_color(led_index, red, green, blue):
    """Set RGB color for a specific LED (0, 1, or 2)."""
    if 0 <= led_index < len(pwm_channels):
        pwm_channels[led_index][0].ChangeDutyCycle(red)
        pwm_channels[led_index][1].ChangeDutyCycle(green)
        pwm_channels[led_index][2].ChangeDutyCycle(blue)

