import time
import signal
import sys
import json
import requests
import adafruit_dht
from board import D4

# Configuration
SERVER_URL = 'http://127.0.0.1:5000/data'
READ_INTERVAL = 5  # seconds
DHT_PIN = D4  # GPIO4 (BCM) = physical pin 7

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_sensor(sensor):
    """Read temperature and humidity from the DHT11 sensor.
    Returns (temperature, humidity) or (None, None) on failure."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            print("Warning: DHT11 returned None for temperature or humidity.")
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT sensors commonly throw RuntimeError on missed reads
        print(f"Sensor read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected sensor error: {e}")
        return None, None

def send_data(temperature, humidity):
    """Send temperature and humidity data to the server via HTTP POST."""
    data = {'temperature': temperature, 'humidity': humidity}
    try:
        response = requests.post(SERVER_URL, json=data, timeout=10)
        print(f"Data sent. Status code: {response.status_code}")
    except requests.exceptions.ConnectionError as e:
        print(f"Connection error: {e}")
    except requests.exceptions.Timeout:
        print("Request timed out.")
    except requests.exceptions.RequestException as e:
        print(f"Request error: {e}")

def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize the DHT11 sensor on GPIO4
    try:
        sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 sensor: {e}")
        sys.exit(1)

    print("DHT11 sensor initialized. Starting data collection...")

    try:
        while _running:
            temperature, humidity = read_sensor(sensor)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                send_data(temperature, humidity)
            else:
                print("Skipping data transmission due to invalid sensor reading.")

            # Sleep in small increments to allow prompt signal handling
            for _ in range(READ_INTERVAL):
                if not _running:
                    break
                time.sleep(1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        # Clean up sensor resources
        try:
            sensor.exit()
        except Exception:
            pass
        print("Program terminated. Resources released.")

if __name__ == "__main__":
    main()

