import time
import board
import busio
import adafruit_ahtx0

# AHT20 I2C address
AHT20_ADDR = 0x38

# Retry interval (seconds)
RETRY_INTERVAL = 5

# Sensor validation ranges
TEMP_MIN, TEMP_MAX = -40.0, 85.0
HUM_MIN, HUM_MAX = 0.0, 100.0


def init_sensor():
    """Initialize I2C bus and AHT20 sensor. Returns sensor object or None."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

    try:
        while not i2c.try_lock():
            pass
        try:
            devices = i2c.scan()
        finally:
            i2c.unlock()

        if AHT20_ADDR not in devices:
            print(f"AHT20 not found at 0x{AHT20_ADDR:02X}. Detected: {[hex(d) for d in devices]}")
            i2c.deinit()
            return None

        sensor = adafruit_ahtx0.AHTx0(i2c, address=AHT20_ADDR)
        return sensor
    except Exception as e:
        print(f"Error initializing AHT20 sensor: {e}")
        try:
            i2c.deinit()
        except Exception:
            pass
        return None


def read_sensor(sensor):
    """Read temperature and humidity from the AHT20 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.relative_humidity
        return temperature, humidity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None


def validate_reading(temperature, humidity):
    """Validate sensor readings against known ranges."""
    if temperature is None or humidity is None:
        return False
    if not (TEMP_MIN <= temperature <= TEMP_MAX):
        print(f"Invalid temperature reading: {temperature}")
        return False
    if not (HUM_MIN <= humidity <= HUM_MAX):
        print(f"Invalid humidity reading: {humidity}")
        return False
    return True


def main():
    """Main loop for reading and printing sensor data."""
    sensor = init_sensor()
    if sensor is None:
        print("Failed to initialize sensor. Exiting.")
        return

    try:
        while True:
            temperature, humidity = read_sensor(sensor)

            if validate_reading(temperature, humidity):
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                print(f"{timestamp} Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")

            time.sleep(RETRY_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        try:
            sensor.deinit()
        except Exception:
            pass
        try:
            i2c.deinit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

