import logging

from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("fanctl")

FAN_PIN = 14
PWM_FREQ = 100.0
INTERVAL = 5.0

TEMP_THRESHOLDS = [
    (70.0, 100.0),
    (60.0, 85.0),
    (50.0, 70.0),
    (40.0, 50.0),
    (32.0, 25.0),
    (25.0, 15.0),
]

fan = None
running = True


def get_cpu_temp():
    """Return CPU temperature in °C, or None on error."""
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        out = result.stdout.strip()
        # Expected format: temp=42.8'C
        if not out.startswith("temp="):
            log.error("Unexpected vcgencmd output: %r", out)
            return None
        return float(out.split("=", 1)[1].split("'", 1)[0])
    except FileNotFoundError:
        log.error("vcgencmd not found; is this running on a Raspberry Pi?")
    except subprocess.TimeoutExpired:
        log.error("vcgencmd timed out")
    except subprocess.CalledProcessError as exc:
        log.error("vcgencmd failed (rc=%s): %s", exc.returncode, exc.stderr)
    except (IndexError, ValueError) as exc:
        log.error("Failed to parse temperature: %s", exc)
    return None


