import time
import signal
import sys
import struct
from smbus2 import SMBus

I2C_BUS = 1
I2C_ADDR = 0x38
READ_INTERVAL = 5
MEASURE_DELAY = 0.08
INIT_DELAY = 0.01
RESET_DELAY = 0.02

running = True

def signal_handler(sig, frame):
    global running
    running = False

def crc8(data, init=0xFF, poly=0x31):
    crc = init
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ poly) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def init_sensor(bus):
    try:
        bus.write_byte(I2C_ADDR, 0xBA)
        time.sleep(RESET_DELAY)
        status = bus.read_byte(I2C_ADDR)
        if not (status & 0x08):
            bus.write_byte(I2C_ADDR, 0xBE)
            bus.write_byte(I2C_ADDR, 0x08)
            bus.write_byte(I2C_ADDR, 0x00)
            time.sleep(INIT_DELAY)
    except IOError as e:
        print(f"Sensor init error: {e}")
        raise

def read_sensor(bus):
    try:
        bus.write_i2c_block_data(I2C_ADDR, 0xAC, [0x33, 0x00])
        time.sleep(MEASURE_DELAY)
        data = bus.read_i2c_block_data(I2C_ADDR, 0x71, 7)
        if data[0] & 0x80:
            print("Sensor busy, skipping")
            return None
        if crc8(data[:6]) != data[6]:
            print("CRC error, skipping")
            return None
        raw_temp = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        raw_humid = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
        temp_c = (raw_temp / 0x100000) * 200.0 - 50.0
        temp_f = temp_c * 9.0 / 5.0 + 32.0
        humid = (raw_humid / 0x100000) * 100.0
        return temp_c, temp_f, humid
    except IOError as e:
        print(f"Sensor read error: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    try:
        bus = SMBus(I2C_BUS)
    except IOError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)
    try:
        init_sensor(bus)
        while running:
            result = read_sensor(bus)
            if result is not None:
                temp_c, temp_f, humid = result
                ts = time.strftime("%Y-%m-%d %H:%M:%S")
                print(f"{ts} | Temp: {temp_c:.2f}C / {temp_f:.2f}F | Humidity: {humid:.2f}%")
            else:
                print("Skipping reading")
            for _ in range(READ_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    except IOError as e:
        print(f"Fatal I2C error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

