import serial
import serial.tools.list_ports
import time
import signal
import sys
import RPi.GPIO as GPIO
from datetime import datetime

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
LOG_FILE = '/home/pi/sensor_log.txt'
TEMP_THRESHOLD = 28.0
HUMIDITY_THRESHOLD = 65.0
ALERT_PIN = 17
ALERT_DURATION = 5.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _log(message):
    ts = datetime.now().isoformat(timespec='seconds')
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f"{ts} - {message}\n")
    except OSError as e:
        print(f"{ts} - LOG ERROR: {e}", file=sys.stderr)

def _cleanup(ser):
    try:
        GPIO.output(ALERT_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()
    if ser is not None and ser.is_open:
        try:
            ser.close()
        except Exception:
            pass

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        try:
            ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
            _log(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
        except serial.SerialException as e:
            _log(f"ERROR: cannot open {SERIAL_PORT}: {e}")
            sys.exit(1)

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(ALERT_PIN, GPIO.OUT, initial=GPIO.LOW)
        _log(f"GPIO{ALERT_PIN} configured as output (LOW).")

        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                _log(f"ERROR: serial read failed: {e}")
                time.sleep(1)
                continue

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                parts = line.split(',')
                if len(parts) != 2:
                    raise ValueError(f"expected 2 fields, got {len(parts)}")
                temperature = float(parts[0])
                humidity = float(parts[1])
            except (ValueError, IndexError) as e:
                _log(f"WARNING: malformed data '{line}': {e}")
                continue

            _log(f"Temperature: {temperature:.2f}C, Humidity: {humidity:.2f}%")

            if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
                _log("ALERT: threshold exceeded!")
                try:
                    GPIO.output(ALERT_PIN, GPIO.HIGH)
                    time.sleep(ALERT_DURATION)
                except Exception as e:
                    _log(f"ERROR: failed to drive GPIO{ALERT_PIN}: {e}")
                finally:
                    try:
                        GPIO.output(ALERT_PIN, GPIO.LOW)
                    except Exception:
                        pass

    except Exception as e:
        _log(f"ERROR: {e}")
    finally:
        _cleanup(ser)
        _log("Program terminated.")

if __name__ == '__main__':
    main()

