import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
SLEEP_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_sensor_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        parts = line.split(',')
        if len(parts) != 2:
            return None
        temperature_str, humidity_str = parts
        temperature = float(temperature_str)
        humidity = float(humidity_str)
        return temperature, humidity
    except ValueError:
        return None
    except serial.SerialException:
        return None

def check_thresholds(temperature, humidity):
    if temperature > TEMPERATURE_THRESHOLD:
        print(f'Alert: Temperature {temperature:.1f}°C exceeds threshold {TEMPERATURE_THRESHOLD}°C')
    if humidity > HUMIDITY_THRESHOLD:
        print(f'Alert: Humidity {humidity:.1f}% exceeds threshold {HUMIDITY_THRESHOLD}%')

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_port = None
    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')

        while _running:
            data = read_sensor_data(serial_port)
            if data is not None:
                temperature, humidity = data
                print(f'Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%')
                check_thresholds(temperature, humidity)
            time.sleep(SLEEP_INTERVAL)

    except serial.SerialException as e:
        print(f'Serial error: {e}', file=sys.stderr)
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
    finally:
        if serial_port is not None and serial_port.is_open:
            serial_port.close()
            print('Serial port closed.')

if __name__ == '__main__':
    main()

