import signal
import sys
import time

from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# Configuration
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0  # seconds
SENSOR_NAMES = ["sensor 1", "sensor 2", "sensor 3"]

# Global list to track open devices for cleanup
_devices = []
_running = True


def _handle_signal(signum, frame):
    """Signal handler for graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _cleanup():
    """Close every open gpiozero device to release GPIO resources."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass
    _devices.clear()


def main():
    global _devices

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    print(f"Monitoring GPIO pins {SENSOR_PINS} (active-high pull-up) every {POLL_INTERVAL}s...")

    # Initialize each sensor pin with an active-high pull-up resistor.
    # pull_up=True means the pin reads HIGH when idle (no external pull-down).
    for pin in SENSOR_PINS:
        try:
            sensor = DigitalInputDevice(pin, pull_up=True)
            _devices.append(sensor)
        except (GPIOZeroError, GPIODeviceError) as exc:
            print(f"Error: Failed to initialize GPIO pin {pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)
        except Exception as exc:
            print(f"Unexpected error initializing GPIO pin {pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    try:
        while _running:
            for idx, sensor in enumerate(_devices):
                try:
                    if sensor.is_active:
                        print(f"Response for {SENSOR_NAMES[idx]}")
                except GPIODeviceError as exc:
                    print(f"Warning: Failed to read GPIO pin {SENSOR_PINS[idx]}: {exc}", file=sys.stderr)
                except Exception as exc:
                    print(f"Warning: Unexpected error reading GPIO pin {SENSOR_PINS[idx]}: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"Unexpected runtime error: {exc}", file=sys.stderr)

    finally:
        _cleanup()
        print("GPIO cleanup completed. Exiting.")


if __name__ == "__main__":
    main()

