import RPi.GPIO as GPIO
import time
import threading
import signal
import sys

# Assuming DOG is a predefined class or module
class DOG:
    @staticmethod
    def send(data_string):
        # Placeholder implementation for data transmission
        print(f"Sending: {data_string}")

    @staticmethod
    def receive():
        # Placeholder implementation for data reception
        return "Received data"

# Global variables
server_running = False
log_file = None
receive_thread = None
receive_lock = threading.Lock()

def cleanup_gpio(signum=None, frame=None):
    """Clean up GPIO resources and exit."""
    global server_running, log_file, receive_thread
    if server_running:
        print("\nStopping server and cleaning up GPIO...")
        server_running = False
        if receive_thread and receive_thread.is_alive():
            receive_thread.join(timeout=1.0)
        if log_file and not log_file.closed:
            log_file.close()
    GPIO.cleanup()
    if signum is not None:
        sys.exit(0)

def receive_data():
    """Continuously receives data and writes it to the log file."""
    global server_running, log_file
    while server_running:
        try:
            data = DOG.receive()
            with receive_lock:
                if log_file and not log_file.closed:
                    log_file.write(data + "\n")
                    log_file.flush()
        except Exception as e:
            print(f"Error receiving data: {e}")
        time.sleep(0.1)

def start_server(filename):
    """Starts the server and the receive thread."""
    global server_running, log_file, receive_thread
    if server_running:
        print("Server is already running.")
        return

    try:
        log_file = open(filename, "a")
    except IOError as e:
        print(f"Error opening log file: {e}")
        return

    server_running = True
    receive_thread = threading.Thread(target=receive_data, daemon=True)
    receive_thread.start()
    print(f"Server started. Logging to {filename}")

def stop_server():
    """Stops the server and cleans up GPIO."""
    global server_running, log_file, receive_thread
    if not server_running:
        print("Server is not running.")
        return

    server_running = False
    if receive_thread and receive_thread.is_alive():
        receive_thread.join(timeout=1.0)
    if log_file and not log_file.closed:
        log_file.close()
    GPIO.cleanup()
    print("Server stopped and GPIO cleaned up.")

def help_command(command=None):
    """Displays help information for commands."""
    help_text = {
        "help": "Displays this help information.\nUsage: help [command]",
        "start": "Starts the server and logs data to a file.\nUsage: start <filename>",
        "stop": "Stops the server and cleans up GPIO.",
        "display": "Displays the contents of the log file.",
        "send": "Sends data using the DOG protocol.\nUsage: send <data>",
        "write": "Writes data directly to the log file.\nUsage: write <data>",
        "exit": "Exits the server.",
    }
    if command:
        print(help_text.get(command, "No help found for this command."))
    else:
        print("Available commands:")
        for cmd, desc in help_text.items():
            print(f"  {cmd}: {desc}")

def display_log():
    """Displays the contents of the log file."""
    global log_file
    if not server_running:
        print("Server is not running. Please start the server first.")
        return

    try:
        with open(log_file.name, "r") as f:
            print(f.read())
    except IOError as e:
        print(f"Error reading log file: {e}")

def send_data(data_string):
    """Sends data using the DOG protocol."""
    if not server_running:
        print("Server is not running. Please start the server first.")
        return
    try:
        DOG.send(data_string)
    except Exception as e:
        print(f"Error sending data: {e}")

def write_data(data_string):
    """Writes data directly to the log file."""
    global log_file
    if not server_running:
        print("Server is not running. Please start the server first.")
        return
    try:
        with receive_lock:
            if log_file and not log_file.closed:
                log_file.write(data_string + "\n")
                log_file.flush()
    except IOError as e:
        print(f"Error writing to log file: {e}")

def exit_server():
    """Exits the server."""
    stop_server()
    sys.exit(0)

def process_command(command):
    """Processes user commands."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()
    args = parts[1:]

    if cmd == "help":
        if len(args) == 1:
            help_command(args[0])
        else:
            help_command()
    elif cmd == "start":
        if len(args) == 1:
            start_server(args[0])
        else:
            print("Usage: start <filename>")
    elif cmd == "stop":
        stop_server()
    elif cmd == "display":
        display_log()
    elif cmd == "send":
        if len(args) == 1:
            send_data(args[0])
        else:
            print("Usage: send <data>")
    elif cmd == "write":
        if len(args) == 1:
            write_data(args[0])
        else:
            print("Usage: write <data>")
    elif cmd == "exit":
        exit_server()
    else:
        print(f"Unknown command: {cmd}. Try 'help'.")

def main():
    """Main function to run the server."""
    global server_running
    signal.signal(signal.SIGINT, cleanup_gpio)
    signal.signal(signal.SIGTERM, cleanup_gpio)

    try:
        GPIO.setmode(GPIO.BCM)
        print("Server ready. Type 'help' for commands.")
        while True:
            try:
                command = input("Enter command: ")
                process_command(command)
            except EOFError:
                print("\nEOF received. Exiting.")
                break
            except Exception as e:
                print(f"An error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

