import signal
import sys
from flask import Flask, render_template_string

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

app = Flask(__name__)

LED_PIN = 17
led = None

INDEX_HTML = """
<!DOCTYPE html>
<html>
<head><title>LED Control</title></head>
<body>
  <h1>LED Control</h1>
  {% if status %}
  <p>{{ status }}</p>
  {% endif %}
  <a href="/light_on">Turn ON</a> | <a href="/light_off">Turn OFF</a>
</body>
</html>
"""

ERROR_HTML = """
<!DOCTYPE html>
<html>
<head><title>Error</title></head>
<body>
  <h1>Error</h1>
  <p>{{ message }}</p>
  <a href="/">Back to Home</a>
</body>
</html>
"""

try:
    led = LED(LED_PIN)
except (BadPinFactory, GPIOZeroError) as e:
    print(f"Error: Could not initialize LED on GPIO {LED_PIN}: {e}", file=sys.stderr)
    sys.exit(1)
except Exception as e:
    print(f"Unexpected error initializing GPIO: {e}", file=sys.stderr)
    sys.exit(1)

@app.route('/')
def index():
    return render_template_string(INDEX_HTML, status=None)

@app.route('/light_on')
def light_on():
    try:
        led.on()
        return render_template_string(INDEX_HTML, status="LED is ON")
    except Exception as e:
        return render_template_string(ERROR_HTML, message=str(e)), 500

@app.route('/light_off')
def light_off():
    try:
        led.off()
        return render_template_string(INDEX_HTML, status="LED is OFF")
    except Exception as e:
        return render_template_string(ERROR_HTML, message=str(e)), 500

def cleanup(signum=None, frame=None):
    global led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        sys.exit(0)

signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=8080, debug=False)
    finally:
        cleanup()

