        """Release GPIO resources and close ZMQ sockets."""
        if self._shutting_down:
            return
        self._shutting_down = True

        if self.subscriber:
            try:
                self.subscriber.close(linger=0)
            except Exception as e:
                logger.error(f"Error closing subscriber socket: {e}")
            finally:
                self.subscriber = None

        if self.error_output:
            try:
                if self.pwm and isinstance(self.error_output, PWMOutputDevice):
                    self.error_output.close()
                else:
                    self.error_output.close()
            except Exception as e:
                logger.error(f"Error closing GPIO device: {e}")
            finally:
                self.error_output = None

        self._gpio_initialized = False
        logger.info("Cleanup complete.")

