# fingerprint_authentication_rp5.py
# Raspberry Pi 5 fingerprint authentication using Adafruit Fingerprint sensor (I2C 0x26)

import time
import board
import busio
import adafruit_fingerprint

# Constants
I2C_ADDRESS = 0x26
DELAY_SECONDS = 1


def initialize_fingerprint_sensor():
    """Initialize the I2C bus and fingerprint sensor with error handling."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus, addr=I2C_ADDRESS)
        return fingerprint_sensor
    except ValueError as e:
        print(f"Error: I2C bus locked or no device at address 0x{I2C_ADDRESS:02X}: {e}")
        return None
    except RuntimeError as e:
        print(f"Error: Fingerprint sensor initialization failed (check wiring/address 0x{I2C_ADDRESS:02X}): {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing fingerprint sensor: {e}")
        return None


def authenticate_fingerprint(fingerprint_sensor):
    """Acquire a fingerprint image, convert to template, and search the database."""
    try:
        if fingerprint_sensor.get_image() == adafruit_fingerprint.OK:
            if fingerprint_sensor.image_2_tz(1) == adafruit_fingerprint.OK:
                if fingerprint_sensor.finger_search() == adafruit_fingerprint.OK:
                    confidence = fingerprint_sensor.finger_id
                    if confidence > 0:
                        print(f"Access Granted (ID: {confidence}, Confidence: {fingerprint_sensor.confidence})")
                    else:
                        print("Access Denied: No fingerprint found in database.")
                else:
                    print("Access Denied: Fingerprint search failed.")
            else:
                print("Access Denied: Template conversion failed.")
        else:
            print("Access Denied: Could not capture fingerprint image.")
    except OSError as e:
        print(f"I2C communication error during authentication: {e}")
    except Exception as e:
        print(f"Unexpected error during authentication: {e}")


def main():
    """Main loop for continuous fingerprint authentication."""
    fingerprint_sensor = initialize_fingerprint_sensor()
    if fingerprint_sensor is None:
        print("Failed to initialize fingerprint sensor. Exiting.")
        return

    try:
        while True:
            authenticate_fingerprint(fingerprint_sensor)
            time.sleep(DELAY_SECONDS)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        print("Resources released. Goodbye!")


if __name__ == "__main__":
    main()

