import RPi.GPIO as GPIO
import time
import logging
import signal
import threading

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21
START_BYTE = [1, 0, 1, 1, 1, 1, 1, 1]
END_BYTE = [1, 1, 1, 1, 1, 1, 1, 1]
BIT_DELAY = 0.0001

_running = threading.Event()
_running.set()

def _signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, shutting down...")
    _running.clear()

def _setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in (DATA_OUT_PIN, TIMER_OUT_PIN):
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
    for pin in (DATA_IN_PIN, TIMER_IN_PIN):
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

def _cleanup_gpio():
    for pin in (DATA_OUT_PIN, TIMER_OUT_PIN, DATA_IN_PIN, TIMER_IN_PIN):
        try:
            GPIO.output(pin, GPIO.LOW)
        except Exception:
            pass
    GPIO.cleanup()

def char_to_list(char: str) -> list:
    if not isinstance(char, str) or len(char) != 1:
        raise ValueError("Input must be a single character.")
    binary = bin(ord(char))[2:].zfill(8)
    return [int(bit) for bit in binary]

def list_to_char(bit_list: list) -> str:
    if not isinstance(bit_list, list) or len(bit_list) != 8:
        raise ValueError("Input must be a list of 8 bits.")
    binary_str = ''.join(map(str, bit_list))
    return chr(int(binary_str, 2))

def _send_bit(bit: int):
    GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
    GPIO.output(DATA_OUT_PIN, GPIO.HIGH if bit else GPIO.LOW)
    time.sleep(BIT_DELAY)
    GPIO.output(TIMER_OUT_PIN, GPIO.HIGH)
    time.sleep(BIT_DELAY)
    GPIO.output(TIMER_OUT_PIN, GPIO.LOW)

def send_data(data: str):
    if not _running.is_set():
        logging.error("Shutdown requested; aborting send.")
        return
    try:
        _setup_gpio()
        for bit in START_BYTE:
            _send_bit(bit)
        for char in data:
            for bit in char_to_list(char):
                _send_bit(bit)
        for bit in END_BYTE:
            _send_bit(bit)
        logging.info(f"Sent: {data}")
    except Exception as e:
        logging.error(f"Error sending data: {e}")
    finally:
        _cleanup_gpio()

def _on_timer_rising(channel):
    global received_data, current_byte
    if not _running.is_set():
        return
    current_byte.append(GPIO.input(DATA_IN_PIN))
    if len(current_byte) == 8:
        if current_byte == START_BYTE:
            received_data = ""
            current_byte = []
        elif current_byte == END_BYTE:
            if received_data:
                logging.info(f"Received: {received_data}")
            else:
                logging.warning("Received empty payload.")
            received_data = ""
            current_byte = []
        else:
            if received_data:
                received_data += list_to_char(current_byte)
            else:
                logging.warning("Received data before START_BYTE.")
            current_byte = []

def receive_data(timeout: float = 5.0) -> str:
    global received_data, current_byte
    received_data = ""
    current_byte = []
    try:
        _setup_gpio()
        GPIO.add_event_detect(TIMER_IN_PIN, GPIO.RISING, callback=_on_timer_rising)
        logging.info("Waiting for data...")
        if not _running.wait(timeout):
            logging.warning("Timeout waiting for data.")
            return ""
        GPIO.remove_event_detect(TIMER_IN_PIN)
        if received_data:
            logging.info(f"Received: {received_data}")
        else:
            logging.warning("No data received within timeout.")
        return received_data
    except Exception as e:
        logging.error(f"Error receiving data: {e}")
        return ""
    finally:
        _cleanup_gpio()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    send_data("Hello")
    receive_data(timeout=10.0)

