import sys
import signal
from gpiozero import PWMOutputDevice

FAN_PIN = 12
PWM_FREQ = 25000

fan = None
running = True

def cleanup(signum=None, frame=None):
    global fan, running
    running = False
    if fan is not None:
        try:
            fan.value = 0
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    global fan
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        print(f"Warning: could not initialize PWM on GPIO{FAN_PIN} ({e}). "
              "Running in software PWM mode or environment may not support hardware PWM.")
        try:
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0, active_high=True, initial_value=0)
        except Exception as e2:
            print(f"Error: could not initialize PWM at all ({e2}). Exiting.")
            sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    print("Fan control ready. Enter a speed 0-100 (Ctrl+C or 'q' to quit).")

    while running:
        try:
            raw = input("Fan Speed (0-100): ").strip()
            if raw.lower() == 'q':
                break
            speed = float(raw)
            if 0 <= speed <= 100:
                fan.value = speed / 100.0
            else:
                print("Invalid speed. Please enter a value between 0 and 100.")
        except ValueError:
            print("Invalid input. Please enter a number.")
        except EOFError:
            break

    cleanup()

if __name__ == "__main__":
    main()

