#!/usr/bin/env python3
"""
LED Blink Program for Raspberry Pi 4

Blinks an LED connected to GPIO17 (BCM) with a 0.5-second on/off cycle.
Uses gpiozero for modern, robust GPIO control.
"""

import time
import sys

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)


LED_PIN = 17
BLINK_INTERVAL = 0.5  # seconds


def main():
    """Main blink loop with robust error handling and cleanup."""
    led = None
    try:
        # Initialize the LED on GPIO17
        led = LED(LED_PIN)
        print(f"LED blink started on GPIO{LED_PIN} with {BLINK_INTERVAL}s interval. Press Ctrl+C to stop.")

        while True:
            led.on()
            time.sleep(BLINK_INTERVAL)
            led.off()
            time.sleep(BLINK_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except PermissionError as e:
        print(f"Permission error: {e}. Try running with sudo or ensure the user is in the gpio group.", file=sys.stderr)
    except RuntimeError as e:
        print(f"Runtime error during GPIO initialization: {e}", file=sys.stderr)
    except GPIOZeroError as e:
        print(f"GPIOZero error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        # Ensure the LED is off and resources are released on every exit path
        if led is not None:
            try:
                led.off()
                led.close()
            except DeviceClosed:
                pass
            except Exception:
                pass
        print("LED turned off and GPIO resources released.")


if __name__ == "__main__":
    main()

