#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter.

Touchpads A (GPIO5) = bit 4, B (GPIO6) = bit 2, C (GPIO12) = bit 1.
Red LED (GPIO7), green LED (GPIO8), blue LED (GPIO12).
HT16K33 14-seg display at I2C 0x70.
APA102 LED strip on GPIO10 (data) / GPIO11 (clock).
Piezo buzzer on GPIO13.

Requires: gpiozero, adafruit-blinka, adafruit-circuitpython-ht16k33,
          adafruit-circuitpython-dotstar (or adafruit-circuitpython-apa102).
"""

import signal
import sys
import time

import board
import busio
from gpiozero import Button, LED, Buzzer
from adafruit_ht16k33.segments import Seg14x4
from adafruit_dotstar import DotStar

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
TOUCH_PINS = {"A": 5, "B": 6, "C": 12}
LED_PINS = {"red": 7, "green": 8, "blue": 12}
BUZZER_PIN = 13

I2C_ADDR = 0x70
NUM_PIXELS = 7
MIDI_BASE = 60

# ---------------------------------------------------------------------------
# Globals (initialised in main)
# ---------------------------------------------------------------------------
bit_states = [False, False, False]
red_led = None
green_led = None
blue_led = None
buzzer = None
display = None
strip = None
touch_buttons = {}
running = True

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def decimal_value() -> int:
    """Return the decimal value of the current bit states (0-7)."""
    return sum(2 ** (2 - i) for i, b in enumerate(bit_states) if b)


def update_discrete_leds() -> None:
    """Drive red, green and blue LEDs from bit_states."""
    red_led.value = bit_states[0]
    green_led.value = bit_states[1]
    blue_led.value = bit_states[2]


def update_display(value: int) -> None:
    """Show the decimal value on the HT16K33 14-segment display."""
    if display is None:
        return
    try:
        display.print_hex(value)
    except Exception as exc:
        print(f"Display update error: {exc}", file=sys.stderr)


def update_strip(value: int) -> None:
    """Update the APA102 LED strip based on the current value and bit states."""
    if strip is None:
        return
    try:
        if value == 0:
            strip.fill((0, 0, 0))
        elif value == 7:
            strip.fill((30, 30, 30))
        else:
            r = 30 if bit_states[0] else 0
            g = 30 if bit_states[1] else 0
            b = 30 if bit_states[2] else 0
            strip.fill((r, g, b))
            strip[value] = (r, g, b)
        strip.show()
    except Exception as exc:
        print(f"Strip update error: {exc}", file=sys.stderr)


def play_tone(value: int) -> None:
    """Play a 0.5-second tone at MIDI note MIDI_BASE + value."""
    if buzzer is None:
        return
    try:
        freq = 440.0 * (2.0 ** ((MIDI_BASE + value) / 12.0))
        buzzer.frequency = int(freq)
        buzzer.value = 0.5
        time.sleep(0.5)
        buzzer.value = 0.0
    except Exception as exc:
        print(f"Buzzer tone error: {exc}", file=sys.stderr)


def cleanup() -> None:
    """Turn off all peripherals and release resources."""
    global running
    running = False
    print("\nCleaning up...")
    try:
        if display is not None:
            display.fill(0)
            display.show()
    except Exception:
        pass
    try:
        if strip is not None:
            strip.fill((0, 0, 0))
            strip.show()
    except Exception:
        pass
    try:
        if red_led is not None:
            red_led.off()
    except Exception:
        pass
    try:
        if green_led is not None:
            green_led.off()
    except Exception:
        pass
    try:
        if blue_led is not None:
            blue_led.off()
    except Exception:
        pass
    try:
        if buzzer is not None:
            buzzer.value = 0.0
    except Exception:
        pass
    for btn in touch_buttons.values():
        try:
            btn.close()
        except Exception:
            pass
    print("Cleanup complete.")


def handle_touch(channel: int) -> None:
    """Toggle the bit corresponding to the touched touchpad."""
    for name, pin in TOUCH_PINS.items():
        if pin == channel:
            bit_states[ord(name) - ord("A")] = not bit_states[ord(name) - ord("A")]
            break
    update_discrete_leds()
    value = decimal_value()
    update_display(value)
    update_strip(value)
    play_tone(value)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    global red_led, green_led, blue_led, buzzer, display, strip
    global touch_buttons

    # --- Touchpads ----------------------------------------------------------
    for name, pin in TOUCH_PINS.items():
        try:
            touch_buttons[name] = Button(pin, pull_up=True, bounce_time=0.05)
        except Exception as exc:
            print(f"Failed to init touchpad {name} on GPIO{pin}: {exc}",
                  file=sys.stderr)
            touch_buttons[name] = None

    # --- Discrete LEDs ------------------------------------------------------
    try:
        red_led = LED(LED_PINS["red"])
        green_led = LED(LED_PINS["green"])
        blue_led = LED(LED_PINS["blue"])
    except Exception as exc:
        print(f"Failed to init discrete LEDs: {exc}", file=sys.stderr)

    # --- Buzzer -------------------------------------------------------------
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as exc:
        print(f"Failed to init buzzer: {exc}", file=sys.stderr)

    # --- I2C / Display ------------------------------------------------------
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        display = Seg14x4(i2c, address=I2C_ADDR)
        display.brightness = 0.5
    except Exception as exc:
        print(f"Failed to init HT16K33 display at 0x{I2C_ADDR:02X}: {exc}",
              file=sys.stderr)
        display = None

    # --- APA102 LED strip ---------------------------------------------------
    try:
        strip = DotStar(board.D10, NUM_PIXELS, brightness=0.2,
                        auto_write=False)
        strip.fill((0, 0, 0))
        strip.show()
    except Exception as exc:
        print(f"Failed to init APA102 LED strip: {exc}", file=sys.stderr)
        strip = None

    # --- Signal handlers ----------------------------------------------------
    signal.signal(signal.SIGINT, lambda *_: None)
    signal.signal(signal.SIGTERM, lambda *_: None)

    # --- Touch event loop ---------------------------------------------------
    try:
        while running:
            signal.pause()
    except Exception as exc:
        print(f"Main loop error: {exc}", file=sys.stderr)
    finally:
        cleanup()
    return 0


if __name__ == "__main__":
    sys.exit(main())

