import random
import sys
import time
from gpiozero import Device
from gpiozero.pins.mock import MockFactory

# Use MockFactory to avoid real GPIO hardware on a simulated system
Device.pin_factory = MockFactory()

def simulate_audio_frame():
    """Simulate an audio frame with a random energy level (0-9)."""
    return random.randint(0, 9)

def transcribe_audio(energy_level):
    """Map energy level modulo 3 to a command keyword."""
    command_map = {0: "water", 1: "stop", 2: "status"}
    return command_map.get(energy_level % 3, "unknown")

def map_to_farm_action(command):
    """Map a command keyword to a simulated farm action."""
    action_map = {"water": "open_valve", "stop": "close_valve", "status": "report"}
    return action_map.get(command, "unknown_action")

def save_actions_to_json(actions, filename="voice_actions.json"):
    """Save the list of actions to a JSON file."""
    try:
        with open(filename, "w") as f:
            json.dump(actions, f, indent=4)
        print(f"Actions saved to {filename}")
    except IOError as e:
        print(f"Error saving actions to JSON: {e}", file=sys.stderr)

def main():
    """Main function to simulate voice recognition and save actions."""
    chosen_actions = []
    try:
        for i in range(6):
            energy = simulate_audio_frame()
            command = transcribe_audio(energy)
            action = map_to_farm_action(command)
            chosen_actions.append(action)
            print(f"Frame {i}: energy={energy}, command={command}, action={action}")
            time.sleep(0.1)
    except Exception as e:
        print(f"An error occurred during simulation: {e}", file=sys.stderr)
    finally:
        save_actions_to_json(chosen_actions)

if __name__ == "__main__":
    main()

