import time
import json
import requests
from gpiozero import Button

# Manufacturing quality control: report button presses as inspection results
# Button wired to GPIO 17 with internal pull-up; active-low (pressed = False)
BUTTON_PIN = 17
SERVER_URL = 'http://localhost:8000/quality'
PART_ID = 'PART-204'
POLL_INTERVAL = 2.0
REQUEST_TIMEOUT = 10

def build_report(part_id, passed, defect_count):
    """Return a JSON report describing the inspection outcome."""
    return json.dumps({'part_id': part_id, 'passed': passed, 'defect_count': defect_count})

def submit_report(report_text):
    """POST the JSON report to the quality control server and return the HTTP status code."""
    headers = {'Content-Type': 'application/json'}
    try:
        response = requests.post(SERVER_URL, data=report_text, headers=headers, timeout=REQUEST_TIMEOUT)
        return response.status_code
    except requests.exceptions.Timeout:
        print('Error: Request timed out after {} seconds.'.format(REQUEST_TIMEOUT))
        return None
    except requests.exceptions.ConnectionError as e:
        print('Error: Could not connect to server: {}'.format(e))
        return None
    except requests.exceptions.RequestException as e:
        print('Error: Network error occurred: {}'.format(e))
        return None

def main():
    """Continuously read the button and submit inspection reports."""
    # Button with pull_up=True uses the internal pull-up resistor; active_low=True
    # means the button is pressed when the pin reads False.
    button = Button(BUTTON_PIN, pull_up=True, active_low=True)
    print('Quality control reporting started. Press Ctrl+C to stop.')
    try:
        while True:
            # Button.is_pressed is True when the pin is LOW (button pressed)
            if button.is_pressed:
                report_text = build_report(PART_ID, passed=False, defect_count=1)
                status_code = submit_report(report_text)
                if status_code is not None:
                    print('Report submitted (fail): HTTP {}'.format(status_code))
            else:
                report_text = build_report(PART_ID, passed=True, defect_count=0)
                status_code = submit_report(report_text)
                if status_code is not None:
                    print('Report submitted (pass): HTTP {}'.format(status_code))
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print('\nStopping quality control reporting.')
    finally:
        button.close()
        print('GPIO resources released.')

if __name__ == '__main__':
    main()

