SAMPLE_COUNT = 6            # Number of readings to average
SAMPLE_INTERVAL = 0.3       # Seconds between readings
THRESHOLD = 7.5             # Average amplitude above this triggers maintenance

# Global sensor object for cleanup
sensor = None


def read_vibration_state():
    """Read the digital vibration sensor state.
    Returns True if vibration detected (LOW), False if idle (HIGH).
    """
    try:
        return not sensor.is_active  # SW-420: LOW = vibration, HIGH = idle
    except DeviceClosed:
        print("Error: Sensor device closed unexpectedly.")
        return False
    except GPIOZeroError as e:
        print(f"GPIO error reading sensor: {e}")
        return False


def generate_simulated_amplitude(vibration_detected):
    """Generate a simulated amplitude based on vibration state."""
    if vibration_detected:
        return random.uniform(6.0, 9.0)
    else:
        return random.uniform(3.0, 5.0)


def main():
    """Main loop: read sensor, compute average, check threshold."""
    global sensor
    running_average = 0.0

    try:
        # Initialize the sensor with internal pull-up (active-low)
        sensor = DigitalInputDevice(VIBRATION_PIN, pull_up=True, bounce_time=None)
        print(f"Vibration sensor initialized on GPIO{VIBRATION_PIN} (active-low).")

        for i in range(SAMPLE_COUNT):
            vibration_detected = read_vibration_state()
            amplitude = generate_simulated_amplitude(vibration_detected)
            running_average += amplitude

            print(f"Sample {i+1}: vibration={vibration_detected}, amplitude={amplitude:.2f}")

            time.sleep(SAMPLE_INTERVAL)

        running_average /= SAMPLE_COUNT
        print(f"\nRunning average amplitude: {running_average:.2f}")

        if running_average > THRESHOLD:
            print("Maintenance recommended: wear trend is high")
        else:
            print("Component healthy: no action needed")

    except GPIOZeroError as e:
        print(f"GPIO initialization error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # Clean up: close the sensor device
        if sensor is not None:
            try:
                sensor.close()
                print("Sensor device closed.")
            except Exception as e:
                print(f"Error closing sensor: {e}")


if __name__ == "__main__":
    main()

