import time
import signal
import sys
import board
import busio
import adafruit_tcs34725
from PIL import Image

# Global resources for cleanup
i2c_bus = None
tcs34725_sensor = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global i2c_bus
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        i2c_bus = None

def get_sensor_color_data():
    """Reads color data from the TCS34725 sensor.
    Returns (R, G, B, Clear) or (0, 0, 0, 0) on error."""
    global tcs34725_sensor
    if tcs34725_sensor is None:
        return (0, 0, 0, 0)
    try:
        r, g, b, clear = tcs34725_sensor.color_rgb_bytes
        return (r, g, b, clear)
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path="image.jpg"):
    """Finds the dominant color in an image using Pillow.
    Returns (R, G, B) or (0, 0, 0) on error."""
    try:
        with Image.open(image_path) as img:
            img = img.resize((100, 100))
            colors = img.getcolors(10000)
            if colors:
                dominant_color = max(colors, key=lambda item: item[0])[1]
                return dominant_color
            else:
                return (0, 0, 0)
    except FileNotFoundError:
        print(f"Error: Image file not found at {image_path}")
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}")
        return (0, 0, 0)

def main():
    global i2c_bus, tcs34725_sensor

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize I2C bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Fatal: Failed to initialize I2C bus: {e}")
        sys.exit(1)

    # Initialize TCS34725 sensor
    try:
        tcs34725_sensor = adafruit_tcs34725.TCS34725(i2c_bus, integration_time=adafruit_tcs34725.TCS34725_INTEGRATION_TIME_50MS, gain=adafruit_tcs34725.TCS34725_GAIN_4X)
    except Exception as e:
        print(f"Fatal: TCS34725 sensor not found or initialization failed: {e}")
        cleanup()
        sys.exit(1)

    print("Starting color sensor and image analysis loop. Press Ctrl+C to exit.")

    while running:
        sensor_data = get_sensor_color_data()
        dominant_color = find_dominant_image_color()

        print(f"Sensor Data: R={sensor_data[0]}, G={sensor_data[1]}, B={sensor_data[2]}, Clear={sensor_data[3]}")
        print(f"Dominant Image Color: {dominant_color}")

        time.sleep(1)

    print("\nExiting program.")
    cleanup()

if __name__ == "__main__":
    main()

