#!/usr/bin/env python3
"""
Wildlife tracking IoT hub for Raspberry Pi.
Accepts remote control commands over TCP and reports GPS coordinates.
Supports Adafruit Ultimate GPS via UART (GPIO14/15) or simulated data.
"""

import json
import logging
import signal
import socket
import sys
import time
from typing import Optional, Tuple

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    stream=sys.stderr
)
logger = logging.getLogger(__name__)

# Constants
LISTEN_HOST = "127.0.0.1"
LISTEN_PORT = 9099
GPS_UART_PORT = "/dev/serial0"  # GPIO14 (TX) and GPIO15 (RX)
GPS_UART_BAUD = 9600
GPS_SIMULATED_INTERVAL = 5.0  # seconds

# Global state
tracking_state = "stopped"
gps_module: Optional["GPSModule"] = None
shutdown_requested = False


class GPSModule:
    """Represents a GPS module with read and write capabilities."""

    def __init__(self, port: str, baudrate: int):
        self.port = port
        self.baudrate = baudrate
        self._serial = None
        self._initialize()

    def _initialize(self):
        """Initialize the serial connection to the GPS module."""
        try:
            import serial
            self._serial = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                timeout=1.0
            )
            logger.info("GPS module initialized on %s at %d baud", self.port, self.baudrate)
        except serial.SerialException as e:
            logger.error("Failed to initialize GPS module on %s: %s", self.port, e)
            self._serial = None

    def read_position(self) -> Optional[Tuple[float, float]]:
        """Read GPS coordinates. Returns (lat, lon) or None on failure."""
        if self._serial is None:
            return None
        try:
            import serial
            if self._serial.in_waiting > 0:
                line = self._serial.readline().decode("utf-8", errors="ignore").strip()
                if line.startswith("$GPRMC"):
                    # Parse RMC sentence: fields[2] = latitude, fields[4] = longitude
                    fields = line.split(",")
                    if len(fields) >= 6 and fields[2] == "A":
                        lat = float(fields[3])
                        lon = float(fields[5])
                        return lat, lon
            return None
        except (serial.SerialException, ValueError) as e:
            logger.error("GPS read error: %s", e)
            return None

    def close(self):
        """Close the serial connection."""
        if self._serial and self._serial.is_open:
            self._serial.close()
            logger.info("GPS serial connection closed")


def read_gps_position() -> Optional[Tuple[float, float]]:
    """Read GPS coordinates from the module or simulate if unavailable."""
    if gps_module and gps_module._serial and gps_module._serial.is_open:
        return gps_module.read_position()
    else:
        return _simulate_gps_coordinates()


def _simulate_gps_coordinates() -> Optional[Tuple[float, float]]:
    """Simulate GPS coordinates for testing."""
    import random
    lat = 37.7749 + random.uniform(-0.005, 0.005)
    lon = -122.4194 + random.uniform(-0.005, 0.005)
    logger.info("Simulated GPS: lat=%.6f, lon=%.6f", lat, lon)
    return lat, lon


def handle_command(command_text: str) -> str:
    """Process a remote control command and return a JSON response."""
    global tracking_state
    command_text = command_text.strip().lower()
    if command_text == "start":
        tracking_state = "running"
        return json.dumps({"status": "tracking started"})
    elif command_text == "stop":
        tracking_state = "stopped"
        return json.dumps({"status": "tracking stopped"})
    elif command_text == "report":
        lat, lon = read_gps_position()
        if lat is not None and lon is not None:
            return json.dumps({"lat": round(lat, 6), "lon": round(lon, 6)})
        else:
            return json.dumps({"error": "GPS read failed"})
    else:
        return json.dumps({"error": "unknown command"})


def signal_handler(signum, frame):
    """Handle shutdown signals gracefully."""
    global shutdown_requested
    logger.info("Received signal %d, shutting down...", signum)
    shutdown_requested = True


def main():
    """Main entry point: initialize GPS, set up socket, handle connections."""
    global gps_module

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize GPS module
    try:
        gps_module = GPSModule(GPS_UART_PORT, GPS_UART_BAUD)
    except Exception as e:
        logger.error("Failed to initialize GPS module: %s", e)
        gps_module = None

    # Create listening socket
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        server_socket.bind((LISTEN_HOST, LISTEN_PORT))
        server_socket.listen(1)
        server_socket.settimeout(2.0)
        logger.info("Listening on %s:%d", LISTEN_HOST, LISTEN_PORT)
    except socket.error as e:
        logger.error("Failed to bind socket: %s", e)
        if gps_module:
            gps_module.close()
        sys.exit(1)

    try:
        while not shutdown_requested:
            try:
                client_socket, client_address = server_socket.accept()
                logger.info("Connection from %s", client_address)
                try:
                    data = client_socket.recv(1024).decode("utf-8", errors="ignore").strip()
                    if data:
                        response = handle_command(data)
                        client_socket.sendall(response.encode("utf-8"))
                    else:
                        logger.info("Empty request from %s", client_address)
                except socket.error as e:
                    logger.error("Socket error during communication: %s", e)
                finally:
                    client_socket.close()
            except socket.timeout:
                continue
            except Exception as e:
                logger.error("Unexpected error handling connection: %s", e)
    finally:
        server_socket.close()
        if gps_module:
            gps_module.close()
        logger.info("Shutdown complete")


if __name__ == "__main__":
    main()

