import random
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Configuration
ALERT_PIN = 18          # BCM GPIO 18 (physical pin 12)
QUALITY_THRESHOLD = 50  # Water quality below this triggers an alert
ITERATIONS = 5
DELAY_SECONDS = 2


def read_water_quality():
    """Simulate reading water quality as a percentage (0-100)."""
    return random.randint(0, 100)


def main():
    # gpiozero automatically cleans up GPIO on program exit, but we
    # explicitly close the LED handle so the alert LED is turned off
    # immediately on Ctrl-C.
    try:
        alert_led = LED(ALERT_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize LED on GPIO {ALERT_PIN}: {exc}")
        return

    try:
        for i in range(1, ITERATIONS + 1):
            quality = read_water_quality()
            alert = quality < QUALITY_THRESHOLD

            if alert:
                alert_led.on()
                status = "ALERT: Water Quality Low!"
            else:
                alert_led.off()
                status = "Water Quality OK"

            print(f"[{i}/{ITERATIONS}] Water Quality: {quality}% | {status}")

            if i < ITERATIONS:
                time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        # Ensure the LED is off and release the GPIO resource.
        try:
            alert_led.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

