import random
import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

pump = None
running = True


def cleanup():
    """Turn the pump off and release GPIO resources."""
    global pump
    if pump is not None:
        try:
            pump.off()
            pump.close()
        except Exception:
            pass
        pump = None


def handle_signal(signum, frame):
    """Handle SIGTERM/SIGINT for graceful shutdown."""
    global running
    running = False


def read_moisture():
    """Simulate a soil-moisture sensor reading (0-100 inclusive)."""
    return random.randint(0, 100)


def main():
    global pump

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # Initialize the pump GPIO pin
    try:
        pump = OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error: Failed to initialize GPIO {PUMP_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: Unexpected GPIO initialization failure on pin {PUMP_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(1, ITERATIONS + 1):
            if not running:
                break

            moisture = read_moisture()
            print(f"[{i}/{ITERATIONS}] Soil Moisture: {moisture}%")

            if moisture < MOISTURE_THRESHOLD:
                pump.on()
                print("  -> Water Pump ON: Soil too dry")
            else:
                pump.off()
