import random
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Configuration
LED_PIN = 17
LIGHT_THRESHOLD = 50
NUM_CYCLES = 5
DELAY_SECONDS = 2


def simulate_light_level() -> int:
    """Simulate an ambient light sensor reading (0-100 inclusive)."""
    return random.randint(0, 100)


def control_led(led: LED, light_level: int) -> None:
    """Control the LED based on the simulated light level."""
    if light_level < LIGHT_THRESHOLD:
        led.on()
        print("LED ON: Light level too low")
    else:
        led.off()
        print("LED OFF: Sufficient light")


def main() -> None:
    """Main function to run the light simulation and LED control."""
    try:
        # gpiozero handles pin setup and cleanup automatically via its context manager.
        with LED(LED_PIN) as led:
            for cycle in range(1, NUM_CYCLES + 1):
                light_level = simulate_light_level()
                print(f"Cycle {cycle}/{NUM_CYCLES}: Simulated Light Level: {light_level}%")
                control_led(led, light_level)
                if cycle < NUM_CYCLES:
                    time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nScript interrupted by user. Exiting gracefully...")
    except GPIOZeroError as e:
        print(f"GPIO error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # gpiozero's context manager ensures the underlying GPIO pin is released.
        # No explicit close() is needed; the context manager handles cleanup.
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

