import RPi.GPIO as GPIO
import time
import datetime
import sys

# Configuration
PIR_PIN = 4
FEEDING_START_HOUR = 7
FEEDING_END_HOUR = 8
EVENING_START_HOUR = 18
EVENING_END_HOUR = 19
FEEDING_DURATION = 60  # seconds
POLL_INTERVAL = 1  # seconds

def is_feeding_time(now):
    """Return True if now is between 7:00-8:00 AM or 6:00-7:00 PM."""
    hour = now.hour
    minute = now.minute
    if (hour == FEEDING_START_HOUR and minute >= 0) or (hour > FEEDING_START_HOUR and hour < FEEDING_END_HOUR):
        return True
    if (hour == EVENING_START_HOUR and minute >= 0) or (hour > EVENING_START_HOUR and hour < EVENING_END_HOUR):
        return True
    return False

def log_motion():
    """Log a motion event with timestamp."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"Motion detected at {timestamp}")

def main():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    last_feeding_time = None

    try:
        while True:
            try:
                if GPIO.input(PIR_PIN):
                    now = datetime.datetime.now()
                    log_motion()

                    if is_feeding_time(now):
                        if last_feeding_time is None or (now - last_feeding_time).total_seconds() >= FEEDING_DURATION:
                            print("Feeding initiated at", now.strftime("%Y-%m-%d %H:%M:%S"))
                            last_feeding_time = now
                        else:
                            print("Not feeding time or recently fed.")
                    else:
                        print("Not feeding time or recently fed.")
            except Exception as e:
                print(f"Error reading PIR sensor: {e}")

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

