import RPi.GPIO as GPIO
import time
import logging
import sys

# Configure logging for the educational servo controller
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# Servo control constants
SERVO_PIN = 18
PWM_FREQUENCY = 50  # Hz, standard for hobby servos
MIN_DUTY_CYCLE = 2.5  # 0 degrees
MAX_DUTY_CYCLE = 12.5  # 180 degrees


class ServoController:
    """Control a single-channel PWM servo on a Raspberry Pi using RPi.GPIO."""

    def __init__(self, pin):
        """Initialize the servo controller on the given GPIO pin (BCM numbering)."""
        self.pin = pin
        self.pwm_channel = None
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT)
            self.pwm_channel = GPIO.PWM(self.pin, PWM_FREQUENCY)
            self.pwm_channel.start(0)  # Start with 0% duty cycle (no signal)
            logging.info("Servo controller initialized on GPIO %d", self.pin)
        except Exception as e:
            logging.error("Failed to initialize servo controller: %s", e)
            raise

    def _angle_to_duty_cycle(self, angle):
        """Convert an angle (0-180 degrees) to a PWM duty cycle (2.5-12.5%)."""
        if not 0 <= angle <= 180:
            raise ValueError("Angle must be between 0 and 180 degrees")
        return MIN_DUTY_CYCLE + (angle / 180.0) * (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE)

    def move_to(self, angle):
        """Move the servo to the specified angle (0-180 degrees)."""
        if self.pwm_channel is None:
            raise RuntimeError("PWM channel not initialized")
        duty_cycle = self._angle_to_duty_cycle(angle)
        self.pwm_channel.ChangeDutyCycle(duty_cycle)
        logging.info("Servo moved to angle %d (duty cycle %.2f%%)", angle, duty_cycle)

    def stop(self):
        """Stop the servo PWM signal and release the GPIO pin."""
        if self.pwm_channel is not None:
            try:
                self.pwm_channel.stop()
                logging.info("Servo PWM stopped")
            except Exception as e:
                logging.error("Error stopping PWM: %s", e)
        try:
            GPIO.cleanup(self.pin)
            logging.info("GPIO pin %d cleaned up", self.pin)
        except Exception as e:
            logging.error("Error cleaning up GPIO: %s", e)


def demonstrate_servo(controller, angle_list):
    """Move the servo through a list of angles for student observation."""
    for angle in angle_list:
        controller.move_to(angle)
        time.sleep(0.5)


def main():
    """Main entry point: initialize controller, demonstrate sweep, handle cleanup."""
    controller = None
    try:
        controller = ServoController(SERVO_PIN)
        angles = [0, 45, 90, 135, 180, 135, 90, 45, 0]
        demonstrate_servo(controller, angles)
    except KeyboardInterrupt:
        logging.info("Demonstration interrupted by user")
    except Exception as e:
        logging.error("Unexpected error: %s", e)
        sys.exit(1)
    finally:
        if controller is not None:
            controller.stop()


if __name__ == "__main__":
    main()

