import signal
import sys
import time
from gpiozero import AngularServo, OutputDeviceBadValue, GPIODeviceError

# SG90 servo pulse-width limits (0.5ms = 0 deg, 2.5ms = 180 deg)
MIN_PULSE_WIDTH = 0.5 / 1000
MAX_PULSE_WIDTH = 2.5 / 1000
FREQUENCY = 50


class RoboticArm:
    """Control three SG90 servos (base, shoulder, gripper) via gpiozero."""

    def __init__(self, base_pin=17, shoulder_pin=27, gripper_pin=22):
        self.base_servo = None
        self.shoulder_servo = None
        self.gripper_servo = None
        try:
            self.base_servo = AngularServo(
                base_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=MIN_PULSE_WIDTH,
                max_pulse_width=MAX_PULSE_WIDTH,
                frame_width=1.0 / FREQUENCY,
            )
            self.shoulder_servo = AngularServo(
                shoulder_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=MIN_PULSE_WIDTH,
                max_pulse_width=MAX_PULSE_WIDTH,
                frame_width=1.0 / FREQUENCY,
            )
            self.gripper_servo = AngularServo(
                gripper_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=MIN_PULSE_WIDTH,
                max_pulse_width=MAX_PULSE_WIDTH,
                frame_width=1.0 / FREQUENCY,
            )
        except GPIODeviceError as exc:
            self.release()
            raise RuntimeError(f"Failed to initialize servos: {exc}") from exc

    def move_joint(self, servo, target_angle):
        """Move a single servo to *target_angle* (clamped to [-90, 90]) and settle."""
        if servo is None:
            return
        clamped = max(-90, min(90, target_angle))
        try:
            servo.angle = clamped
        except OutputDeviceBadValue as exc:
            raise ValueError(f"Invalid angle {target_angle} for servo: {exc}") from exc
        time.sleep(0.4)

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        """Move all three joints to the specified pose sequentially."""
        self.move_joint(self.base_servo, base_angle)
        self.move_joint(self.shoulder_servo, shoulder_angle)
        self.move_joint(self.gripper_servo, gripper_angle)

    def release(self):
        """Detach all servos (angle = None) to stop sending pulses."""
        for servo in (self.base_servo, self.shoulder_servo, self.gripper_servo):
            if servo is not None:
                try:
                    servo.angle = None
                except Exception:
                    pass

    def close(self):
        """Release servos and close gpiozero resources."""
        self.release()
        for servo in (self.base_servo, self.shoulder_servo, self.gripper_servo):
            if servo is not None:
                try:
                    servo.close()
                except Exception:
                    pass


def run_demo_sequence(robot_arm):
    """Execute a predefined sequence of arm poses."""
    poses = [
        (0, 0, 0),
        (45, -30, 20),
        (-45, 30, -20),
        (0, 0, 0),
    ]
    for base_angle, shoulder_angle, gripper_angle in poses:
        print(f"Moving to pose: base={base_angle}, shoulder={shoulder_angle}, gripper={gripper_angle}")
        robot_arm.go_to_pose(base_angle, shoulder_angle, gripper_angle)


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, exiting...")
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    robot_arm = None
    try:
        robot_arm = RoboticArm()
        run_demo_sequence(robot_arm)
    except (ValueError, RuntimeError) as exc:
        print(f"Error: {exc}", file=sys.stderr)
    finally:
        if robot_arm is not None:
            robot_arm.close()


if __name__ == "__main__":
    main()

