import signal
import sys
import logging
from typing import Dict, Any, Optional

import serial
from pymodbus.client import ModbusSerialClient
from pymodbus.exceptions import ModbusIOException, ModbusException
from pymodbus.payload import BinaryPayloadDecoder
from pymodbus.constants import Endian

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class Servo:
    """
    A class to control a servo motor via Modbus RTU over Raspberry Pi UART.
    """

    # Constants for Modbus function codes
    FC_READ_HOLDING_REGISTERS = 3
    FC_WRITE_SINGLE_REGISTER = 6
    FC_WRITE_MULTIPLE_REGISTERS = 16

    # Constants for servo control
    CONTROL_STOP = 0x0006
    CONTROL_START = 0x000F

    # Constants for operating modes
    OPMODE_POSITION = 1

    # Register map: {name: {R/W: 'R' or 'W', Register: hex_address, functioncode: FC, Value: {sub_values}}}
    REGISTERS: Dict[str, Dict[str, Any]] = {
        "STATUS": {"R/W": "R", "Register": 0x3000, "functioncode": FC_READ_HOLDING_REGISTERS},
        "CONTROL": {
            "R/W": "W",
            "Register": 0x3100,
            "functioncode": FC_WRITE_SINGLE_REGISTER,
            "Value": {"Stop": CONTROL_STOP, "Start": CONTROL_START},
        },
        "OPMODE": {
            "R/W": "W",
            "Register": 0x3500,
            "functioncode": FC_WRITE_SINGLE_REGISTER,
            "Value": {"Position": OPMODE_POSITION},
        },
        "VelocityCommand": {
            "R/W": "W",
            "Register": 0x6F00,
            "functioncode": FC_WRITE_SINGLE_REGISTER,
        },
        "VelocityFeedback": {
            "R/W": "R",
            "Register": 0x3B00,
            "functioncode": FC_READ_HOLDING_REGISTERS,
            "read_length": 2,
        },
        "PositionCommand": {
            "R/W": "W",
            "Register": 0x4000,
            "functioncode": FC_WRITE_SINGLE_REGISTER,
        },
        "PositionFeedback": {
            "R/W": "R",
            "Register": 0x3700,
            "functioncode": FC_READ_HOLDING_REGISTERS,
            "read_length": 2,
        },
    }

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 115200, timeout: float = 1.0):
        """
        Initializes the Servo object and establishes a Modbus RTU connection.

        Args:
            port (str): The serial port to use (default: /dev/serial0).
            baudrate (int): The baud rate for the serial connection (default: 115200).
            timeout (float): The timeout for serial operations in seconds (default: 1.0).
        """
        self.client: Optional[ModbusSerialClient] = None
        self._connected = False
        self._original_sigint = signal.getsignal(signal.SIGINT)

        try:
            self.client = ModbusSerialClient(
                method="rtu",
                port=port,
                baudrate=baudrate,
                parity="N",
                stopbits=1,
                bytesize=8,
                timeout=timeout,
            )
            if not self.client.connect():
                raise ConnectionError(f"Failed to connect to Modbus device on {port}")
            self._connected = True
            logger.info(f"Connected to Modbus device on {port} at {baudrate} baud.")
        except serial.SerialException as e:
            logger.warning(f"Serial port {port} unavailable or connection failed: {e}. "
                           f"Running in degraded mode.")
            self.client = None
            self._connected = False
        except Exception as e:
            logger.error(f"Error initializing Modbus client: {e}")
            self.client = None
            self._connected = False

    def _read_register(self, register_name: str, count: int = 1) -> Optional[int]:
        """
        Reads a value from a Modbus holding register.

        Args:
            register_name (str): The name of the register to read.
            count (int): The number of registers to read (default: 1).

        Returns:
            Optional[int]: The value read from the register, or None on error.
        """
        if not self._connected or self.client is None:
            logger.error("Modbus client not connected. Cannot read register.")
            return None

        register = self.REGISTERS.get(register_name)
        if not register:
            logger.error(f"Invalid register name: {register_name}")
            return None

        if register["R/W"] != "R":
            logger.error(f"Register {register_name} is not readable.")
            return None

        try:
            address = register["Register"]
            result = self.client.read_holding_registers(address=address, count=count)
            if result.isError():
                logger.error(f"Modbus error reading {register_name} (FC={register['functioncode']}): {result}")
                return None

            decoder = BinaryPayloadDecoder.fromRegisters(result.registers, byteorder=Endian.BIG)
            if count == 1:
                return decoder.decode_16bit_int()
            else:
                return decoder.decode_32bit_float()
        except ModbusIOException as e:
            logger.error(f"Modbus IO error reading {register_name}: {e}")
            return None
        except ModbusException as e:
            logger.error(f"Modbus exception reading {register_name}: {e}")
            return None
        except Exception as e:
            logger.error(f"Unexpected error reading {register_name}: {e}")
            return None

    def _write_register(self, register_name: str, value: int) -> bool:
        """
        Writes a value to a Modbus holding register.

        Args:
            register_name (str): The name of the register to write.
            value (int): The value to write to the register.

        Returns:
            bool: True if the write was successful, False otherwise.
        """
        if not self._connected or self.client is None:
            logger.error("Modbus client not connected. Cannot write register.")
            return False

        register = self.REGISTERS.get(register_name)
        if not register:
            logger.error(f"Invalid register name: {register_name}")
            return False

        if register["R/W"] != "W":
            logger.error(f"Register {register_name} is not writable.")
            return False

        try:
            address = register["Register"]
            if register["functioncode"] == self.FC_WRITE_SINGLE_REGISTER:
                result = self.client.write_register(address=address, value=value)
