#!/usr/bin/env python3
"""
Raspberry Pi Zero W Smart Garden Controller

Reads soil moisture from an Adafruit Seesaw sensor (I2C 0x36) and controls
a 12V water pump via a relay on GPIO17 (BCM).  Prints status every 10 s.

Hardware:
  * Raspberry Pi Zero W
  * Adafruit Seesaw soil-moisture sensor (I2C address 0x36)
  * 12V water pump relay module on GPIO17 (BCM)

Dependencies:
  pip install adafruit-circuitpython-seesaw gpiozero
"""

import signal
import sys
import time

import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_ADDRESS = 0x36
PUMP_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL_S = 10

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_i2c = None
_sensor = None
_pump = None
_running = True


def _cleanup() -> None:
    """Turn the pump off and release hardware resources."""
    global _pump, _sensor, _i2c
    if _pump is not None:
        try:
            _pump.off()
            _pump.close()
        except Exception:
            pass
        _pump = None

    if _sensor is not None:
        try:
            _sensor.deinit()
        except Exception:
            pass
        _sensor = None

    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_i2c() -> busio.I2C:
    """Initialize the I2C bus; raise on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize I2C bus: {exc}") from exc


def _init_sensor(i2c_bus: busio.I2C) -> adafruit_seesaw.seesaw.Seesaw:
    """Initialize the Seesaw soil-moisture sensor; raise on failure."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
    except Exception as exc:
        raise RuntimeError(
            f"Seesaw sensor not found at 0x{I2C_ADDRESS:02X} on I2C bus: {exc}"
        ) from exc


def _init_pump(pin: int) -> OutputDevice:
    """Initialize the pump relay GPIO; raise on failure."""
    try:
        return OutputDevice(pin, active_high=True, initial_value=False)
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize pump GPIO{pin}: {exc}") from exc


def _read_moisture(sensor: adafruit_seesaw.seesaw.Seesaw) -> int:
    """Read soil moisture; return -1 on error."""
    try:
        return sensor.moisture_read()
    except Exception as exc:
        print(f"Error reading soil moisture: {exc}", file=sys.stderr)
        return -1


def _control_pump(pump: OutputDevice, moisture: int) -> None:
    """Activate the pump when moisture is below threshold, else deactivate."""
    try:
        if moisture < MOISTURE_THRESHOLD:
            pump.on()
            print("Pump ON: soil too dry")
        else:
            pump.off()
            print("Pump OFF: soil moisture adequate")
    except Exception as exc:
        print(f"Error controlling pump: {exc}", file=sys.stderr)


def main() -> int:
    global _i2c, _sensor, _pump

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- Initialize I2C bus -------------------------------------------------
    try:
        _i2c = _init_i2c()
    except RuntimeError as exc:
        print(f"Fatal: {exc}", file=sys.stderr)
        return 1

    # --- Initialize sensor --------------------------------------------------
    try:
        _sensor = _init_sensor(_i2c)
    except RuntimeError as exc:
        print(f"Fatal: {exc}", file=sys.stderr)
        _cleanup()
        return 1

    # --- Initialize pump GPIO ----------------------------------------------
    try:
        _pump = _init_pump(PUMP_GPIO_PIN)
    except RuntimeError as exc:
        print(f"Fatal: {exc}", file=sys.stderr)
        _cleanup()
        return 1

    print("Smart Garden Controller started. Press Ctrl+C to exit.")

    # --- Main loop ----------------------------------------------------------
    try:
        while _running:
            moisture = _read_moisture(_sensor)
            if moisture >= 0:
                print(f"Soil Moisture: {moisture}")
                _control_pump(_pump, moisture)
            else:
                print("Sensor read failed; skipping pump control this cycle.")

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < READ_INTERVAL_S:
                time.sleep(0.25)
                slept += 0.25

    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
        return 1
    finally:
        _cleanup()
        print("Smart Garden Controller stopped.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

