import signal
import sys
import logging
import minimalmodbus
import serial

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ServoMotorController:
    """
    Controls a Modbus RTU servo motor on a Raspberry Pi via /dev/serial0.
    """

    def __init__(self, port='/dev/serial0', slave_address=1, baudrate=115200):
        self.port = port
        self.slave_address = slave_address
        self.baudrate = baudrate
        self.instrument = None
        self._running = True

        try:
            self.instrument = minimalmodbus.Instrument(self.port, self.slave_address)
            self.instrument.serial.baudrate = self.baudrate
            self.instrument.serial.parity = serial.PARITY_NONE
            self.instrument.serial.bytesize = 8
            self.instrument.serial.stopbits = 1
            self.instrument.serial.timeout = 1.0
            self.instrument.mode = minimalmodbus.MODE_RTU
            self.instrument.clear_cache()
            logger.info(f"Connected to servo on {self.port} at {self.baudrate} baud (slave {self.slave_address}).")
        except serial.SerialException as e:
            logger.error(f"Failed to open serial port {self.port}: {e}")
            self.instrument = None
        except Exception as e:
            logger.error(f"Unexpected error initializing Modbus instrument: {e}")
            self.instrument = None

    def _check_connection(self):
        if self.instrument is None:
            logger.error("Not connected to the servo. Call connect() first.")
            return False
        return True

    def connect(self):
        return self.instrument is not None

    def disconnect(self):
        self._running = False
        if self.instrument is not None:
            try:
                self.instrument.serial.close()
                logger.info("Serial port closed.")
            except Exception as e:
                logger.error(f"Error closing serial port: {e}")
            finally:
                self.instrument = None

    def set_operation_mode(self, mode):
        if not self._check_connection():
            return False
        if not isinstance(mode, int) or not (0 <= mode <= 0xFFFF):
            logger.error(f"Invalid operation mode: {mode}. Must be a 16-bit integer.")
            return False
        try:
            self.instrument.write_register(0x3500, mode, signed=True)
            logger.info(f"Set operation mode to {mode:#06x}.")
            return True
        except minimalmodbus.NoResponseError:
            logger.error("No response from servo (check wiring and slave address).")
            return False
        except minimalmodbus.ModbusException as e:
            logger.error(f"Modbus error setting operation mode: {e}")
            return False
        except serial.SerialException as e:
            logger.error(f"Serial communication error: {e}")
            return False
        except Exception as e:
            logger.error(f"Unexpected error setting operation mode: {e}")
            return False

    def write_position_command(self, value):
        if not self._check_connection():
            return False
        if not isinstance(value, int) or not (-0xFFFF <= value <= 0xFFFF):
            logger.error(f"Invalid position value: {value}. Must be a 16-bit signed integer.")
            return False
        try:
            self.instrument.write_register(0x4000, value, signed=True)
            logger.info(f"Set position command to {value:#06x}.")
            return True
        except minimalmodbus.NoResponseError:
            logger.error("No response from servo (check wiring and slave address).")
            return False
        except minimalmodbus.ModbusException as e:
            logger.error(f"Modbus error writing position command: {e}")
            return False
        except serial.SerialException as e:
            logger.error(f"Serial communication error: {e}")
            return False
        except Exception as e:
            logger.error(f"Unexpected error writing position command: {e}")
            return False

    def write_velocity_command(self, value):
