import time
import signal
import sys
from gpiozero import OutputDevice, Servo
from gpiozero.exc import GPIOZeroError, DeviceClosed

# Constants for GPIO pins
LASER_PIN = 17
HORIZONTAL_SERVO_PIN = 18
VERTICAL_SERVO_PIN = 19

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


class Laser:
    """Controls the laser module via gpiozero OutputDevice."""

    def __init__(self, pin=LASER_PIN):
        self.pin = pin
        try:
            self.device = OutputDevice(pin)
        except GPIOZeroError as e:
            raise RuntimeError(f"Failed to initialize laser on GPIO{pin}: {e}") from e

    def on(self):
        if self.device is None:
            raise RuntimeError("Laser device is not initialized.")
        self.device.on()

    def off(self):
        if self.device is None:
            raise RuntimeError("Laser device is not initialized.")
        self.device.off()

    def close(self):
        """Release the GPIO resource cleanly."""
        if self.device is not None:
            try:
                self.device.close()
            except DeviceClosed:
                pass
            except Exception:
                pass
            finally:
                self.device = None


class Aim:
    """Controls the servo motors and laser for aiming."""

    def __init__(self, ld=0.1, sd=0.5):
        self.ld = ld
        self.sd = sd
        self.hp = [0.0] * 10
        self.vp = [0.0] * 10
        self.laser = Laser()
        try:
            self.h = Servo(HORIZONTAL_SERVO_PIN)
            self.v = Servo(VERTICAL_SERVO_PIN)
        except GPIOZeroError as e:
            self.laser.close()
            raise RuntimeError(f"Failed to initialize servos: {e}") from e

    def aim(self, nums):
        """Aim at targets specified by nums (1-based indices)."""
        global _running
        if not _running:
            return

        try:
            for b in nums:
                if not _running:
                    break
                idx = b - 1
                self.h.value = self.hp[idx]
                self.v.value = self.vp[idx]
                self.laser.on()
                time.sleep(self.ld)
                self.laser.off()
                self.h.value = self.hp[10]
                self.v.value = self.vp[10]
                time.sleep(self.sd / 2)
        except KeyboardInterrupt:
            raise
        except Exception as e:
            print(f"Error during aiming: {e}", file=sys.stderr)
        finally:
            self.laser.off()

    def close(self):
        """Release servo and laser resources cleanly."""
        try:
            self.h.close()
        except Exception:
            pass
        try:
            self.v.close()
        except Exception:
            pass
        self.laser.close()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        aim = Aim(ld=0.1, sd=0.5)
        aim.aim([1, 2, 3])
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        if 'aim' in locals():
            aim.close()
        sys.exit(0)

