import signal
import sys
import time
from typing import Tuple

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit-circuitpython-servokit not installed. Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# Constants for servo channels
BASE = 0
DROP = 1
SEEK = 2
GRAB = 4

# Constants for object types
METAL = 135
PLASTIC = 180
PAPER = 90

# Constants for drop angles
DROP_ANGLES = {
    "metal": METAL,
    "plastic": PLASTIC,
    "paper": PAPER,
}

# Constants for servo movement
SERVO_STEP_SIZE = 5
SERVO_DELAY = 0.04

# Global kit reference for cleanup
kit = None


def initialize_servokit() -> ServoKit:
    """Initializes the ServoKit object with error handling."""
    try:
        return ServoKit(channels=16)
    except Exception as e:
        print(f"Error initializing ServoKit: {e}")
        sys.exit(1)


def move_servo(servo_kit: ServoKit, channel: int, target_angle: int, step_size: int = SERVO_STEP_SIZE, delay: float = SERVO_DELAY) -> None:
    """Moves a servo smoothly to a target angle with error handling."""
    if not 0 <= channel <= 15:
        print(f"Error: Invalid servo channel {channel}. Must be 0-15.")
        return
    if not 0 <= target_angle <= 180:
        print(f"Error: Invalid target angle {target_angle}. Must be 0-180.")
        return

    try:
        current_angle = servo_kit.servo[channel].angle
        if current_angle is None:
            current_angle = 0

        # Determine direction and step
        if target_angle > current_angle:
            step = step_size
        elif target_angle < current_angle:
            step = -step_size
        else:
            step = 0

        # Move smoothly
        while 0 <= current_angle <= 180 and step != 0:
            current_angle += step
            servo_kit.servo[channel].angle = current_angle
            time.sleep(delay)

        # Ensure final position is exact
        servo_kit.servo[channel].angle = target_angle
    except Exception as e:
        print(f"Error moving servo on channel {channel}: {e}")


def seek(angle: int) -> None:
    """Moves the seek servo to the specified angle."""
    move_servo(kit, SEEK, angle)


def deseek(angle: int) -> None:
    """Moves the seek servo back to the default position (180 degrees)."""
    move_servo(kit, SEEK, 180)


def drop(angle: int) -> None:
    """Moves the drop servo to the specified angle."""
    move_servo(kit, DROP, angle)


def pick(angle: int) -> None:
    """Closes the gripper."""
    move_servo(kit, GRAB, angle)


def grab(angle: int) -> None:
    """Opens the gripper."""
    move_servo(kit, GRAB, angle)


def release(angle: int) -> None:
    """Releases the gripper."""
    move_servo(kit, GRAB, angle)


def collect_object_steps(seek_angle: int) -> None:
    """Performs the sequence of actions to collect an object."""
    seek(seek_angle)
    pick(90)
    drop(160)
    release(100)
    deseek(90)


def drop_object_steps(drop_angle: int) -> None:
    """Performs the sequence of actions to drop an object."""
    move_servo(kit, DROP, drop_angle, step_size=2, delay=0.01)
    release(120)
    move_servo(kit, DROP, 100, step_size=2, delay=0.01)


def get_pos_x(x_center: int) -> int:
    """Calculates the x position based on the x-coordinate of the object."""
    if x_center < 0 or x_center > 320:
        print("Error: x_center out of range (0-320).")
        return 90
    return int(180 / 320 * x_center)


def get_pos_y(y_center: int) -> int:
    """Calculates the y position based on the y-coordinate of the object."""
    if y_center < 0 or y_center > 320:
        print("Error: y_center out of range (0-320).")
        return 90
    return int(180 / 320 * y_center)


def collect_object(x_center: int, y_center: int, drop_angle: int) -> None:
    """Collects an object based on its coordinates and drops it at the specified angle."""
    pos_x = get_pos_x(x_center)
    pos_y = get_pos_y(y_center)

    move_servo(kit, BASE, pos_x)
    collect_object_steps(pos_y)
    drop_object_steps(drop_angle)
    move_servo(kit, BASE, 90)


def cleanup(signum=None, frame=None) -> None:
    """Clean up resources and stop all servos on exit."""
    global kit
    if kit is not None:
        try:
            for ch in range(16):
                kit.servo[ch].angle = None
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main() -> None:
    """Main function to demonstrate object collection."""
    global kit
    kit = initialize_servokit()

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        # Example usage: collect an object at center (160, 160) and drop it at 90 degrees
        collect_object(160, 160, 90)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()


if __name__ == "__main__":
    main()

