from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

app = Flask(__name__)

RELAY_PIN = 23
relay = None

def cleanup(signum=None, frame=None):
    global relay
    if relay is not None:
        relay.close()
        relay = None
    if signum is not None:
        sys.exit(0)

@app.route('/relay', methods=['POST'])
def relay_control():
    global relay
    if relay is None:
        return jsonify({'error': 'Relay not initialized'}), 500

    try:
        data = request.get_json(silent=True)
        if data is None:
            return jsonify({'error': 'Invalid request: JSON required'}), 400

        state = data.get('state')
        if state not in ('on', 'off'):
            return jsonify({'error': 'Invalid request: state must be "on" or "off"'}), 400

        if state == 'on':
            relay.on()
        else:
            relay.off()

        return jsonify({'status': 'Relay state changed'}), 200

    except GPIOZeroError as e:
        return jsonify({'error': f'GPIO error: {e}'}), 500
    except Exception as e:
        return jsonify({'error': f'Internal server error: {e}'}), 500

if __name__ == '__main__':
    try:
        relay = OutputDevice(RELAY_PIN)
    except GPIOZeroError as e:
        print(f'Failed to initialize GPIO{RELAY_PIN}: {e}', file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        app.run(host='0.0.0.0', port=5000)
    finally:
        cleanup()

