from gpiozero.exc import GPIOZeroError

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

PUMP_PIN = 20
LIGHT_PIN = 21

pump = None
light = None


def parse_intent(phrase):
    """Return a control intent keyword from a plain-English phrase."""
    keywords = {"pump on": "pump_on", "pump off": "pump_off", "light": "light_toggle"}
    phrase_lower = phrase.lower()
    for pattern, intent in keywords.items():
        if pattern in phrase_lower:
            return intent
    return None


def apply_intent(intent):
    """Drive gpiozero actuators according to the parsed intent."""
    global pump, light
    if intent == "pump_on":
        if pump is not None:
            pump.on()
            logging.info("Pump turned ON")
    elif intent == "pump_off":
        if pump is not None:
            pump.off()
            logging.info("Pump turned OFF")
    elif intent == "light_toggle":
        if light is not None:
            light.toggle()
            logging.info("Light toggled")


def safe_shutdown():
    """Turn off and release all gpiozero devices."""
    global pump, light
    for dev, name in [(pump, "pump"), (light, "light")]:
        if dev is not None:
            try:
                dev.off()
                dev.close()
            except GPIOZeroError as e:
                logging.error("Error during %s shutdown: %s", name, e)
    pump = None
    light = None


try:
    pump = OutputDevice(PUMP_PIN)
    light = OutputDevice(LIGHT_PIN)
    logging.info("GPIO devices initialized on BCM %d and %d", PUMP_PIN, LIGHT_PIN)

    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command",
    ]

    for phrase in test_phrases:
        intent = parse_intent(phrase)
        if intent is not None:
            apply_intent(intent)
        else:
            logging.warning("Unknown command: %s", phrase)

except KeyboardInterrupt:
    logging.info("Interrupted by user")
except GPIOZeroError as e:
    logging.error("GPIO error: %s", e)
finally:
    safe_shutdown()

