import smbus2
import time
import signal
import sys

# CCS811 I2C address and register definitions
CCS811_I2C_ADDR = 0x5A
CCS811_REG_APP_START = 0xF4
CCS811_REG_ALG_RESULT_DATA = 0x02

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_sensor(bus):
    """Initialize the CCS811 sensor by writing 0x20 to APP_START register."""
    try:
        bus.write_byte_data(CCS811_I2C_ADDR, CCS811_REG_APP_START, 0x20)
        time.sleep(1.0)  # Wait for sensor to process
        return True
    except OSError as e:
        print(f"Error initializing sensor: {e}")
        return False

def read_co2_level(bus):
    """Read CO2 concentration from the CCS811 sensor and return it in ppm."""
    try:
        # Read 2 bytes from ALG_RESULT_DATA register
        data = bus.read_i2c_block_data(CCS811_I2C_ADDR, CCS811_REG_ALG_RESULT_DATA, 2)
        if len(data) < 2:
            raise IOError("Incomplete data read from sensor")
        co2_level = (data[0] << 8) | data[1]
        return co2_level
    except OSError as e:
        print(f"Error reading CO2 level: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = smbus2.SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}")
        sys.exit(1)

    try:
        # Verify sensor presence before initialization
        try:
            bus.read_byte_data(CCS811_I2C_ADDR, CCS811_REG_APP_START)
        except OSError:
            print(f"Sensor not found at address 0x{CCS811_I2C_ADDR:02X}. Check wiring and I2C configuration.")
            sys.exit(1)

        if not initialize_sensor(bus):
            print("Sensor initialization failed.")
            sys.exit(1)

        # Main loop to read and display CO2 levels
        for i in range(5):
            if not running:
                break
            co2 = read_co2_level(bus)
            if co2 is not None:
                print(f"CO2 Level: {co2} ppm")
            else:
                print(f"CO2 Level: Read failed (attempt {i+1}/5)")
            time.sleep(2)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            bus.close()
            print("I2C bus closed.")

if __name__ == "__main__":
    main()

