import signal
import sys
import logging
from datetime import datetime
from smbus2 import SMBus, i2c_msg

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DS1338:
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07

    def __init__(self, i2c_bus=1, i2c_address=0x68):
        self.i2c_address = i2c_address
        self._bus = None
        try:
            self._bus = SMBus(i2c_bus)
        except OSError as e:
            logger.error(f"Failed to open I2C bus {i2c_bus}: {e}")
            raise
        if not self._probe():
            logger.error(f"No DS1338 found at address 0x{i2c_address:02X} on bus {i2c_bus}")
            self.close()
            raise OSError(f"DS1338 not found at 0x{i2c_address:02X}")
        logger.info(f"DS1338 initialized on bus {i2c_bus} at 0x{i2c_address:02X}")

    def _probe(self):
        try:
            msg = i2c_msg.write(self.i2c_address, [self.REG_SECONDS])
            self._bus.i2c_rdwr(msg)
            return True
        except OSError:
            return False

    @staticmethod
    def _bcd_to_int(bcd):
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    @staticmethod
    def _int_to_bcd(int_val):
        return ((int_val // 10) << 4) | (int_val % 10)

    def _read_register(self, register):
        try:
            return self._bus.read_byte_data(self.i2c_address, register)
        except OSError as e:
            logger.error(f"I2C read error at register 0x{register:02X}: {e}")
            raise

    def _write_register(self, register, value):
        try:
            self._bus.write_byte_data(self.i2c_address, register, value)
        except OSError as e:
            logger.error(f"I2C write error at register 0x{register:02X}: {e}")
            raise

    def read_seconds(self):
        return self._bcd_to_int(self._read_register(self.REG_SECONDS) & 0x7F)

    def read_minutes(self):
        return self._bcd_to_int(self._read_register(self.REG_MINUTES))

    def read_hours(self):
        raw = self._read_register(self.REG_HOURS)
        return self._bcd_to_int(raw & 0x3F)

    def read_date(self):
        return self._bcd_to_int(self._read_register(self.REG_DATE))

    def read_month(self):
        return self._bcd_to_int(self._read_register(self.REG_MONTH))

    def read_year(self):
        return self._bcd_to_int(self._read_register(self.REG_YEAR))

    def read_datetime(self, century=21):
        try:
            year = century * 100 + self.read_year() - 1
            month = self.read_month()
            date = self.read_date()
            hours = self.read_hours()
            minutes = self.read_minutes()
            seconds = self.read_seconds()
            return datetime(year, month, date, hours, minutes, seconds)
        except ValueError as e:
            logger.error(f"Invalid datetime values read from DS1338: {e}")
            raise

    def write_seconds(self, seconds):
        if not 0 <= seconds <= 59:
            raise ValueError("Seconds must be 0-59")
        self._write_register(self.REG_SECONDS, self._int_to_bcd(seconds))

    def write_minutes(self, minutes):
        if not 0 <= minutes <= 59:
            raise ValueError("Minutes must be 0-59")
        self._write_register(self.REG_MINUTES, self._int_to_bcd(minutes))

    def write_hours(self, hours):
        if not 0 <= hours <= 23:
            raise ValueError("Hours must be 0-23")
        self._write_register(self.REG_HOURS, self._int_to_bcd(hours | 0x40))

    def write_date(self, date):
        if not 1 <= date <= 31:
            raise ValueError("Date must be 1-31")
        self._write_register(self.REG_DATE, self._int_to_bcd(date))

    def write_month(self, month):
        if not 1 <= month <= 12:
            raise ValueError("Month must be 1-12")
        self._write_register(self.REG_MONTH, self._int_to_bcd(month))

    def write_year(self, year):
        if not 0 <= year <= 99:
            raise ValueError("Year must be 0-99")
        self._write_register(self.REG_YEAR, self._int_to_bcd(year % 100))

    def write_all(self, year=None, month=None, date=None, hours=None, minutes=None, seconds=None):
        if year is not None:
            self.write_year(year)
        if month is not None:
            self.write_month(month)
        if date is not None:
            self.write_date(date)
        if hours is not None:
            self.write_hours(hours)
        if minutes is not None:
            self.write_minutes(minutes)
        if seconds is not None:
            self.write_seconds(seconds)

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            self._bus = None


def _main():
    rtc = None
    try:
        rtc = DS1338(i2c_bus=1, i2c_address=0x68)
        now = rtc.read_datetime()
        logger.info(f"Current RTC time: {now}")
        rtc.write_all(year=23, month=4, date=5, hours=14, minutes=30, seconds=0)
        rtc.close()
    except (OSError, ValueError) as e:
        logger.error(f"Error: {e}")
    finally:
        if rtc is not None:
            rtc.close()


if __name__ == '__main__':
    _main()

