import serial
import time
import signal
import sys
import re

ESP_OK = b"OK"
ESP_ERROR = b"ERROR"
ESP_FAIL = b"FAIL"
ESP_BUSY = b"busy p...\r\n"
ESP_WIFI_CONNECTED = b"WIFI CONNECTED"
ESP_WIFI_GOT_IP = b"WIFI GOT IP"
ESP_WIFI_DISCONNECT = b"WIFI DISCONNECT"
ESP_WIFI_AP_NOT_FOUND = b"WIFI AP NOT FOUND"
ESP_WIFI_AP_WRONG_PWD = b"WIFI AP WRONG PASSWORD"
ESP_WIFI_DISCONNECTED = b"WIFI DISCONNECTED"
ESP_LINK_DOWN = b"LINK DOWN"
ESP_CLOSED = b"CLOSED"

ESP8266_OK_RESPONSES = [ESP_OK, ESP_BUSY, ESP_WIFI_CONNECTED, ESP_WIFI_GOT_IP, ESP_WIFI_DISCONNECT, ESP_WIFI_AP_NOT_FOUND, ESP_WIFI_AP_WRONG_PWD, ESP_WIFI_DISCONNECTED, ESP_LINK_DOWN, ESP_CLOSED]


class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self._port = port
        self._baud_rate = baud_rate
        self._timeout = timeout
        self._serial = None
        self._running = True
        try:
            self._serial = serial.Serial(port, baud_rate, timeout=timeout)
        except serial.SerialException as e:
            print(f"Error opening serial port {port}: {e}")
            raise

    def _send_command(self, command, timeout=1.0, wait_for=None):
        if not self._serial or not self._serial.is_open:
            print("Serial port is not open.")
            return None
        try:
            self._serial.reset_input_buffer()
            self._serial.write(command.encode('utf-8'))
            self._serial.flush()
            response = b""
            start_time = time.time()
            while time.time() - start_time < timeout:
                if self._serial.in_waiting > 0:
                    chunk = self._serial.read(self._serial.in_waiting)
                    if chunk:
                        response += chunk
                        if wait_for and wait_for in response:
                            return response
                else:
                    time.sleep(0.01)
            return response
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None

    def test_connection(self):
        response = self._send_command("AT\r\n", wait_for=ESP_OK)
        return response is not None

    def restart(self):
        response = self._send_command("AT+RST\r\n", wait_for=ESP_OK)
        if response is None:
            return False
        time.sleep(2)
        return self.test_connection()

