import serial
import time
import threading
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'water_flow_log.txt'
READ_INTERVAL = 1.0

stop_event = threading.Event()


def signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, stopping flow reader...")
    stop_event.set()


def read_flow_data():
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")
        while not stop_event.is_set():
            try:
                raw = ser.readline()
                if not raw:
                    continue
                data = raw.decode('ascii', errors='replace').strip()
                if not data:
                    continue
                try:
                    flow_rate = float(data)
                except ValueError:
                    print(f"Warning: non-numeric data received: {data!r}")
                    continue
                timestamp = datetime.now().isoformat(timespec='seconds')
                print(f"Flow Rate: {flow_rate} L/min")
                with open(LOG_FILE, 'a') as logfile:
                    logfile.write(f"{timestamp} - Flow Rate: {flow_rate} L/min\n")
                time.sleep(READ_INTERVAL)
            except serial.SerialException as e:
                print(f"Serial I/O error: {e}")
                break
            except OSError as e:
                print(f"OS error during read: {e}")
                break
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if ser is not None and ser.is_open:
            try:
                ser.close()
                print("Serial port closed.")
            except Exception as e:
                print(f"Error closing serial port: {e}")


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    reader_thread = threading.Thread(target=read_flow_data, name='FlowReader', daemon=True)
    reader_thread.start()
    try:
        while not stop_event.is_set():
            stop_event.wait(timeout=1.0)
    except KeyboardInterrupt:
        stop_event.set()
    finally:
        reader_thread.join(timeout=2.0)
        if reader_thread.is_alive():
            print("Flow reader thread did not stop cleanly.")
        print("Program terminated.")


if __name__ == "__main__":
    main()

