TIMEOUT = 1  # seconds


@dataclass
class GPS_readings:
    """Dataclass to store GPS readings."""
    latitude: Optional[float] = None
    latitude_dir: Optional[str] = None
    longitude: Optional[float] = None
    longitude_dir: Optional[str] = None
    altitude: Optional[float] = None
    satellites: Optional[int] = None


class GPSReader:
    """Reads and parses GPS data from a serial port."""

    def __init__(self, port: str = SERIAL_PORT, baudrate: int = BAUD_RATE, timeout: int = TIMEOUT):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None
        self._running = True

    def connect(self) -> bool:
        """Connects to the serial port. Returns True on success, False on failure."""
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            print(f"Connected to serial port {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            print(f"Error connecting to serial port {self.port}: {e}", file=sys.stderr)
            self.serial_port = None
            return False
        except Exception as e:
            print(f"Unexpected error opening serial port {self.port}: {e}", file=sys.stderr)
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        """Disconnects from the serial port. Idempotent and safe to call multiple times."""
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    print("Serial port closed.")
            except Exception as e:
                print(f"Error closing serial port: {e}", file=sys.stderr)
            finally:
                self.serial_port = None

    def _signal_handler(self, signum, frame):
        """Handle SIGINT/SIGTERM for clean shutdown."""
        print(f"\nReceived signal {signum}, shutting down...")
        self._running = False

    def read_gps_data(self) -> Optional[GPS_readings]:
        """Reads a line from the serial port and parses it if it's a GPGGA sentence."""
        if self.serial_port is None or not self.serial_port.is_open:
            return None

        try:
            raw_line = self.serial_port.readline()
            if not raw_line:
                # Timeout occurred with no data
                return None

            line = raw_line.decode('ascii', errors='replace').strip()
            if not line.startswith("$GPGGA"):
                return None

            return self._parse_gpgga_sentence(line)
        except serial.SerialException as e:
            print(f"Serial communication error: {e}", file=sys.stderr)
            return None
        except Exception as e:
            print(f"Error reading or parsing GPS data: {e}", file=sys.stderr)
            return None

    def _parse_gpgga_sentence(self, sentence: str) -> GPS_readings:
        """Parses a GPGGA sentence into a GPS_readings dataclass."""
        try:
            parts = sentence.split(",")
            if len(parts) < 15:
                raise ValueError(f"Invalid GPGGA sentence: expected at least 15 fields, got {len(parts)}")

            # Validate talker ID
            talker = parts[0]
            if talker != "$GPGGA":
                raise ValueError(f"Invalid talker ID: {talker}")

            # Validate checksum (simple: check if '*' is present and after the first comma)
            if "*" not in sentence:
                raise ValueError("Checksum missing (no '*' in sentence)")

            # Parse latitude
            latitude_raw = parts[2]
            latitude_dir = parts[3]
            if not latitude_raw or not latitude_dir:
                raise ValueError("Invalid latitude or direction")
            latitude = self._convert_to_decimal(latitude_raw, latitude_dir)
            if latitude is None:
                raise ValueError("Invalid latitude value")

            # Parse longitude
            longitude_raw = parts[4]
            longitude_dir = parts[5]
            if not longitude_raw or not longitude_dir:
                raise ValueError("Invalid longitude or direction")
            longitude = self._convert_to_decimal(longitude_raw, longitude_dir)
            if longitude is None:
                raise ValueError("Invalid longitude value")

            # Parse altitude
            altitude = self._safe_float(parts[9])

            # Parse satellites
            satellites = self._safe_int(parts[7])

            return GPS_readings(
                latitude=latitude,
                latitude_dir=latitude_dir,
                longitude=longitude,
                longitude_dir=longitude_dir,
                altitude=altitude,
                satellites=satellites,
            )
        except ValueError as e:
            print(f"Error parsing GPS data: {e}", file=sys.stderr)
            return GPS_readings()

    @staticmethod
    def _convert_to_decimal(raw: str, direction: str) -> Optional[float]:
        """Converts NMEA ddmm.mmmm coordinate to decimal degrees."""
        try:
            dot = raw.find(".")
            if dot == -1:
                raise ValueError("No decimal point in coordinate")
            degrees = int(raw[:dot - 2])
            minutes = float(raw[dot - 2:])
            decimal = degrees + minutes / 60.0
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except ValueError as e:
            print(f"Error converting coordinate: {e}", file=sys.stderr)
            return None

    @staticmethod
    def _safe_float(value: str) -> Optional[float]:
        """Safely converts a string to a float, returning None on error."""
        try:
            return float(value)
        except ValueError:
            return None

    @staticmethod
    def _safe_int(value: str) -> Optional[int]:
        """Safely converts a string to an int, returning None on error."""
        try:
            return int(value)
        except ValueError:
            return None


def main():
    """Main function to continuously read and display GPS data."""
    gps_reader = GPSReader()

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, gps_reader._signal_handler)
    signal.signal(signal.SIGTERM, gps_reader._signal_handler)

    if not gps_reader.connect():
