                logging.warning(f"Missing fields in GGA: {data}")
                return None
            try:
                lat_dec = self._convert_to_decimal(latitude, lat_dir)
                lon_dec = self._convert_to_decimal(longitude, lon_dir)
            except ValueError as e:
                logging.error(f"Error converting coordinates: {e}")
                return None
            return {
                'utc_time': utc_time,
                'latitude': lat_dec,
                'latitude_dir': lat_dir,
                'longitude': lon_dec,
                'longitude_dir': lon_dir,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
