import signal
import sys
import threading
import json
from flask import Flask, Response, request, jsonify
import serial

app = Flask(__name__)

# In-memory data store
class DataManager:
    def __init__(self):
        self.data = [
            {"id": 1, "name": "Sample Item 1", "done": False},
            {"id": 2, "name": "Sample Item 2", "done": True},
        ]
        self.lock = threading.Lock()

    def get_all(self):
        with self.lock:
            return list(self.data)

    def get_by_id(self, item_id):
        with self.lock:
            for item in self.data:
                if item["id"] == item_id:
                    return item
            return None

    def create(self, name, done):
        if not name or not isinstance(name, str):
            return None, 400
        if not isinstance(done, bool):
            return None, 400
        with self.lock:
            new_id = self.data[-1]["id"] + 1 if self.data else 1
            new_item = {"id": new_id, "name": name, "done": done}
            self.data.append(new_item)
            return new_item, 201

# Serial communication class
class SerialCommunicator:
    def __init__(self, port="/dev/ttyUSB0", baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_port = None
        self.lock = threading.Lock()

    def open(self):
        with self.lock:
            if self.serial_port and self.serial_port.is_open:
                return True
            try:
                self.serial_port = serial.Serial(
                    self.port, self.baudrate, timeout=1
                )
                return True
            except serial.SerialException as e:
                print(f"Error opening serial port: {e}", file=sys.stderr)
                self.serial_port = None
                return False

    def close(self):
        with self.lock:
            if self.serial_port and self.serial_port.is_open:
                try:
                    self.serial_port.close()
                except serial.SerialException as e:
                    print(f"Error closing serial port: {e}", file=sys.stderr)
            self.serial_port = None

    def send(self, command):
        with self.lock:
            if not self.serial_port or not self.serial_port.is_open:
                return False
            try:
                self.serial_port.write(command.encode("ascii"))
                self.serial_port.flush()
                return True
            except serial.SerialException as e:
                print(f"Error sending command: {e}", file=sys.stderr)
                return False

    def receive_line(self):
        with self.lock:
            if not self.serial_port or not self.serial_port.is_open:
                return None
            try:
                line = self.serial_port.readline()
                if not line:
                    return None
                return line.decode("ascii", errors="replace").strip()
            except serial.SerialException as e:
                print(f"Error receiving data: {e}", file=sys.stderr)
                return None

    def __enter__(self):
        if not self.open():
            raise RuntimeError("Failed to open serial port")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

