def get_version():
    if not serial_comm.open():
        serial_comm.close()
        return Response("Serial port error", status=500, mimetype="text/plain")
    try:
        if not serial_comm.send("*IDN?\n"):
            serial_comm.close()
            return Response("Serial communication error", status=502, mimetype="text/plain")
        response = serial_comm.receive_line()
        if response is None:
            serial_comm.close()
            return Response("No response from device", status=504, mimetype="text/plain")
        return Response(response, mimetype="text/plain")
    except Exception as e:
        serial_comm.close()
        return Response(f"Error: {e}", status=500, mimetype="text/plain")
    finally:
        serial_comm.close()

