import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'power_consumption.log'

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_power(power_value):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Power: {power_value} W'
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(log_entry + '\n')
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f'OS error opening serial port: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue
                try:
                    power = float(line)
                    log_power(power)
                except ValueError:
                    print(f'Invalid data received: {line}', file=sys.stderr)
            except serial.SerialException as e:
                print(f'Serial read error: {e}', file=sys.stderr)
                break
            except OSError as e:
                print(f'OS read error: {e}', file=sys.stderr)
                break
    finally:
        if ser.is_open:
            ser.close()
        print('Serial port closed. Exiting.')

if __name__ == '__main__':
    main()

