from flask import Flask, jsonify, request, Response
import serial
import time
import json
import sys

app = Flask(__name__)

# In-memory data store
data_store = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": True},
]

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1.0


def get_serial_connection():
    """Open and return a serial connection, or None on failure."""
    try:
        conn = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT,
        )
        if not conn.is_open:
            conn.open()
        return conn
    except serial.SerialException as exc:
        print(f"Serial error opening {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"Unexpected error opening serial port: {exc}", file=sys.stderr)
        return None


@app.route('/version', methods=['GET'])
def version():
    """Query the connected SCPI instrument for its identification string."""
    conn = get_serial_connection()
    if conn is None:
        return Response(
            "Serial port initialization failed",
            status=503,
            mimetype='text/plain',
        )

    try:
        conn.reset_input_buffer()
        conn.reset_output_buffer()
        conn.write(b'*IDN?\n')
        time.sleep(0.1)

        raw = conn.read(conn.in_waiting or 4096)
        if not raw:
            return Response(
                "No response from instrument",
                status=503,
                mimetype='text/plain',
            )

        text = raw.decode('ascii', errors='replace').replace('\n', '<br>')
        return Response(text, mimetype='text/html')
    except serial.SerialException as exc:
        print(f"Serial communication error: {exc}", file=sys.stderr)
        return Response(
            f"Serial communication error: {exc}",
            status=503,
            mimetype='text/plain',
        )
    except Exception as exc:
        print(f"Unexpected error during serial read: {exc}", file=sys.stderr)
        return Response(
            f"Unexpected error: {exc}",
            status=503,
            mimetype='text/plain',
        )
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.route('/getdata', methods=['GET'])
def get_data():
    """Return the full data store as JSON."""
    return jsonify(data_store)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set(item_id):
    """Return the item with the given id, or 404 if not found."""
    item = next((i for i in data_store if i['id'] == item_id), None)
    if item is None:
        return jsonify({'error': 'Item not found'}), 404
    return jsonify(item)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def get_post(item_id, name):
    """Append a new item with the given id and name, return updated list."""
    new_item = {'id': item_id, 'name': name, 'done': False}
    data_store.append(new_item)
    return jsonify(data_store)


@app.route('/postjson', methods=['POST'])
def post_json():
    """Create a new item from JSON/form data, return updated list."""
    try:
        if request.is_json:
            content = request.get_json(silent=True)
        else:
            content = request.form.to_dict()

        if not content:
            return jsonify({'error': 'No data provided'}), 400

        new_item = {'id': len(data_store) + 1, 'name': ''}
        if 'name' in content:
            new_item['name'] = str(content['name'])
        new_item['done'] = False
        if 'done' in content:
            new_item['done'] = bool(content['done'])

        data_store.append(new_item)
        return jsonify(data_store)

    except Exception as exc:
        print(f"Error processing JSON data: {exc}", file=sys.stderr)
        return jsonify({'error': 'Invalid data'}), 400


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

