COMMAND_PREFIX = "X"
TRANSMISSION_DELAY = 0.1  # seconds


def send_command(ser, command):
    """Send a command to the Bluetooth device.

    Args:
        ser: An active serial.Serial object.
        command: The command string to send.

    Raises:
        RuntimeError: If there is an error during transmission.
    """
    try:
        payload = COMMAND_PREFIX + command + "\n"
        bytes_written = ser.write(payload.encode("utf-8"))
        ser.flush()
        if bytes_written != len(payload):
            raise RuntimeError(
                f"Incomplete write: expected {len(payload)} bytes, wrote {bytes_written}"
            )
        time.sleep(TRANSMISSION_DELAY)
    except serial.SerialException as e:
        raise RuntimeError(f"Serial transmission error: {e}") from e
    except OSError as e:
        raise RuntimeError(f"OS-level I/O error during transmission: {e}") from e


def main():
    """Main function to handle user input and send commands."""
    ser = None
    try:
        ser = serial.Serial(
            port=BLUETOOTH_PORT,
            baudrate=BLUETOOTH_BAUDRATE,
            timeout=1.0,
            write_timeout=1.0,
        )
        print(f"Connected to {BLUETOOTH_PORT} at {BLUETOOTH_BAUDRATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == "exit":
                break

            try:
                send_command(ser, user_command)
                print(f"Sent: {user_command}")
            except RuntimeError as e:
                print(f"Error: {e}", file=sys.stderr)

    except serial.SerialException as e:
        print(f"Serial connection error: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial connection closed.")


if __name__ == "__main__":
    main()
